/* WAKHAN 2.0 — theme system. App colour: WAKHAN purple (dark) + ice white with blue (light). One place for all colours (design tokens).
   Loaded first in <head> so the app never flashes the wrong theme.
   The server decides which themes you may use; this file only paints. */
(()=>{'use strict';if(window.WKT)return;
const T={
 free_dark:{tier:'free',bg:'#10091C',surface:'#1E1232',surface2:'#302047',border:'#68449A',text:'#F2F7FF',text2:'#C8B6E3',accent:'#9E6FFF',onAccent:'#140820',disabled:'#5B4A72',nav:'#150C25',xpTrack:'#42305D',xpFill:'#AB74FF',glow:'#A855F7',g1:'#9040FF',g2:'#5B21B6',anim:true,dark:true},
 free_light:{tier:'free',bg:'#E8ECF1',surface:'#F8FAFC',surface2:'#EEF2F6',border:'#CFD6DF',text:'#12161C',text2:'#5A6472',accent:'#1F5EFF',onAccent:'#FFFFFF',disabled:'#A9B2BE',nav:'#F8FAFC',xpTrack:'#D6DDE7',xpFill:'#1F5EFF',glow:'#5B8CFF',g1:'#3B7BFF',g2:'#1240C8',anim:true,dark:false},
 vip_purple:{tier:'vip',bg:'#10091C',surface:'#1E1232',surface2:'#302047',border:'#68449A',text:'#FFFFFF',text2:'#C8B6E3',accent:'#AB74FF',onAccent:'#140820',disabled:'#5B4A72',nav:'#150C25',xpTrack:'#42305D',xpFill:'#AB74FF',glow:'#A855F7',g1:'#9040FF',g2:'#5B21B6',anim:true,dark:true},
 vip_ice:{tier:'vip',bg:'#051321',surface:'#0D2438',surface2:'#18364D',border:'#286282',text:'#F4FBFF',text2:'#A9C9DD',accent:'#42C8FF',onAccent:'#062033',disabled:'#3D5A70',nav:'#081A2C',xpTrack:'#214963',xpFill:'#42C8FF',glow:'#00BFFF',g1:'#42C8FF',g2:'#0878C8',anim:true,dark:true},
 premium_emerald:{tier:'premium',bg:'#041A17',surface:'#0C2925',surface2:'#174139',border:'#286F60',text:'#F0FFF9',text2:'#A5D9C9',accent:'#21D6A2',onAccent:'#05251A',disabled:'#3B5F56',nav:'#06211D',xpTrack:'#255347',xpFill:'#21D6A2',glow:'#00E5A8',g1:'#21D6A2',g2:'#087C65',anim:true,dark:true},
 premium_ruby:{tier:'premium',bg:'#1A080E',surface:'#301019',surface2:'#471C28',border:'#913B50',text:'#FFF5F7',text2:'#E7AEBB',accent:'#FF657B',onAccent:'#310810',disabled:'#6A3A46',nav:'#220A12',xpTrack:'#662B3B',xpFill:'#FF657B',glow:'#FF355E',g1:'#FF657B',g2:'#A30D37',anim:true,dark:true},
 royal_gold:{tier:'royal',bg:'#100D07',surface:'#231B10',surface2:'#342716',border:'#80622C',text:'#FFF8E8',text2:'#D6C29B',accent:'#F5CC73',onAccent:'#291C09',disabled:'#5E5038',nav:'#17120A',xpTrack:'#514025',xpFill:'#F5CC73',glow:'#FFD76A',g1:'#F5CC73',g2:'#A96519',anim:true,dark:true},
 royal_cosmic:{tier:'royal',bg:'#06091A',surface:'#141631',surface2:'#22254A',border:'#6256A0',text:'#F8F7FF',text2:'#C4BCE8',accent:'#B794F4',onAccent:'#1B1034',accent2:'#32E6D3',disabled:'#4A4670',nav:'#0B0E24',xpTrack:'#39345B',xpFill:'#B794F4',glow:'#A78BFA',g1:'#7C3AED',g2:'#21BFAE',anim:true,dark:true}};
const ORDER=['free_dark','free_light','vip_purple','vip_ice','premium_emerald','premium_ruby','royal_gold','royal_cosmic'];
const KEY='wkt_theme',ACT='wkt_active';
const get=k=>{try{return localStorage.getItem(k)}catch(e){return null}};
const put=(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}};
/* status colours never come from the theme */
const STATUS={ok:'#22C55E',warn:'#F59E0B',err:'#EF4444',info:'#3B82F6'};
function css(id){const t=T[id]||T.free_dark;
 /* the old screens (rebuilt one by one) are designed for dark backgrounds, so in the light theme they keep dark tokens */
 const old=t.dark?t:T.free_dark;const oldAccent=old.accent;
 return `--wk-bg:${t.bg};--wk-surface:${t.surface};--wk-surface2:${t.surface2};--wk-border:${t.border};--wk-text:${t.text};--wk-text2:${t.text2};--wk-accent:${t.accent};--wk-on-accent:${t.onAccent};--wk-accent2:${t.accent2||t.accent};--wk-disabled:${t.disabled};--wk-nav:${t.nav};--wk-xp-track:${t.xpTrack};--wk-xp-fill:${t.xpFill};--wk-glow:${t.glow};--wk-g1:${t.g1};--wk-g2:${t.g2};--wk-ok:${STATUS.ok};--wk-warn:${STATUS.warn};--wk-err:${STATUS.err};--wk-info:${STATUS.info};--wk-shadow:${t.dark?'0 8px 24px rgba(0,0,0,.35)':'0 4px 14px rgba(24,24,27,.08)'};`+
  `--bg:${old.bg};--bg2:${old.surface};--card:${old.surface};--card2:${old.surface2};--ln:${old.border};--txt:${old.text};--mut:${old.text2};--a1:${oldAccent};--a2:${old.g2};--a3:${old.accent2||old.g1};--ok:${STATUS.ok};--bad:${STATUS.err}`}
const st=document.createElement('style');st.id='wkt-css';
st.textContent=ORDER.map(id=>`html[data-wkt=${id}],html[data-wkt=${id}] body,html[data-wkt=${id}] body[data-th]{${css(id)}}`).join('\n')+
 `\nhtml[data-wkt] body{background:var(--wk-bg)!important;color:var(--wk-text)}html[data-wkt]{color-scheme:dark}html[data-wkt=free_light]{color-scheme:light}
html[data-wkt=free_light] #nav.tb2{background:rgba(248,250,252,.94)!important;-webkit-backdrop-filter:blur(18px) saturate(1.2)!important;backdrop-filter:blur(18px) saturate(1.2)!important;border:1px solid #D3DAE3!important;box-shadow:0 10px 28px rgba(20,30,50,.13)!important;color:#4A5260!important}html[data-wkt=free_light] #nav.tb2>button{color:#4A5260!important}html[data-wkt=free_light] #nav.tb2>button.on{color:#1F5EFF!important}html[data-wkt=free_light] #nav.tb2 .tb2-lens{background:#DCE4F0!important}html[data-wkt=free_light] #nav.tb2>button .wm75-art{filter:brightness(0) invert(.42)}html[data-wkt=free_light] #nav.tb2>button.on .wm75-art{filter:brightness(0) saturate(100%) invert(27%) sepia(98%) saturate(3500%) hue-rotate(222deg) brightness(101%)}html[data-wkt=free_light] #nav.tb2>button .wm76-icon,html[data-wkt=free_light] #nav.tb2>button>span{color:#4A5260!important;fill:none}html[data-wkt=free_light] #nav.tb2>button.on .wm76-icon,html[data-wkt=free_light] #nav.tb2>button.on>span{color:#1F5EFF!important}html[data-wkt=free_light] #nav.tb2>button.on>span{font-weight:700}html[data-wkt=free_light] #nav .wm76-unread{background:#1F5EFF!important;color:#fff!important}html[data-wkt=free_light] #wk52-pop .wk52-pok{background:#1F5EFF!important;color:#fff!important}html[data-wkt=free_light] #wk52-pop .wm70-avatar-fallback{background:#14181F!important;color:#fff!important}html[data-wkt=free_light] #wk52-pop .wk52-psee{color:#4A5260!important;background:#E8ECF1!important}html[data-wkt=free_light] #wk52-pop{background:rgba(255,255,255,.96)!important;color:#12161C!important;border-color:#D3DAE3!important}
html.wkt-switch body *{transition:background-color .25s ease,border-color .25s ease,color .25s ease!important}
@media (prefers-reduced-motion:reduce){html.wkt-switch body *{transition:none!important}}`;
(document.head||document.documentElement).appendChild(st);
function paint(id,anim){if(!T[id])id='free_dark';const h=document.documentElement;
 if(anim){h.classList.add('wkt-switch');setTimeout(()=>h.classList.remove('wkt-switch'),320)}
 h.dataset.wkt=id;h.classList.toggle('wkt-light',!T[id].dark);
 try{const m=document.querySelector('meta[name=theme-color]')||Object.assign(document.createElement('meta'),{name:'theme-color'});m.content=T[id].bg;if(!m.parentNode)document.head.appendChild(m)}catch(e){}
 try{if(window.WAKHAN_NATIVE_N1&&WAKHAN_NATIVE_N1.bars)WAKHAN_NATIVE_N1.bars(T[id].bg)}catch(e){}
 try{document.querySelectorAll('img[src*="/s/wk2/"]').forEach(i=>{const s=i.getAttribute('src'),n=WKT.art(s);if(n!==s)i.setAttribute('src',n)})}catch(e){}
 window.dispatchEvent(new CustomEvent('wkt',{detail:id}))}
/* first paint: the last theme the server allowed (no flash) */
/* «مطابق گوشی» (follow the phone) lives on this phone only and never changes the account: the free theme follows the phone's
   dark/light setting. On by default until the person picks a theme themselves (server says theme.set). Paid themes are never changed. */
const phoneTheme=()=>{try{return matchMedia('(prefers-color-scheme: dark)').matches?'free_dark':'free_light'}catch(e){return 'free_dark'}};
const autoOn=()=>{const v=get('wkt_auto');return v==='1'?true:v==='0'?false:get('wkt_set')!=='1'};
const resolve=a=>{a=a||'free_dark';return autoOn()&&/^free_/.test(a)?phoneTheme():a};
paint(resolve(get(ACT)),false);
let preview=null;
try{matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(!preview)paint(resolve(get(ACT)),true)})}catch(e){}
const WKT=window.WKT={themes:T,order:ORDER,status:STATUS,
 active:()=>document.documentElement.dataset.wkt,
 chosen:()=>get(KEY)||'free_dark',
 /* the server answer decides what is shown */
 apply(server){if(!server)return;const a=server.active||'free_dark';put(ACT,a);if(server.chosen)put(KEY,server.chosen);if('set' in server)put('wkt_set',server.set?'1':'0');if(!preview)paint(resolve(a),true)},
 auto:autoOn,
 setAuto(v){put('wkt_auto',v?'1':'0');if(!preview)paint(resolve(get(ACT)),true)},
 preview(id){preview=id;paint(id,true)},
 endPreview(){preview=null;paint(resolve(get(ACT)),true)},
 /* ice-white theme: the big pictures have ice-blue copies in /s/wk2/light/ (shop items keep their real look) */
 art(p){const o=String(p||''),b=o.replace('/s/wk2/light/','/s/wk2/');if(!/^\/s\/wk2\/(bk|sub|st)\/(?!i_)/.test(b))return o;return document.documentElement.dataset.wkt==='free_light'?b.replace('/s/wk2/','/s/wk2/light/'):b},
 async sync(){try{const r=await api('/api/app/tier');if(r&&r.ok){WKT.apply(r.theme);WKT.last=r;return r}}catch(e){}return null},
 async choose(id){const r=await api('/api/app/theme',{theme:id});if(r&&r.ok){preview=null;WKT.apply(r.theme)}return r}};
/* after sign-in, ask the server once (keeps several phones in step) */
let tries=0;const iv=setInterval(()=>{tries++;if(typeof api==='function'&&(window.INIT||window.WKA)){clearInterval(iv);WKT.sync()}else if(tries>60)clearInterval(iv)},500);
/* ---- WAKHAN 2.0 languages: 15 languages. Dari and English live in the pages; every other language is a small pack
   (/s/wk2/i18n/<code>.json) that is downloaded once, kept on the phone, and used by all «من» pages. */
(()=>{const LANGS=['fa','ps','en','de','ar','tr','ur','hi','ru','es','fr','pt','zh','id','uz'],RTL=['fa','ps','ar','ur'],PACKV='5';
 const raw=()=>{let l='en';try{l=(window.ME3_LANG||localStorage.getItem('wk_native_lang_override')||localStorage.getItem('wm13_lang')||document.documentElement.lang||'en').slice(0,2).toLowerCase()}catch(e){}if(l==='in')l='id';return LANGS.includes(l)?l:'en'};
 window.WK2L=raw;window.WK2_RTL=l=>RTL.includes(l||raw());window.WK2_I18N=window.WK2_I18N||{};
 window.WK2P=(mod,k)=>{const p=WK2_I18N[raw()];const m=p&&p[mod];const v=m&&m[k];return typeof v==='string'||Array.isArray(v)?v:undefined};
 const want=l=>!['fa','en'].includes(l);
 function load(l){if(!want(l)||WK2_I18N[l])return;const key='wk2_i18n_'+l+'_'+PACKV;
  try{const c=localStorage.getItem(key);if(c){WK2_I18N[l]=JSON.parse(c);return}}catch(e){}
  fetch(new URL('/s/wk2/i18n/'+l+'.json?v='+PACKV,document.baseURI).href).then(r=>r.ok?r.json():null).then(j=>{if(!j)return;WK2_I18N[l]=j;try{localStorage.setItem(key,JSON.stringify(j))}catch(e){}
   try{window.dispatchEvent(new CustomEvent('wk2-i18n',{detail:l}));if(window.ME3&&ME3.reload)ME3.reload()}catch(e){}}).catch(()=>{})}
 const dir=()=>{try{const r=RTL.includes(raw()),h=document.documentElement;h.style.setProperty('--wk-dir',r?'rtl':'ltr');h.setAttribute('data-wkdir',r?'rtl':'ltr')}catch(e){}};
 try{const s=document.createElement('style');s.id='wk2-dir-css';s.textContent='html[data-wkdir=ltr] .wk-flip{transform:scaleX(-1)}html[data-wkdir=ltr] .s3-bk .wk-flip,html[data-wkdir=ltr] .st-pg .wk-flip,html[data-wkdir=ltr] .st-pack .ch .wk-flip{transform:none}html[data-wkdir=ltr] .bk-info img{left:auto;right:-6px;width:40%}html[data-wkdir=ltr] .bk-info .tx{padding:14px 0 12px 14px;margin-left:0;margin-right:auto}html[data-wkdir=ltr] .st-ban .bk-live{left:auto!important;right:0!important}';document.head.appendChild(s)}catch(e){}
 dir();load(raw());let last=raw();setInterval(()=>{const l=raw();if(l!==last){last=l;dir();load(l)}},2000)})();

})();

(function(){if(window.__wkGcs)return;window.__wkGcs=1;try{var real=window.getComputedStyle.bind(window),C={k:"",v:{}};
function key(){var d=document.documentElement,b=document.body;return (d.className||"")+"|"+(d.getAttribute("style")||"")+"|"+(d.dataset.theme||"")+"|"+(b?(b.dataset.wnTheme||"")+"|"+[].filter.call(b.classList,function(c){return /theme|dawn|midnight|orbit|light|dark/.test(c)}).join(","):"")}
window.getComputedStyle=function(el,ps){if(el&&el===document.body&&!ps){var cs=real(el),k=key();if(C.k!==k)C={k:k,v:{}};var c=C;
return new Proxy(cs,{get:function(t,p){if(p==="getPropertyValue")return function(n){n=String(n);if(n.indexOf("--")===0){if(!(n in c.v))c.v[n]=t.getPropertyValue(n);return c.v[n]}return t.getPropertyValue(n)};var v=t[p];return typeof v==="function"?v.bind(t):v}})}return real(el,ps)}}catch(e){}})();

