if(CS.playing&&st!==1&&st!==3){YTP.playVideo();if(!blockedSince)blockedSince=Date.now();else if(Date.now()-blockedSince>2500){const ov=$("#scov");ov.style.display="flex";ov.className="scov tap";ov.innerHTML=`${ae("▶️")}<div>${t("tap_sound")}</div>`;ov.onclick=()=>{YTP.playVideo();ov.style.display="none";blockedSince=0}}}else blockedSince=0;
