const VC={on:false,mute:true,stream:null,pcs:{},ver:0,tok:0,ice:null,members:[],spk:{},actx:null,cid:null};
const sl=ms=>new Promise(r=>setTimeout(r,ms));
async function vcJoin(){if(!CS||CS.mine<0)return toast(t("only_seated"));hap("medium");
try{VC.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}})}catch(e){return toast(t("mic_denied"))}
VC.stream.getAudioTracks().forEach(x=>x.enabled=false);VC.mute=true;VC.on=true;VC.cid=CID;VC.ver=0;
const j=await api("/api/turn");VC.ice=j.ice||[{urls:"stun:stun.l.google.com:19302"}];
const r=await api("/api/cv/"+CID,{a:"join"});if(!r.ok){vcLeave(true);return toast(t(r.err==="seat"?"only_seated":"err"))}
vcMeter(ME.me.id,VC.stream);vcLoop();drawHall()}
function vcLeave(silent){if(!VC.on&&!VC.stream)return;const cid=VC.cid;VC.on=false;VC.tok++;Object.values(VC.pcs).forEach(p=>{try{p.pc.close()}catch(e){}});VC.pcs={};VC.stream?.getTracks().forEach(x=>x.stop());VC.stream=null;VC.spk={};VC.members=[];document.querySelectorAll(".vca").forEach(a=>a.remove());duck();if(cid&&!silent)api("/api/cv/"+cid,{a:"leave"});if($("#hall"))drawHall()}
function vcMute(){if(!VC.on)return;VC.mute=!VC.mute;VC.stream.getAudioTracks().forEach(x=>x.enabled=!VC.mute);if(VC.mute)VC.spk[ME.me.id]=false;api("/api/cv/"+VC.cid,{a:"mute",m:VC.mute?1:0});hap("medium");drawHall()}
async function vcLoop(){const tok=++VC.tok;while(VC.on&&tok===VC.tok){try{const j=await api(`/api/cv/${VC.cid}/poll?v=${VC.ver}`);if(tok!==VC.tok)return;if(!j.ok){await sl(2000);continue}VC.ver=j.ver;VC.members=j.members||[];for(const m of j.msgs||[]){try{await vcSig(m.from,m.d)}catch(e){}}vcSync()}catch(e){await sl(2000)}}}
function vcSync(){const me=ME.me.id,ids=VC.members.map(m=>m.id).filter(i=>i!==me);
for(const id of Object.keys(VC.pcs))if(!ids.includes(+id)){try{VC.pcs[id].pc.close()}catch(e){}document.getElementById("vca"+id)?.remove();delete VC.pcs[id];VC.spk[id]=false}
for(const id of ids)if(!VC.pcs[id]&&me<id)vcCall(id)}
function wmqPlayVoice(audio){
 if(!VC.on||audio.dataset.room!==VC.cid)return Promise.resolve(false);
 return audio.play().then(()=>{audio.dataset.blocked='0';SX.audioBlocked=[...document.querySelectorAll('.vca')].some(node=>node.dataset.room===VC.cid&&node.dataset.blocked==='1');if(typeof drawHall==='function')drawHall();return true}).catch(error=>{
  if(!VC.on||audio.dataset.room!==VC.cid)return false;
  audio.dataset.blocked='1';SX.audioBlocked=true;if(typeof drawHall==='function')drawHall();return false;
 });
}
function wmqResumeVoiceAudio(){
 if(!VC.on||SX.speaker===false)return false;
 VC.actx?.resume().catch(()=>{});
 let pending=false;for(const audio of document.querySelectorAll('.vca')){
  if(audio.dataset.room!==VC.cid||!audio.srcObject)continue;audio.muted=false;
  if(audio.paused||audio.dataset.blocked==='1'){pending=true;void wmqPlayVoice(audio)}
 }
 return pending;
}
function vcPc(id){
 const room=VC.cid,pc=new RTCPeerConnection(window.WakhanVoiceRoutes?.configuration(VC.ice,{room,peer:id})||{iceServers:VC.ice});
 VC.stream.getTracks().forEach(track=>pc.addTrack(track,VC.stream));
 pc.onicecandidate=event=>{if(event.candidate&&VC.on&&VC.cid===room&&VC.pcs[id]?.pc===pc)api('/api/cv/'+room,{a:'sig',to:id,d:{c:event.candidate.toJSON?event.candidate.toJSON():event.candidate}})};
 pc.ontrack=event=>{
  if(!VC.on||VC.cid!==room||VC.pcs[id]?.pc!==pc||event.track?.kind!=='audio')return;
  const stream=event.streams?.[0]||new MediaStream([event.track]);let audio=document.getElementById('vca'+id);
  if(!audio){audio=document.createElement('audio');audio.id='vca'+id;audio.className='vca';audio.autoplay=true;audio.setAttribute('playsinline','');document.body.append(audio)}
  audio.dataset.room=room;audio.muted=SX.speaker===false;if(audio.srcObject!==stream)audio.srcObject=stream;
  void wmqPlayVoice(audio);vcMeter(id,stream);
 };
 pc.onconnectionstatechange=()=>{if(pc.connectionState==='failed'&&VC.pcs[id]?.pc===pc){pc.close();delete VC.pcs[id];setTimeout(vcSync,1500)}};
 VC.pcs[id]={pc,q:[]};return pc;
}
async function vcCall(id){const pc=vcPc(id);const o=await pc.createOffer();await pc.setLocalDescription(o);api("/api/cv/"+VC.cid,{a:"sig",to:id,d:{sdp:{type:pc.localDescription.type,sdp:pc.localDescription.sdp}}})}
async function vcSig(from,d){let P=VC.pcs[from];
if(d.sdp){if(d.sdp.type==="offer"){if(P){try{P.pc.close()}catch(e){}}const pc=vcPc(from);P=VC.pcs[from];await pc.setRemoteDescription(d.sdp);const a=await pc.createAnswer();await pc.setLocalDescription(a);api("/api/cv/"+VC.cid,{a:"sig",to:from,d:{sdp:{type:pc.localDescription.type,sdp:pc.localDescription.sdp}}})}else if(P){await P.pc.setRemoteDescription(d.sdp)}
if(P){for(const c of P.q){try{await P.pc.addIceCandidate(c)}catch(e){}}P.q=[]}}
else if(d.c&&P){if(P.pc.remoteDescription){try{await P.pc.addIceCandidate(d.c)}catch(e){}}else P.q.push(d.c)}}
function vcMeter(id,stream){try{VC.actx=VC.actx||new (window.AudioContext||window.webkitAudioContext)();VC.actx.resume();const an=VC.actx.createAnalyser();an.fftSize=256;VC.actx.createMediaStreamSource(stream).connect(an);const buf=new Uint8Array(an.frequencyBinCount);let last=0;
const tick=()=>{if(!VC.on)return;an.getByteFrequencyData(buf);let s=0;for(const v of buf)s+=v;const on=s/buf.length>16&&!(id===ME.me.id&&VC.mute);const now=performance.now();if(on!==!!VC.spk[id]&&(on||now-last>500)){VC.spk[id]=on;spkDraw(id);duck()}if(on)last=now;requestAnimationFrame(tick)};tick()}catch(e){}}
function spkDraw(id){document.querySelectorAll(`.seat[data-u="${id}"]`).forEach(e=>e.classList.toggle("spk",!!VC.spk[id]))}
function duck(){try{const any=Object.entries(VC.spk).some(([k,v])=>v&&+k!==ME.me.id);YTP?.setVolume?.(any?35:100)}catch(e){}}
