let WM_OFFER=null,WM_OFFSET=0,WM_PROMO_BUSY=null,WM_PROMO_FETCHED=0,WM_END_TIMER=null;
const WM_CHECKOUT={quote:null,seq:0,timer:null,proof:"",busy:false};
function wmNow(){return Math.floor((Date.now()+WM_OFFSET)/1000)}
function wmDiscount(){return WM_OFFER&&WM_OFFER.active&&wmNow()<WM_OFFER.end?WM_OFFER.discount:0}
function wmAmount(value,cur=SC){
 const n=Number(value);if(!Number.isFinite(n))return "—";
 const digits=cur==="irt"?0:cur==="usdt"||cur==="ton"?4:2;
 const text=new Intl.NumberFormat("en-US",{minimumFractionDigits:cur==="eur"||cur==="usd"||cur==="afn"?2:0,maximumFractionDigits:digits}).format(n);
 const unit=cur==="afn"?"افغانی":CSIGN[cur];
 return '<bdi dir="ltr">'+text+' '+h(unit||cur.toUpperCase())+'</bdi>';
}
function wmCampaignAccept(j){
 if(!j||!j.campaign)return;
 WM_OFFER=j.campaign;WM_OFFSET=WM_OFFER.server_now*1000-Date.now();WM_PROMO_FETCHED=Date.now();
 clearTimeout(WM_END_TIMER);
 const wait=(WM_OFFER.end-wmNow())*1000;
 if(WM_OFFER.active&&wait>0)WM_END_TIMER=setTimeout(wmCampaignEnd,Math.min(wait+150,86400000));
 wmRefreshPromos();
}
function wmPromoMarkup(compact=false){
 if(!wmDiscount())return "";
 const left=Math.max(0,Math.ceil((WM_OFFER.end-wmNow())/86400));
 const line=wmTx("offerline");
 if(compact)return `<button type="button" class="wm-promo-ticker" onclick="go('s')" aria-label="${h(wmTx("buy"))}"><b class="wm-promo-badge">70%</b><span class="wm-ticker-window"><span class="wm-ticker-track"><span dir="${LG==="en"?"ltr":"rtl"}">${h(line)}</span><span aria-hidden="true" dir="${LG==="en"?"ltr":"rtl"}">${h(line)}</span></span></span></button>`;
 return `<div class="wm-promo-card"><div class="wm-offer-seal">70<span>%</span></div><div><b>${h(wmTx("offer"))}</b><p>${h(line)}</p><small>${left} ${h(wmTx("left"))}</small></div></div>`;
}
function wmRefreshPromos(){document.querySelectorAll("[data-wm-promo]").forEach(e=>e.innerHTML=wmPromoMarkup(e.dataset.wmPromo==="ticker"))}
async function wmCampaignEnd(){
 if(WM_OFFER&&wmNow()<WM_OFFER.end){wmCampaignAccept({campaign:{...WM_OFFER,server_now:wmNow()}});return}
 wmRefreshPromos();
 if(TAB==="s"){await rShop();toast(wmTx("expired"))}else wmEnsureOffer(true);
}
async function wmEnsureOffer(force=false){
 if(!force&&Date.now()-WM_PROMO_FETCHED<60000){wmRefreshPromos();return}
 if(WM_PROMO_BUSY)return WM_PROMO_BUSY;
 WM_PROMO_BUSY=(async()=>{try{const j=await api("/api/shop");if(j.ok)wmCampaignAccept(j)}catch(e){}finally{WM_PROMO_BUSY=null}})();
 return WM_PROMO_BUSY;
}
function wmQuoteKey(){return [String(SG||""),SM,SC].join(":")}
function wmQuoteValid(){const q=WM_CHECKOUT.quote;return q&&q.key===wmQuoteKey()&&q.expires_at>wmNow()}
function wmInvalidateQuote(clearProof=false){
 WM_CHECKOUT.seq++;WM_CHECKOUT.quote=null;clearTimeout(WM_CHECKOUT.timer);
 if(clearProof)WM_CHECKOUT.proof="";
 const b=$("#wm-send");if(b)b.disabled=true;const status=$("#wm-quote-status");if(status)status.textContent=wmTx("quote_pending");
}
function wmSelectGroup(id){if(String(SG)!==String(id)){SG=String(id);wmInvalidateQuote(true)}drawShop()}
function wmSelectCurrency(c){if(SC!==c){SC=c;wmInvalidateQuote(true)}drawShop()}
function wmSelectMonth(n){SM=Math.max(1,Math.min(SH.max_months||36,Math.round(Number(n)||1)));wmInvalidateQuote();drawShop();requestAnimationFrame(()=>document.querySelector(".wm-checkout")?.scrollIntoView({behavior:"smooth",block:"start"}))}
function wmMonthLive(n){
 SM=Math.max(1,Math.min(SH.max_months||36,Math.round(Number(n)||1)));wmInvalidateQuote();
 const label=$("#wm-month-value");if(label)label.textContent=SM+" "+t("sh_month");const chosen=$("#wm-selected-month");if(chosen)chosen.textContent=SM+" "+t("sh_month");
 document.querySelectorAll("[data-wm-month]").forEach(e=>{const on=Number(e.dataset.wmMonth)===SM;e.classList.toggle("on",on);e.setAttribute("aria-pressed",String(on))});
