}
function wmDrawTotal(held=false){
 const e=$("#wm-total"),r=$("#wm-regular");if(!e||!SH)return;
 const q=held&&wmQuoteValid()?WM_CHECKOUT.quote:null;
 e.innerHTML=wmAmount(q?q.amount:SH.prices[SC][SM],SC);
 const normal=q?q.base_amount:SH.regular_prices[SC][SM];
 const discount=q?q.discount:wmDiscount();
 if(r)r.innerHTML=discount?'<s>'+wmAmount(normal,SC)+'</s> <span class="wm-off-chip">70% '+h(wmTx("off"))+'</span>':"";
}
function wmScheduleQuote(){clearTimeout(WM_CHECKOUT.timer);if(!SG||!payTo())return;WM_CHECKOUT.timer=setTimeout(wmFetchQuote,180)}
async function wmFetchQuote(){
 const status=$("#wm-quote-status"),send=$("#wm-send");
 if(!SG||!payTo())return;
 if(wmQuoteValid()){wmDrawTotal(true);if(status)status.textContent=wmTx("quote_held");if(send)send.disabled=false;return WM_CHECKOUT.quote}
 const seq=++WM_CHECKOUT.seq,key=wmQuoteKey();
 if(status)status.textContent=wmTx("quote_pending");if(send)send.disabled=true;
 try{
  const j=await api("/api/order",{action:"quote",g:SG,m:SM,c:SC});
  if(seq!==WM_CHECKOUT.seq||key!==wmQuoteKey()||TAB!=="s")return;
  if(!j.ok){if(status)status.textContent=wmTx(j.err)==j.err?t("err"):wmTx(j.err);return}
  wmCampaignAccept(j);WM_CHECKOUT.quote={...j,key};
  wmDrawTotal(true);
  if(status)status.textContent=wmTx("quote_held");
  if(send)send.disabled=false;
  return WM_CHECKOUT.quote;
 }catch(e){if(seq===WM_CHECKOUT.seq&&status)status.textContent=t("err")}
}
