 const j=await api("/api/shop");if(!j.ok)return;
 SH=j;wmCampaignAccept(j);
 const previousGroup=String(SG||"");
 if(!SG||!SH.groups.some(g=>String(g.id)===String(SG)))SG=SH.groups[0]?.id||null;
 if(previousGroup!==String(SG||""))wmInvalidateQuote(true);
 if(!SH.prices[SC]||!SH.payment_ready?.[SC])SC=["irt","ton","usdt","afn","eur","usd"].find(c=>SH.prices[c]&&SH.payment_ready?.[c])||SC;
 SM=Math.max(1,Math.min(SH.max_months||36,SM));
 drawShop();
}
