('#vbarw');if(vw)vw.innerHTML=vcBar();wmcOverlay();wmcSpeakers()};
function wmcOverlay(){const ov=$('#scov');if(!ov||!CS)return;ov.onclick=null;if(!CS.vid){ov.className='scov';ov.style.display='flex';ov.innerHTML=`${ae('🍿')}<div>${t('empty_yt')}</div>`;return}if(WMC.error){ov.className='scov';ov.style.display='flex';ov.innerHTML=`<div>${h(wmcT('yt_error'))}</div><button class="chip" onclick="wmcRetryVideo()">${wmcT('retry')}</button>`;return}if(!WMC.gesture||WMC.blocked){ov.className='scov tap';ov.style.display='flex';ov.innerHTML=`<button class="wmc-watch" onclick="wmcWatch()">${wmcIcon('play')}<span>${wmcT('watch')}</span></button>`;return}ov.style.display='none'}
async function wmcTakeSeat(){if(!CS||WMC.joining)return;const i=CS.seats.findIndex(x=>!x);if(i<0)return toast(t('full'));return cinSit(i)}
