hSearch=async function(){const el=$('#hq'),out=$('#yres');if(!el||!out)return;const q=el.value.trim();if(!q)return;el.blur();hap();const seq=++WMC.searchSeq;out.innerHTML=`<div class="ytg" style="margin-top:12px">${"<div class='skel' style='height:150px'></div>".repeat(4)}</div>`;try{const j=await api('/api/search?k=y&q='+encodeURIComponent(q));if(seq!==WMC.searchSeq||!$('#yres'))return;CRES=(j.items||[]).filter(v=>/^[\w-]{11}$/.test(v.id));drawYRes();if(!CRES.length)out.textContent=t('nores');if(WMC.expanded)wmcExpand(false);out.scrollIntoView?.({behavior:'smooth',block:'nearest'})}catch(e){if(seq===WMC.searchSeq)out.textContent=t('err')}};
ytMake=function(){if(!$('#yt')||YTP)return;const epoch=WMC.epoch;YTP=new YT.Player('yt',{host:NX.ytHost||'https://www.youtube.com',playerVars:{hl:'en',widget_referrer:location.href,playsinline:1,controls:1,rel:0,disablekb:1,fs:0,origin:location.origin},events:{onReady:()=>{if(epoch!==WMC.epoch)return;YTOK=true;WMC.ready=true;cinApply();wmcOverlay()},onAutoplayBlocked:()=>{if(epoch!==WMC.epoch)return;WMC.blocked=true;wmcOverlay()},onStateChange:e=>{if(epoch!==WMC.epoch)return;if(typeof nfYoutubeState==='function')nfYoutubeState(e.data,epoch);if(e.data===1){WMC.blocked=false;blockedSince=0;wmcOverlay()}if(e.data===0&&CS?.mine>=0&&CS.playing&&YTP?.getVideoData?.()?.video_id===CS.vid){const duration=Number(YTP.getDuration?.());if(duration>0&&Number(YTP.getCurrentTime?.())>=duration-2)wmcState(CID,{a:'end'})}},onError:event=>{if(epoch!==WMC.epoch)return;nxYtError(event.data)}}})};
function wmcRetryVideo(){WMC.error='';WMC.loaded='';WMC.gesture=true;WMC.blocked=false;cinApply();wmcOverlay()}
function wmcWatch(){WMC.gesture=true;WMC.blocked=false;WMC.error='';wmcResumeAudio();try{VC.actx?.resume?.();if(YTP&&YTOK&&CS?.vid){const cur=YTP.getVideoData?.()?.video_id;if(cur!==CS.vid){const fn=CS.playing?'loadVideoById':'cueVideoById';YTP[fn]({videoId:CS.vid,startSeconds:cExp()});YTP.unMute?.()}else{YTP.seekTo(cExp(),true);YTP.unMute?.();if(CS.playing)YTP.playVideo();else YTP.pauseVideo()}blockedSince=Date.now()}}catch(e){}wmcOverlay()}
unlockYT=wmcWatch;
cinApply=function(){if(!YTP||!YTOK||!CS?.vid)return;try{const cur=YTP.getVideoData?.()?.video_id;const expected=Math.max(0,cExp());if(cur!==CS.vid){WMC.error='';if(WMC.loaded===CS.vid&&Date.now()-(WMC.loadAt||0)<4000)return;WMC.loaded=CS.vid;WMC.loadAt=Date.now();if(CS.playing&&WMC.gesture&&!WMC.blocked)YTP.loadVideoById({videoId:CS.vid,startSeconds:expected});else YTP.cueVideoById({videoId:CS.vid,startSeconds:expected});wmcOverlay();return}const st=YTP.getPlayerState();if(Math.abs(Number(YTP.getCurrentTime())-expected)>2.5&&st!==3)YTP.seekTo(expected,true);if(!CS.playing){if(st===1)YTP.pauseVideo();blockedSince=0;return}if(WMC.gesture&&!WMC.blocked&&st!==1&&st!==3){YTP.playVideo();if(!blockedSince)blockedSince=Date.now();else if(Date.now()-blockedSince>3000){WMC.blocked=true;wmcOverlay()}}else if(st===1)blockedSince=0}catch(e){}};
function wmcSpeakers(){const el=$('#wmc-speakers');if(!el||!CS)return;const people=CS.seats.filter(x=>x&&VC.spk[x.id]).slice(0,2);el.innerHTML=people.map(x=>`<div class="wmc-speaker"><img src="/ava/${h(x.id)}" alt="" onerror="this.style.display='none'"><span>${h(x.name)}</span><i></i><i></i><i></i></div>`).join('')}
