vcJoin=async function(){if(VC.on||WMC.voiceJoining)return;if(!CS||CS.mine<0)return toast(t('only_seated'));WMC.voiceJoining=true;const code=CID,epoch=WMC.epoch;let stream=null;try{hap('medium');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(code!==CID||epoch!==WMC.epoch){stream.getTracks().forEach(t=>t.stop());return}stream.getAudioTracks().forEach(t=>t.enabled=false);VC.stream=stream;VC.mute=true;VC.on=true;VC.cid=code;VC.ver=0;const j=await api('/api/turn');if(!VC.on||CID!==code)return;VC.ice=j.ice||[{urls:'stun:stun.l.google.com:19302'}];const r=await api('/api/cv/'+code,{a:'join'});if(!VC.on||CID!==code)return;if(!r.ok)throw Error('join');vcMeter(ME.me.id,stream);vcLoop();drawHall();wmcResumeAudio()}catch(e){if(stream)stream.getTracks().forEach(t=>t.stop());vcLeave();toast(t(e.name==='NotAllowedError'?'mic_denied':'err'))}finally{WMC.voiceJoining=false}};
