vcMeter=function(id,stream){try{const prior=WMC.meters.get(String(id));if(prior){prior.source.disconnect();prior.an.disconnect()}VC.actx=VC.actx||new(window.AudioContext||window.webkitAudioContext)();VC.actx.resume().catch(()=>{});const an=VC.actx.createAnalyser();an.fftSize=256;const source=VC.actx.createMediaStreamSource(stream);source.connect(an);const state={source,an};WMC.meters.set(String(id),state);const buf=new Uint8Array(an.frequencyBinCount);let last=0;const tick=()=>{if(!VC.on||WMC.meters.get(String(id))!==state)return;an.getByteFrequencyData(buf);let sum=0;for(const v of buf)sum+=v;const active=sum/buf.length>16&&!(String(id)===String(ME.me.id)&&VC.mute);const now=performance.now();if(active!==!!VC.spk[id]&&(active||now-last>550)){VC.spk[id]=active;spkDraw(id);duck()}if(active)last=now;requestAnimationFrame(tick)};tick()}catch(e){}};
