function wmPlayerIcon(name){
 const paths={
  play:'<path d="m9 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',
  pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',
  next:'<path d="m5 5 10 7-10 7Z" fill="currentColor" stroke="none"/><path d="M19 5v14"/>',
  previous:'<path d="m19 5-10 7 10 7Z" fill="currentColor" stroke="none"/><path d="M5 5v14"/>',
  repeat:'<path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/>',
  add:'<path d="M12 5v14M5 12h14"/>'
 };
 return '<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||'')+'</svg>';
}
function wmRefreshPlayerControls(){
 const root=document.getElementById('fp');
 if(!root)return;
 const buttons=root.querySelectorAll('.ctl button');
 if(buttons.length!==5)return;
 const labels={fa:['تکرار آهنگ','آهنگ قبلی','پخش','مکث','آهنگ بعدی','افزودن به گروپ'],ps:['سندره تکرارول','مخکینۍ سندره','غږول','تمول','راتلونکې سندره','ګروپ ته زیاتول'],en:['Repeat track','Previous track','Play','Pause','Next track','Add to group']}[LG]||[];
 const icons=['repeat','previous',au.paused?'play':'pause','next','add'];
 const names=[labels[0],labels[1],labels[au.paused?2:3],labels[4],labels[5]];
 buttons.forEach((button,i)=>{
  button.innerHTML=wmPlayerIcon(icons[i]);
  button.setAttribute('aria-label',names[i]||icons[i]);
  if(i===0){button.setAttribute('aria-pressed',String(LOOP1));button.classList.toggle('wm-repeat-active',LOOP1)}
 });
}
const wmOriginalDrawFP=drawFP;
drawFP=function(){wmOriginalDrawFP();wmRefreshPlayerControls()};
