// Change source without rebuilding the page or losing the query / focus.
function wmChooseSource(source){
 if(source!=='sc'&&source!=='yt')return;
 SRC=source;
 document.querySelectorAll('[data-wm-source]').forEach(button=>{
  const active=button.dataset.wmSource===source;
  button.classList.toggle('on',active);
  button.setAttribute('aria-selected',String(active));
 });
}

