const wpOriginalApi=api;
api=async function(path,body){
 const j=await wpOriginalApi(path,body);
 if(path==='/api/me'&&j.ok&&j.entitlement){WP.entitlement=j.entitlement;WP.lastStatus=Date.now()}
 if(j.err==='subscription_required'){
  WP.entitlement={allowed:false};wpStopPersonal();
  if(TAB==='p'||TAB==='c')queueMicrotask(()=>render());
 }
 return j;
};
function wpAllowed(){return !!(WP.entitlement||ME?.entitlement)?.allowed}
function wpMoney(value,currency){
 const n=Number(value)*(currency==='irt'?10:1);if(!Number.isFinite(n))return '—';
 if(currency==='irt')currency='irr';
 const max=currency==='irr'||currency==='irt'?0:currency==='ton'?6:currency==='usdt'?4:2;
 return `<bdi dir="ltr">${h(new Intl.NumberFormat('en-US',{maximumFractionDigits:max}).format(n))} ${h(wpT(currency))}</bdi>`;
}
function wpStopPersonal(){
 ++playTok;LOADING=false;try{au.pause();au.removeAttribute('src');au.load()}catch(e){}
 CUR=null;miniUpd();closeFP();try{cinStop()}catch(e){}
}
async function wpStatus(){
 if(WP.statusBusy)return WP.statusBusy;
 WP.statusBusy=(async()=>{try{
  const j=await api('/api/personal?status=1');
  if(j.ok){const previous=wpAllowed();WP.entitlement=j.entitlement;if(ME)ME.entitlement=j.entitlement;WP.lastStatus=Date.now();
   if(WP.catalog&&j.trial)WP.catalog.trial=j.trial;
   if(!j.entitlement.allowed)wpStopPersonal();
   if(previous!==j.entitlement.allowed&&(TAB==='p'||TAB==='c'||TAB==='s'))render();
  }return j;
 }catch(e){return {ok:false}}finally{WP.statusBusy=null}})();
 return WP.statusBusy;
}
async function wpLoadCatalog(){
 const seq=++WP.seq;WP.loading=true;WP.error='';wpDrawCurrent();
 try{
  const j=await api('/api/personal'+(WP.currency?'?display='+encodeURIComponent(WP.currency):''));
  if(seq!==WP.seq)return;
  if(j.ok){WP.catalog=j;WP.entitlement=j.entitlement;if(ME)ME.entitlement=j.entitlement;WP.lastStatus=Date.now()}
  else WP.error=wpT(j.err);
 }catch(e){if(seq===WP.seq)WP.error=wpT('err')}
 finally{if(seq===WP.seq){WP.loading=false;wpDrawCurrent()}}
}
