// Normalize rendered UI only. Do not alter scripts, CSS, user input or callback data.
function wpLatinTree(root){
 if(!root)return;
 if(root.nodeType===3){const parent=root.parentElement;if(!parent||parent.closest('script,style,textarea,[contenteditable="true"]'))return;const value=wpDigits(root.nodeValue);if(value!==root.nodeValue)root.nodeValue=value;return}
 if(root.nodeType!==1)return;
 if(root.matches('script,style,textarea,[contenteditable="true"]'))return;
 for(const key of ['placeholder','aria-label','title']){const before=root.getAttribute(key);if(before!==null){const after=wpDigits(before);if(after!==before)root.setAttribute(key,after)}}
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode()))wpLatinTree(node);
 root.querySelectorAll('[placeholder],[aria-label],[title]').forEach(element=>{for(const key of ['placeholder','aria-label','title']){const before=element.getAttribute(key);if(before!==null){const after=wpDigits(before);if(before!==after)element.setAttribute(key,after)}}});
}
let wpDigitQueued=false;const wpDigitRoots=new Set();
const wpDigitObserver=new MutationObserver(records=>{
 for(const record of records){if(record.type==='characterData')wpDigitRoots.add(record.target);else if(record.type==='attributes')wpDigitRoots.add(record.target);else for(const node of record.addedNodes)wpDigitRoots.add(node)}
 if(wpDigitQueued)return;wpDigitQueued=true;
 queueMicrotask(()=>{wpDigitQueued=false;const roots=[...wpDigitRoots];wpDigitRoots.clear();roots.forEach(wpLatinTree)});
});
wpDigitObserver.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});
wpLatinTree(document.body);

