const wiBaseHero=heroCard;
heroCard=function(){
 const root=document.createElement('template');root.innerHTML=wiBaseHero();
 const hero=root.content.querySelector('.hero'),top=hero?.querySelector('.top');
 if(hero&&top){hero.classList.add('wi-hero','wi-'+wiCurrent().primary.code);top.innerHTML=wiPersona()}
 return root.innerHTML;
};
function wiMount(){
 if(!ME?.me)return;
 const context=wiContext(),changed=context!==WI.context;
 if(changed){WI.context=context;WI.profile=null}
 const view=V();if(!view)return;
 const hero=view.querySelector('.hero');
 const signature=JSON.stringify([wiCurrent(),LG,ME.me.name,ME.un]);
 if(hero){
  view.querySelector('.wi-compact')?.remove();
  if(hero.dataset.wiSignature!==signature){hero.classList.remove(...Array.from(hero.classList).filter(c=>c.startsWith('wi-')));hero.classList.add('wi-hero','wi-'+wiCurrent().primary.code);const top=hero.querySelector('.top');if(top)top.innerHTML=wiPersona();hero.dataset.wiSignature=signature}
 }else{
  let slot=view.querySelector(':scope > .wi-compact');
  if(!slot){slot=document.createElement('div');slot.className='wi-compact';view.prepend(slot)}
  if(slot.dataset.wiSignature!==signature){slot.innerHTML=wiPersona(true);slot.dataset.wiSignature=signature}
 }
 if(changed)wiRefresh();
}
function wiAccept(profile){
 if(!profile?.primary||!WI_CODES.includes(profile.primary.code))return;
 WI.profile=profile;WI.stamp=Number(profile.server_now)||0;WI.clock=performance.now();WI.last=Date.now();wiMount();
}
async function wiRefresh(){
 if(!ME)return;
 const context=wiContext();WI.context=context;
 if(WI.request?.context===context)return WI.request.promise;
 WI.last=Date.now();
 const seq=++WI.seq;
 const request={context};WI.request=request;
 request.promise=(async()=>{try{const j=await api('/api/identity'+(context?'?g='+encodeURIComponent(context):''));if(seq===WI.seq&&j.ok){WI.last=Date.now();wiAccept(j.identity)}}catch(e){}finally{if(WI.request===request)WI.request=null}})();
 return request.promise;
}
const wiBaseApi=api;
api=async function(path,body){
 const j=await wiBaseApi(path,body);
 if(path==='/api/me'&&j.ok&&j.identity)queueMicrotask(()=>{if(WI.context===null)wiAccept(j.identity)});
 if(j.ok&&(/^\/api\/personal(?:\?|\/trial|$)/.test(path)||path==='/api/finance/review'))setTimeout(wiRefresh,300);
 return j;
};
for(const name of ['render','rMe','rPlayer','rShop','drawShop','wpRenderShop','wpLockPage','applyLang']){
