}
function wiReady(){if(ME?.identity&&WI.context===null)wiAccept(ME.identity);else wiRefresh();wiMount()}
if(ME)wiReady();else{const ready=setInterval(()=>{if(ME){clearInterval(ready);wiReady()}},100);setTimeout(()=>clearInterval(ready),30000)}
