 if(identity.primary.until&&now>=identity.primary.until){WI.profile={primary:identity.secondary||{code:'member',rank:10,tier:0},secondary:null,server_now:now};wiMount();wiRefresh()}
 else if(Date.now()-WI.last>30000)wiRefresh();
},1000);
