 b.innerHTML=wc23Coin+'<bdi>'+h(WC23.data?.balance||'—')+'</bdi>';b.setAttribute('aria-label',wc23T('title'));
}
async function wc23Refresh(draw=true){
 const seq=WC23.readSeq=(WC23.readSeq||0)+1;
 try{const j=await api('/api/wallet');if(seq!==WC23.readSeq)return;if(j.ok){if(!WC23.data&&WC23.error==='err')WC23.error='';WC23.data=j;WC23.last=Date.now();const bill=WC23.quote?.bill;if(bill){const fresh=j.orders?.find(b=>b.id===bill.id);if(fresh){WC23.quote.bill=fresh;if(fresh.status==='ok'){WC23.quote=null;WC23.done='coins'}}}wc23Mount();if(draw&&WC23.open&&!WC23.busy)wc23Draw()}else if(!WC23.data){WC23.error='err';if(WC23.open)wc23Draw()}}catch(e){if(seq===WC23.readSeq&&!WC23.data){WC23.error='err';if(WC23.open)wc23Draw()}}
}
async function wc23Open(){WC23.open=true;WC23.error='';wc23Draw();await wc23Refresh();setBack()}
function wc23Close(){WC23.open=false;document.getElementById('wc23-panel')?.remove();setBack()}
function wc23Tab(tab){if(WC23.busy)return;WC23.tab=tab;WC23.terms=false;WC23.quote=null;WC23.intent=null;WC23.key=null;WC23.error='';++WC23.seq;wc23Draw()}
function wc23Currency(cur){if(WC23.busy||!['usd','eur','irr','afn','usdt','ton'].includes(cur))return;WC23.cur=cur;WC23.quote=null;WC23.key=null;WC23.error='';++WC23.seq;wc23Draw()}
function wc23Methods(){const list=WC23.data?.methods||[];return list.filter(m=>m.configured&&m.code!=='stars'&&(WC23.cur==='usd'?m.code==='stars':WC23.cur==='eur'?['sepa','revolut','stars'].includes(m.code):m.cur===WC23.cur))}
function wc23Draw(){
 if(!WC23.open)return;let panel=document.getElementById('wc23-panel');if(!panel){panel=document.createElement('section');panel.id='wc23-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');document.body.append(panel)}
 const data=WC23.data;let body='';
 if(WC23.terms)body=`<div class="wc23-card"><h3>${h(wc23T('terms'))}</h3><p class="wc23-muted">${h(wc23T('note'))}</p><p class="wc23-muted">${h(wc23T('starsInfo'))}</p><p class="wc23-muted">${h(wc23T('manual'))}</p><button class="chip" onclick="wc23Support()">${h(wc23T('support'))}</button><button class="wc23-submit" onclick="WC23.terms=false;wc23Draw()">${h(wc23T('close'))}</button></div>`;
 else if(WC23.done){body=`<div class="wc23-card wc23-done"><span class="wc23-gift">${wc23Gift(WC23.done)}</span><h3>${h(wc23T('done'))}</h3><button class="wc23-submit" onclick="WC23.done=null;wc23Tab('history')">${h(wc23T('history'))}</button></div>`}
 else if(!data)body=WC23.error?`<button class="wc23-submit" onclick="wc23Refresh()">${h(wc23T('refresh'))}</button>`:'<div class="skel" style="height:160px"></div>';
 else if(WC23.quote)body=wc23Confirm();
 else if(WC23.tab==='topup')body=`<div class="wc23-currencies">${['usd','eur','irr','afn','usdt','ton'].map(c=>`<button class="${WC23.cur===c?'on':''}" onclick="wc23Currency('${c}')">${h(wc23T(c))}</button>`).join('')}</div><div class="wc23-card"><h3>${h(wc23T('topup'))}</h3><label>${h(wc23T('amount'))}<input id="wc23-amount" inputmode="decimal" dir="ltr" value="${h(WC23.amount||'50')}"></label><div class="wc23-grid">${wc23Methods().map(m=>`<button onclick="${m.kind==='support'?"wc23Support()":`wc23TopupQuote('${m.code}')`}">${m.code==='stars'?'⭐':m.code==='ton'?'💠':m.code==='usdt'?'🟢':'💳'} ${h(wc23T(m.code))}${m.kind==='support'?`<small class="wc23-muted">${h(wc23T('support'))}</small>`:''}</button>`).join('')}</div><p class="wc23-muted">${h(wc23T('note'))}</p></div>`;
 else if(WC23.tab==='send')body=`<div class="wc23-card"><label>${h(wc23T('uid'))}<input id="wc23-recipient" inputmode="numeric" dir="ltr" value="${h(WC23.recipient||'')}"></label><div class="wc23-grid">${data.gifts.map(g=>`<button class="${WC23.gift===g.code?'on':''}" onclick="wc23ChooseGift('${g.code}')"><span class="wc23-gift">${wc23Gift(g.code)}</span>${h(wc23T(g.code))} · <bdi>${h(g.coins)}</bdi></button>`).join('')}</div><label>${h(wc23T('amount'))}<input id="wc23-send-amount" inputmode="decimal" dir="ltr" value="${h(WC23.sendAmount||'1')}" oninput="WC23.gift=''"></label><button class="wc23-submit" onclick="wc23TransferQuote()">${h(wc23T(WC23.gift?'gift':'transfer'))}</button></div>`;
 else if(WC23.tab==='buy')body=`<div class="wc23-card"><div class="wc23-tabs">${['personal'].map(k=>`<button class="${WC23.kind===k?'on':''}" onclick="WC23.kind='${k}';wc23Draw()">${h(wc23T(k))}</button>`).join('')}</div>${WC23.kind==='group'?`<label>${h(wc23T('selectGroup'))}<select id="wc23-group"><option value="0">${h(wc23T('selectGroup'))}</option>${(ME?.groups||[]).map(g=>`<option value="${-Math.abs(Number(g.id))}">${h(g.title)}</option>`).join('')}</select></label>`:''}<div class="wc23-grid">${data.plans.map(p=>`<button onclick="wc23PurchaseQuote(${p.months})"><b>${p.months===12?h(wc23T('year')):p.months+' '+h(wc23T('month'))}</b>${WC23.kind==='personal'?`<br><bdi>${h(p.coins)}</bdi> ${h(wc23T('coins'))}`:''}</button>`).join('')}</div></div>`;
 else body=wc23History();
 panel.innerHTML=`<div class="wc23-wrap"><div class="wc23-head"><b>${wc23Coin} ${h(wc23T('title'))}</b><button onclick="wc23Close()" aria-label="${h(wc23T('close'))}">×</button></div><div class="wc23-balance">${wc23Coin}<strong>${h(data?.balance||'—')}</strong><small>${h(wc23T('coins'))}</small></div><div class="wc23-tabs">${['topup','send','buy','history'].map(k=>`<button class="${WC23.tab===k?'on':''}" onclick="WC23.done=null;wc23Tab('${k}')">${h(wc23T(k))}</button>`).join('')}</div>${WC23.error?`<p class="wc23-error" role="alert">${h(wc23T(WC23.error))}</p>`:''}${body}</div>`;
 if(WC23.busy)panel.querySelectorAll('button:not(.wc23-head button)').forEach(b=>b.disabled=true);
}
function wc23History(){const data=WC23.data;return `<div class="wc23-card"><button class="chip" onclick="wc23Refresh()">↻ ${h(wc23T('refresh'))}</button>${data.history.length?data.history.map(v=>`<div class="wc23-history"><span>${wc23Gift(v.meta?.gift)} ${h(wc23T(v.kind==='topup'?'topupKind':v.kind==='gift'?'giftKind':v.kind==='transfer'?'transferKind':'purchase'))}${v.other?`<small>${h(v.other.name)} · <bdi>${v.other.public_id||v.other.id}</bdi></small>`:''}<small>${new Date(v.ts*1000).toLocaleString('en-GB')}</small></span><bdi>${h(v.coins)}</bdi></div>`).join(''):`<p class="wc23-muted">${h(wc23T('empty'))}</p>`}</div>${(data.orders||[]).map(b=>`<div class="wc23-card"><b>${h(wc23T('topupKind'))} #${b.id} · <bdi>${h(b.coins)}</bdi></b><p>${h(wc23T(b.status))}</p>${b.status==='draft'||b.status==='wait'?wc23Bill(b):''}</div>`).join('')}`}
function wc23ChooseGift(gift){WC23.recipient=document.getElementById('wc23-recipient')?.value||'';WC23.sendAmount=document.getElementById('wc23-send-amount')?.value||'1';WC23.gift=gift;wc23Draw()}
function wc23Bill(b){return `<p><bdi>${h(b.amount)}</bdi> ${h(b.cur==='xtr'?'Stars':wc23T(b.cur))}</p>${b.destination?`<pre style="white-space:pre-wrap;direction:ltr;text-align:left;font-size:13px">${h(Object.entries(b.destination).map(([k,v])=>k==='network'?k+': '+v:String(v)).join('\n'))}</pre>`:''}${b.method==='stars'?`<p class="wc23-muted">${h(wc23T('starsInfo'))}</p>${b.invoice_link?`<button class="wc23-submit" onclick="wc23Invoice('${b.invoice_link}')">${h(wc23T('invoice'))}</button>`:''}`:`<p class="wc23-muted">${h(wc23T('manual'))}</p>${b.receipt_in_app?`<button class="wc23-submit" onclick="WakhanReceipt.open('wallet',{id:${Number(b.id)}})">${h(wc23T('receipt'))}</button>`:''}`}`}
function wc23Confirm(){const q=WC23.quote;if(q.bill)return `<div class="wc23-card"><h3>${h(wc23T('topupKind'))} #${q.bill.id}</h3><bdi>${h(q.bill.coins)}</bdi> ${h(wc23T('coins'))}${wc23Bill(q.bill)}</div>`;return `<div class="wc23-card"><h3>${h(wc23T('confirm'))}</h3>${q.recipient?`<p>${h(wc23T('recipient'))}: <b>${h(q.recipient.name)}</b><br><bdi>${q.recipient.public_id||q.recipient.id}</bdi></p>`:''}<p>${q.gift?wc23Gift(q.gift):wc23Coin} <bdi>${h(q.coins)}</bdi> ${h(wc23T('coins'))}</p>${q.amount?`<p><bdi>${h(q.amount)}</bdi> ${h(q.cur==='xtr'?'Stars':wc23T(q.cur))}</p>`:''}${q.kind?`<p>${h(wc23T(q.kind))} · ${q.months===12?h(wc23T('year')):q.months+' '+h(wc23T('month'))}</p>`:''}${q.method==='stars'?`<p class="wc23-muted">${h(wc23T('starsInfo'))}</p><label class="wc23-muted"><input id="wc23-terms" type="checkbox" style="display:inline;width:20px;min-height:20px"> ${h(wc23T('terms'))} <a href="javascript:wc23Terms()">/terms</a></label>`:''}<button class="wc23-submit" onclick="wc23Commit()">${h(wc23T('confirm'))}</button></div>`}
async function wc23Request(body){const j=await api('/api/wallet',body);if(!j.ok)throw Error(j.err||'err');return j}
async function wc23Run(fn){if(WC23.busy)return;const seq=++WC23.seq;WC23.busy=true;WC23.error='';wc23Draw();try{await fn(seq)}catch(e){if(seq===WC23.seq)WC23.error=WC23_COPY.en[e.message]?e.message:'err'}finally{if(seq===WC23.seq){WC23.busy=false;wc23Draw()}}}
async function wc23TopupQuote(method){WC23.amount=document.getElementById('wc23-amount')?.value||'50';await wc23Run(async seq=>{const j=await wc23Request({action:'topup_quote',coins:wpDigits(WC23.amount),method});if(seq!==WC23.seq)return;WC23.quote=j;WC23.intent='topup';WC23.key=wc23Key()})}
async function wc23TransferQuote(){WC23.recipient=document.getElementById('wc23-recipient')?.value||'';WC23.sendAmount=document.getElementById('wc23-send-amount')?.value||'1';await wc23Run(async seq=>{const j=await wc23Request({action:'transfer_quote',uid:Number(wpDigits(WC23.recipient)),coins:wpDigits(WC23.sendAmount),gift:WC23.gift});if(seq!==WC23.seq)return;WC23.quote=j;WC23.intent='transfer';WC23.key=wc23Key()})}
async function wc23PurchaseQuote(months){WC23.group=Number(document.getElementById('wc23-group')?.value||0);await wc23Run(async seq=>{const j=await wc23Request({action:'purchase_quote',kind:WC23.kind,months,cid:WC23.group});if(seq!==WC23.seq)return;WC23.quote=j;WC23.intent='purchase';WC23.key=wc23Key()})}
async function wc23Commit(){const q=WC23.quote,intent=WC23.intent,key=WC23.key;if(!q?.token||!intent)return;const terms=document.getElementById('wc23-terms')?.checked;if(q.method==='stars'&&!terms){WC23.error='terms_required';wc23Draw();return}await wc23Run(async seq=>{const j=await wc23Request({action:intent,token:q.token,client_key:key,lang:LG,terms:terms?'2026-11-03':null});await wc23Refresh(false);if(seq!==WC23.seq)return;if(intent==='topup')WC23.quote={bill:j.bill};else{WC23.done=q.gift||'coins';WC23.quote=null;if(intent==='transfer'){WC23.recipient='';WC23.sendAmount='';WC23.gift='';WC23.intent=null;WC23.key=null}if(intent==='purchase'){if(j.entitlement){WP.entitlement=j.entitlement;if(ME)ME.entitlement=j.entitlement}await wiRefresh()}}})}
