// Local app text/labels use Latin digits; wire IDs, URLs and stored user data stay intact.
function w29Digits(root){
 if(!root)return;
 const skip=node=>node.parentElement?.closest('script,style,noscript');
 if(root.nodeType===3){if(!skip(root)){const v=w29Latin(root.nodeValue);if(v!==root.nodeValue)root.nodeValue=v}return}
 if(root.nodeType!==1&&root.nodeType!==9)return;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode())if(!skip(node)){const v=w29Latin(node.nodeValue);if(v!==node.nodeValue)node.nodeValue=v}
 const fields=root.matches?.('input,textarea')?[root]:Array.from(root.querySelectorAll?.('input,textarea')||[]);
 for(const el of fields){if(el.tagName==='INPUT'&&!['text','search','number','tel'].includes(el.type))continue;const v=w29Latin(el.value);if(v!==el.value){const start=el.selectionStart,end=el.selectionEnd;el.value=v;try{el.setSelectionRange(start,end)}catch(e){}}}
}
const w29DigitObserver=new MutationObserver(records=>{for(const r of records)if(r.type==='characterData')w29Digits(r.target);else for(const node of r.addedNodes)w29Digits(node)});
w29DigitObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
document.addEventListener('input',e=>{if(e.target.matches?.('input,textarea'))w29Digits(e.target)},true);
w29Digits(document.body);w29Mount();

