async function op31Act(action,extra={}){
 if(OP31.busy||!op31Allowed())return;
 const team=action.startsWith('team_'),cid=team?0:OP31.selected;if(!team&&(!OP31.group||OP31.group.id!==cid))return;
 const body={action,cid,...extra};if(!team)body.expected_rev=OP31.group.rev;
 if(action==='credit'){const days=Number(w29Latin(OP31.days));if(!Number.isInteger(days)||days<1||days>36500){OP31.error=op31T('bad_days');op31Render();return}body.days=days}
 if(action==='team_add')body.target=OP31.teamTarget.trim();
 const identity=JSON.stringify({...body,expected_rev:undefined});
 if(OP31.intent?.identity===identity)Object.assign(body,OP31.intent.body);else{body.client_key=op31Key();OP31.intent={identity,body:{...body}}}
 OP31.busy=true;OP31.error='';op31Render();op31UpdateGuide();
 try{
  const j=await api('/api/operations',body);
  if(!j.ok){if(j.err!=='server')OP31.intent=null;op31Error(j);if(j.err==='stale_group'){await op31LoadGroup(cid);OP31.error=op31T('stale_group')}return}
  OP31.intent=null;toast(j.stop_ok===false?op31T('stop_failed'):op31T(action+'_done')===action+'_done'?op31T('done'):op31T(action+'_done').replace('{days}',String(j.days||'')));
  if(team){OP31.teamUser=null;OP31.teamTarget='';await af24Refresh(false);await op31Load()}
  else {const previousTarget=OP31.member?.id;await op31LoadGroup(cid);if(action==='right'&&previousTarget){const next=await api('/api/operations',{action:'lookup',cid,target:String(previousTarget)});if(next.ok)OP31.member=next.user}}
 }catch(e){OP31.error=op31T('error')}
 finally{OP31.busy=false;if(TAB==='o')op31Render();op31UpdateGuide()}
}
function op31Person(user){return `<span class="op31-person"><img src="/ava/${Number(user.id)}" alt="" loading="lazy" onerror="this.hidden=true"><span><b dir="auto">${h(user.name||String(user.id))}</b><small><bdi>${user.id}</bdi>${user.username?' · @'+h(user.username):''}</small></span></span>`}
function op31State(g){return g.suspended?'suspended':!g.approved?'pending':g.active===false||g.until<=Date.now()/1000?'expired':'active'}
function op31GrantControls(){
 const u=OP31.member;if(!u)return '';
 const fixed=['owner','creator'].includes(u.role);
 return `<div class="op31-result">${op31Person(u)}<small>${h(op31T('direct'))}</small>${fixed?`<p>${h(op31T('fixed_role'))}</p>`:`<div class="op31-rights">${['music','miniapp','deputy','minister'].map(right=>`<button type="button" role="switch" aria-checked="${u.rights[right]}" class="${u.rights[right]?'on':''}" onclick="op31Act('right',{target:'${u.id}',right:'${right}',enabled:${!u.rights[right]}})">${op31Icon(right==='music'?'credit':'shield')}<span>${h(op31T(right))}</span><i aria-hidden="true"></i></button>`).join('')}</div>`}</div>`;
}
function op31GrantList(){
 const groups=new Map();for(const grant of OP31.group?.grants||[]){let item=groups.get(grant.user.id);if(!item){item={...grant.user,fixed:grant.fixed,rights:[]};groups.set(item.id,item)}item.rights.push(grant.right)}
 return `<details class="op31-grant-list"><summary>${h(op31T('grant_list'))} · ${groups.size}</summary>${Array.from(groups.values()).map(u=>`<article class="op31-team-member">${op31Person(u)}<small>${h(u.rights.map(op31T).join(' · '))}</small><div class="op31-actions">${op31Button(op31T('member'),`OP31.target='${u.id}';op31Lookup()`,'shield')}${!u.fixed?op31Button(op31T('revoke'),`op31Act('revoke',{target:'${u.id}'})`,'stop','class="op31-remove"'):''}</div></article>`).join('')||`<p>${h(op31T('empty'))}</p>`}</details>`;
}
