 <section class="op31-card"><h3>${op31Icon('credit')}${h(op31T('credit'))}</h3><p>${h(op31T('credit_hint'))}</p><div class="op31-presets">${[3,7,30,90,300].map(days=>`<button type="button" class="${Number(OP31.days)===days?'on':''}" onclick="OP31.days='${days}';op31Render()"><bdi>${days}</bdi></button>`).join('')}</div><label class="op31-days">${h(op31T('days'))}<input id="op31-days" inputmode="numeric" value="${h(OP31.days)}" oninput="OP31.days=this.value;document.getElementById('op31-add-label').textContent=op31T('add_credit').replace('{days}',w29Latin(this.value))"></label><button type="button" class="op31-primary" onclick="op31Act('credit')">${op31Icon('credit')}<span id="op31-add-label">${h(op31T('add_credit').replace('{days}',OP31.days))}</span></button>${!g.approved&&g.until>Date.now()/1000?op31Button(op31T('approve'),"op31Act('approve')",'shield'):''}</section>
