 return `<section class="op31-card"><h3>${op31Icon('team')}${h(op31T('team'))}</h3><p>${h(op31T('team_note'))}</p>${root?`<label>${h(op31T('target'))}<input id="op31-team-target" type="text" dir="ltr" value="${h(OP31.teamTarget)}" oninput="OP31.teamTarget=this.value;OP31.teamUser=null" placeholder="123456789 / @username"></label><div class="op31-actions">${op31Button(op31T('lookup'),'op31Lookup(true)','search')}${op31Button(op31T('team_add'),"op31Act('team_add')",'team','class="op31-primary"')}</div>${OP31.teamUser?op31Person(OP31.teamUser):''}`:''}${OP31.data?.team?.length?OP31.data.team.map(u=>`<article class="op31-team-member">${op31Person(u)}${!u.known?`<small>${h(op31T('pending_start'))}</small>`:''}${root?op31Button(op31T('team_remove'),`op31Act('team_remove',{target:'${u.id}'})`,'stop','class="op31-remove"'):''}</article>`).join(''):`<p>${h(op31T('empty'))}</p>`}</section>${root?`<section class="op31-card">${op31Button(op31T('mint'),'op31Mint()','credit')}</section>`:''}`;
