function op31LogView(rows){
 if(!rows.length)return `<p>${h(op31T('empty'))}</p>`;
 return rows.map(row=>{const key=row.action==='right'?'member':row.action==='owner_changed'?'owner_transfer':row.action.startsWith('grant:')||row.action.startsWith('revoke:')?'member':row.action;
 const extra=row.detail?.days?` · ${row.detail.days} ${op31T('days')}`:row.detail?.right?' · '+op31T(row.detail.right):'';
 return `<article class="op31-log"><span>${op31Icon('audit')}</span><div><b>${h(op31T(key)===key?op31T('done'):op31T(key))}${h(extra)}</b><small>${h(row.actor.name)}${row.target?' ← '+h(row.target.name):''}</small>${row.cid?`<small><bdi>${row.cid}</bdi></small>`:''}<time>${h(op31Date(row.ts))}</time></div></article>`}).join('');
}
