 const data=OP31.data;
 return `<section class="op31-card"><label class="op31-search">${op31Icon('search')}<input id="op31-search" type="search" placeholder="${h(op31T('search'))}" value="${h(OP31.q)}" oninput="op31Search(this.value)"></label><div class="op31-filters">${['all','active','pending','near','expired','suspended'].map(key=>`<button type="button" class="${OP31.filter===key?'on':''}" onclick="op31Filter('${key}')">${h(op31T(key))}</button>`).join('')}</div></section><div class="op31-group-list">${data?.groups?.length?data.groups.map(g=>`<button type="button" class="op31-group" onclick="op31Select(${g.id})">${op31Icon('groups')}<span><b dir="auto">${h(g.title)}</b><small><bdi>${g.id}</bdi> · ${g.days} ${h(op31T('days'))}</small></span><span class="op31-status ${g.state}">${h(op31T(g.state))}</span></button>`).join(''):`<p class="op31-card">${h(op31T('empty'))}</p>`}</div>${data?.more?op31Button(op31T('more'),'op31More()','groups'):''}<section class="op31-card">${op31Button(op31T('bot_add'),'addBotLink()','team')}<small>${h(op31T('add_hint'))}</small></section>`;
