function op31Render(){
 if(TAB!=='o')return;if(!op31Allowed()){go('m');return}
 let body=OP31.selected?op31GroupView():OP31.tab==='team'?op31TeamView():OP31.tab==='audit'?`<section class="op31-card">${op31LogView(OP31.audit||[])}${OP31.auditMore?op31Button(op31T('more'),'OP31.auditPage++;op31LoadAudit()','audit'):''}</section>`:op31ListView();
 const focused=document.activeElement;const searchFocus=focused?.id==='op31-search',caret=searchFocus?focused.selectionStart:null;
 const counts=OP31.data?.counts;
 V().innerHTML=`<main class="op31"><div class="op31-heading"><button type="button" class="op31-back" onclick="go('m')" aria-label="${LG==='fa'?'برگشت':LG==='ps'?'شاته':'Back'}">‹</button><div><h2>${h(op31T('title'))}</h2><p>${h(op31T('intro'))}</p></div><button class="op31-small" onclick="${OP31.selected?'op31LoadGroup()':'op31Load()'}" aria-label="${h(op31T('refresh'))}">${op31Icon('audit')}</button></div>${!OP31.selected?`<div class="op31-metrics">${['active','near','pending'].map(k=>`<button type="button" onclick="OP31.tab='groups';op31Filter('${k}')"><bdi>${counts?.[k]??'—'}</bdi><small>${h(op31T(k))}</small></button>`).join('')}</div><div class="op31-tabs">${['groups','team','audit'].map(k=>`<button type="button" class="${OP31.tab===k?'on':''}" onclick="op31Tab('${k}')">${op31Icon(k)}${h(op31T(k))}</button>`).join('')}</div>`:''}${OP31.error?`<p class="op31-error" role="alert">${h(OP31.error)}</p>`:''}${OP31.loading?'<div class="op31-loading" role="status"><i></i></div>':''}${body}</main>`;
 if(OP31.busy)V().querySelectorAll('button,input,select').forEach(el=>el.disabled=true);
 if(searchFocus&&!OP31.busy){const input=document.getElementById('op31-search');input?.focus({preventScroll:true});try{input?.setSelectionRange(caret,caret)}catch(e){}}
 if(!OP31.data&&!OP31.loading&&!OP31.error&&!OP31.selected)op31Load();
}
