 V().innerHTML=`<main class="wn-page wn-music"><div class="wn-eyebrow">WAKHAN AUDIO</div><h1 class="wn-heading">${h(wnT("music"))}</h1><p class="wn-subtitle">${h(wnT("musicHint"))}</p><div class="wn-sources" role="tablist">${["sc","yt"].map(s=>`<button class="wn-source ${SRC===s?'on':''}" data-wm-source="${s}" role="tab" aria-selected="${SRC===s}" onclick="wmChooseSource('${s}')">${wnIcon(s==="yt"?"youtube":"soundcloud")}<span>${s==="yt"?"YouTube":"SoundCloud"}</span></button>`).join("")}</div><form class="wn-search" onsubmit="event.preventDefault();doSearch()">${wnIcon("search")}<input id="q" type="search" autocomplete="off" placeholder="${h(wnT("searchHint"))}" value="${h(WN60.queries[SRC])}" aria-label="${h(wnT("search"))}"><button type="submit" aria-label="${h(wnT("search"))}">${wnIcon("forward")}</button></form><p class="wn-subtitle">${h(wnT("sourceHint"))}</p><section id="pres" aria-live="polite"></section></main>`;
 showRes();
}
rPlayer=wnMusic;
wmChooseSource=function(source){if(!["sc","yt"].includes(source)||source===SRC)return;const input=document.getElementById("q");if(input)WN60.queries[SRC]=input.value;if(WN60.searchState[SRC]==="loading")WN60.searchState[SRC]="";++WN60.searchSeq;SRC=source;M22.source=source;store("music_source_v22",source);RES=WN60.results[source].slice();wnMusic();hap()};
showRes=function(){const out=document.getElementById("pres");if(!out)return;const state=WN60.searchState[SRC];if(state==="loading"){out.innerHTML=wnSkeleton();return}if(state==="error"){out.innerHTML=wnEmpty(wnT("failed"),"","error","doSearch()",wnT("retry"));return}if(state==="empty"){out.innerHTML=wnEmpty(wnT("noResults"),wnT("musicHint"),"search");return}if(RES.length){out.innerHTML=wnHeading(wnT("results"),RES.length)+wnRows(RES,"RES");return}const recent=(ME?.phist||[]).filter(r=>wnProvider(r)===SRC).slice(0,6),favorites=(ME?.favs||[]).filter(r=>wnProvider(r)===SRC).slice(0,6);out.innerHTML=(recent.length?wnHeading(wnT("history"))+wnRows(recent,"WN_SOURCE_RECENT"):"")+(favorites.length?wnHeading(wnT("favorites"))+wnRows(favorites,"WN_SOURCE_FAV"):"");if(!recent.length&&!favorites.length)out.innerHTML=wnEmpty(wnT("empty"),wnT("emptyHint"),"headphones")};
doSearch=async function(){const input=document.getElementById("q");if(!input)return;const query=input.value.trim();if(!query)return;input.blur();const seq=++WN60.searchSeq,source=SRC;WN60.queries[source]=query;WN60.searchState[source]="loading";RES=[];showRes();try{const result=await api('/api/search?k=m&src='+source+'&q='+encodeURIComponent(query));if(seq!==WN60.searchSeq||source!==SRC)return;if(!result.ok)throw Error(result.err||"failed");RES=(result.items||[]).filter(r=>wnProvider(r)===source);WN60.results[source]=RES.slice();WN60.searchState[source]=RES.length?"":"empty";showRes()}catch(error){if(seq===WN60.searchSeq&&source===SRC){WN60.searchState[source]="error";showRes()}}};

function wnPlaylistTile(playlist){return `<button class="wn-playlist" onclick="go('l',{kind:'playlist',id:'${playlist.id}'})"><span class="wn-playlist-art">${playlist.covers?.[0]?`<img src="${h(playlist.covers[0])}" alt="" loading="lazy" onerror="this.replaceWith(wnFallback())">`:wnIcon("library")}<span class="wn-count">${playlist.count||0}</span></span><b>${h(playlist.name)}</b><small>${playlist.count||0} ${h(wnT("tracks"))}${playlist.providers?.length>1?" · "+wnT("fromBoth"):""}</small></button>`}
async function wnLoadLibrary(){const lib=WN60.library;if(lib.loading)return;lib.loading=true;lib.error="";try{const result=await api('/api/v60/library');if(!result.ok)throw Error(result.err);lib.items=result.playlists||[];lib.loaded=true}catch(error){lib.error=wnT("failed")}finally{lib.loading=false;if(TAB==='l')wnLibrary();else if(TAB==='h')wnHome();else if(TAB==='m'&&SUB?.kind!=='details')rMe()}}
async function wnLoadPlaylist(id){const lib=WN60.library,seq=++lib.detailSeq;lib.id=id;lib.detail=null;lib.detailLoading=true;lib.detailError="";try{const result=await api('/api/v60/library?id='+encodeURIComponent(id));if(seq!==lib.detailSeq)return;if(!result.ok)throw Error(result.err);lib.detail=result.playlist}catch(error){if(seq===lib.detailSeq)lib.detailError=wnT("failed")}finally{if(seq===lib.detailSeq){lib.detailLoading=false;if(TAB==='l'&&SUB?.id===id)wnLibrary()}}}
function wnLibrary(){const lib=WN60.library,kind=SUB?.kind,id=SUB?.id;
 if(kind==='playlist'&&id){if(lib.id!==id)wnLoadPlaylist(id);const value=lib.id===id?lib.detail:null;V().innerHTML=`<main class="wn-page"><button class="wn-secondary" onclick="go('l')">${wnIcon("back")}${h(wnT("back"))}</button>${!value?(lib.detailError?wnEmpty(lib.detailError,"","error",`wnLoadPlaylist('${id}')`,wnT("retry")):wnSkeleton()):`<section class="wn-playlist-hero"><div class="wn-playlist-art">${value.tracks[0]?.thumb?wnImage(value.tracks[0]):wnIcon("library")}</div><h1>${h(value.name)}</h1><p>${value.tracks.length} ${h(wnT("tracks"))} · ${h(wnT("fromBoth"))}</p><div class="wn-playlist-actions"><button class="wn-primary" onclick="wnPlay('WN_PLAYLIST',0)" ${!value.tracks.length?'disabled':''}>${wnIcon("play")}${h(wnT("playAll"))}</button><button class="wn-icon-only" onclick="wnPlaylistMenu()" aria-label="${h(wnT("more"))}">${wnIcon("more")}</button></div></section>${value.tracks.length?wnRows(value.tracks,"WN_PLAYLIST",!!WN60.editPlaylist):wnEmpty(wnT("emptyPlaylist"),wnT("createHint"),"library","go('p')",wnT("listen"))}`}</main>`;if(lib.busy)V().querySelectorAll("button").forEach(b=>b.disabled=true);return}
 if(kind==='favorites'||kind==='history'){const items=(kind==='favorites'?ME?.favs:ME?.phist)||[];V().innerHTML=`<main class="wn-page"><button class="wn-secondary" onclick="go('l')">${wnIcon("back")}${h(wnT("back"))}</button><h1 class="wn-heading">${h(wnT(kind))}</h1>${items.length?wnRows(items.filter(wnProvider),'WN_SHELF'):wnEmpty(wnT("empty"),wnT("emptyHint"),kind==='favorites'?'heart':'clock',"go('p')",wnT("listen"))}</main>`;return}
 V().innerHTML=`<main class="wn-page"><div class="wn-eyebrow">${h(wnT("personal"))}</div><h1 class="wn-heading">${h(wnT("library"))}</h1><div class="wn-library-pins"><button onclick="go('l',{kind:'favorites'})">${wnIcon("heart")}${h(wnT("favorites"))}</button><button onclick="go('l',{kind:'history'})">${wnIcon("clock")}${h(wnT("history"))}</button></div><div class="wn-library-toolbar"><div><b>${h(wnT("playlists"))}</b><p class="wn-subtitle">${h(wnT("fromBoth"))}</p></div><button class="wn-secondary" onclick="wnNameSheet()">${wnIcon("add")}${h(wnT("create"))}</button></div>${lib.error?wnEmpty(lib.error,"","error","wnLoadLibrary()",wnT("retry")):lib.loading&&!lib.loaded?wnSkeleton():lib.items.length?`<div class="wn-library-grid">${lib.items.map(wnPlaylistTile).join("")}</div>`:wnEmpty(wnT("createFirst"),wnT("createHint"),"library","wnNameSheet()",wnT("create"))}</main>`;
 if(!lib.loaded&&!lib.loading&&!lib.error)wnLoadLibrary();
}
function wnNameSheet(rename=false,addTrack=false){const value=rename?WN60.library.detail?.name||"":"";sheet(`<h3>${wnIcon("library")}${h(wnT(rename?'rename':'create'))}</h3><form onsubmit="event.preventDefault();wnSubmitName(${rename},${addTrack})"><label class="wn-sheet-help" for="wn-name">${h(wnT("name"))}</label><input class="wn-input" id="wn-name" maxlength="80" value="${h(value)}" placeholder="${h(wnT("nameHint"))}" required><div id="wn-form-error" class="wn-form-error" role="alert"></div><div class="wn-sheet-buttons"><button type="button" class="wn-secondary" onclick="closeSheet()">${h(wnT("cancel"))}</button><button class="wn-primary" id="wn-submit">${h(wnT("save"))}</button></div></form>`);setTimeout(()=>document.getElementById('wn-name')?.focus(),100)}
async function wnSubmitName(rename,addTrack){const input=document.getElementById('wn-name'),button=document.getElementById('wn-submit'),error=document.getElementById('wn-form-error');const name=input?.value.trim();if(!name)return;button.disabled=true;try{const current=WN60.library.detail;const result=await api('/api/v60/library',rename?{action:'rename',id:current.id,rev:current.rev,name}:{action:'create',name});if(!result.ok)throw Error(result.err);WN60.library.detail=result.playlist;WN60.library.id=result.playlist.id;closeSheet();if(addTrack&&WN60.pendingTrack)await wnAddToPlaylist(result.playlist.id);else{go('l',{kind:'playlist',id:result.playlist.id});wnLoadLibrary()}}catch(e){if(error?.isConnected)error.textContent=wnT(e.message==='stale'?'stale':'failed');if(e.message==='stale'&&WN60.library.id)wnLoadPlaylist(WN60.library.id)}finally{if(button?.isConnected)button.disabled=false}}
async function wnSaveTrack(list,index){const track=listOf(list)[index];if(!track)return;WN60.pendingTrack={...track};sheet(`<h3>${wnIcon("library")}${h(wnT("addTo"))}</h3>${wnSkeleton()}`);await wnLoadLibrary();if(!document.getElementById('sheet').classList.contains('show'))return;sheet(`<h3>${wnIcon("library")}${h(wnT("choosePlaylist"))}</h3><p class="wn-sheet-help" dir="auto">${h(track.title)}</p><div class="wn-sheet-list"><button onclick="wnNameSheet(false,true)">${wnIcon("add")}<span>${h(wnT("create"))}</span></button>${WN60.library.items.map(p=>`<button onclick="wnAddToPlaylist('${p.id}')">${wnIcon("library")}<span>${h(p.name)}</span><small>${p.count} ${h(wnT("tracks"))}</small></button>`).join("")}</div>${WN60.library.error?`<p class="wn-form-error">${h(WN60.library.error)}</p>`:""}`)}
async function wnAddToPlaylist(id){const track=WN60.pendingTrack;if(!track||WN60.library.busy)return;WN60.library.busy=true;try{const current=await api('/api/v60/library?id='+encodeURIComponent(id));if(!current.ok)throw Error(current.err);const result=await api('/api/v60/library',{action:'add',id,rev:current.playlist.rev,track});if(!result.ok)throw Error(result.err);WN60.library.detail=result.playlist;WN60.library.id=id;WN60.pendingTrack=null;closeSheet();toast(wnT(result.duplicate?'duplicate':'saved'));await wnLoadLibrary()}catch(e){toast(wnT(e.message==='stale'?'stale':'failed'))}finally{WN60.library.busy=false;if(TAB==='l')wnLibrary()}}
function wnPlaylistMenu(){sheet(`<h3>${wnIcon('library')}${h(WN60.library.detail?.name||'')}</h3><div class="wn-sheet-list"><button onclick="wnNameSheet(true)">${wnIcon('edit')}<span>${h(wnT('rename'))}</span></button><button onclick="WN60.editPlaylist=!WN60.editPlaylist;closeSheet();wnLibrary()">${wnIcon('sort')}<span>${h(wnT(WN60.editPlaylist?'done':'edit'))}</span></button><button onclick="wnDeleteSheet()">${wnIcon('trash')}<span>${h(wnT('delete'))}</span></button></div>`)}
function wnDeleteSheet(){sheet(`<h3>${wnIcon('trash')}${h(wnT('delete'))}</h3><p class="wn-sheet-help">${h(WN60.library.detail?.name||'')}<br>${h(wnT('deleteHint'))}</p><div class="wn-sheet-buttons"><button class="wn-secondary" onclick="closeSheet()">${h(wnT('cancel'))}</button><button class="wn-primary" onclick="wnMutatePlaylist('delete')">${h(wnT('delete'))}</button></div>`)}
async function wnMutatePlaylist(action,extra={}){const lib=WN60.library,current=lib.detail;if(!current||lib.busy)return;lib.busy=true;try{const result=await api('/api/v60/library',{action,id:current.id,rev:current.rev,...extra});if(!result.ok)throw Error(result.err);if(action==='delete'){lib.detail=null;lib.id=null;closeSheet();go('l');toast(wnT('deleteDone'))}else{lib.detail=result.playlist;wnLibrary();if(action==='remove')toast(wnT('removed'))}await wnLoadLibrary()}catch(e){toast(wnT(e.message==='stale'?'stale':'failed'));if(e.message==='stale')await wnLoadPlaylist(current.id)}finally{lib.busy=false;if(TAB==='l')wnLibrary()}}
function wnRemove(index){const track=WN60.library.detail?.tracks[index];if(track)wnMutatePlaylist('remove',{track_id:track.id})}
function wnMove(index,delta){const items=WN60.library.detail?.tracks||[],target=index+delta;if(target<0||target>=items.length)return;const order=items.map(t=>t.id);[order[index],order[target]]=[order[target],order[index]];wnMutatePlaylist('reorder',{order})}

function wnPlay(list,index){const tracks=listOf(list);if(!tracks[index])return;if(!wpAllowed()){toast(wnT('subscriptionNeeded'));go('p');return}unlock();QUEUE=tracks.slice();QI=index;playCur()}
apFetch=async function(url,mode,seq){const provider=wnProvider({url}),deadline=Date.now()+300000;if(!provider)return{ok:false,err:'bad_source'};while(seq===AP.seq&&Date.now()<deadline){const result=await api((provider==='yt'?'/api/v60/audio?url=':'/api/stream?u=')+encodeURIComponent(url)+(provider==='sc'&&mode?'&fx=8d':''));if(seq!==AP.seq)return null;if(!result.pending)return result;await new Promise(r=>setTimeout(r,750))}return seq===AP.seq?{ok:false,err:'source_timeout'}:null};
playCur=async function(){const track=QUEUE[QI];if(!track)return;if(!wpAllowed()){wpStopPersonal();go('p');return}py21Stop();const seq=++AP.seq;++playTok;AP.busy=false;WN60.error='';au.pause();au.removeAttribute('src');au.load();CUR={...track,youtube:false,ready:false};LOADING=true;miniUpd();openFP();try{const result=await apFetch(track.url,FX8&&wnProvider(track)==='sc',seq);if(!result||seq!==AP.seq)return;if(!result.ok)throw Error(result.err||'failed');CUR={...track,youtube:false,title:result.title||track.title,artist:result.artist||track.artist||track.ch||'',ch:result.artist||track.artist||track.ch||'',thumb:result.thumb||track.thumb,dur:result.dur||track.dur,ready:true};const loaded=await apSource(result,0,true,seq);if(seq!==AP.seq)return;LOADING=false;if(!loaded)throw Error('audio');ME.phist=(ME.phist||[]).filter(r=>wnCanonical(r.url)!==wnCanonical(CUR.url));ME.phist.unshift({...CUR});ME.phist=ME.phist.slice(0,50);mediaMeta();miniUpd();drawFP()}catch(error){if(seq===AP.seq){LOADING=false;WN60.error=wnT('audioFailed');miniUpd();drawFP()}}};
togglePlay=function(){if(!CUR?.ready||LOADING)return;if(!wpAllowed()){wpStopPersonal();go('p');return}hap();if(au.paused){apSession();au.play().catch(()=>{WN60.error=wnT('tapPlay');drawFP()})}else au.pause()};
nextTrack=function(delta){if(!QUEUE.length)return;if(delta>0&&WN60.shuffle&&QUEUE.length>1){const available=QUEUE.map((_,i)=>i).filter(i=>i!==QI);QI=available[Math.floor(Math.random()*available.length)]}else QI=(QI+delta+QUEUE.length)%QUEUE.length;playCur()};
function wnLoop(){WN60.repeat=(WN60.repeat+1)%3;LOOP1=WN60.repeat===2;drawFP();hap()}
au.addEventListener('ended',event=>{event.stopImmediatePropagation();if(!CUR)return;if(WN60.repeat===2){au.currentTime=0;au.play().catch(()=>{})}else if(WN60.shuffle&&QUEUE.length>1||QI<QUEUE.length-1||WN60.repeat===1)nextTrack(1);else{miniUpd();drawFP()}},true);
const wnFx=fx8;fx8=async function(){if(wnProvider(CUR)!=='sc')return;return wnFx()};
drawFP=function(){if(!CUR)return;const root=document.getElementById('fp'),provider=wnProvider(CUR);root.classList.remove('py21-mode');root.style.setProperty('--fpbg',`url("${String(CUR.thumb||'').replace(/["\\]/g,'')}")`);const duration=Number.isFinite(au.duration)?au.duration:Number(CUR.dur)||0,position=Number.isFinite(au.currentTime)?au.currentTime:0;root.innerHTML=`<div class="wn-fp-top"><button onclick="closeFP()" aria-label="${h(wnT('back'))}">${wnIcon('back')}</button><span>${h(wnT('nowPlaying'))}</span><button onclick="wnQueueSheet()" aria-label="${h(wnT('queue'))}">${wnIcon('queue')}</button></div><div class="wn-player-art">${wnImage(CUR)}</div><div class="wn-player-info"><div><h1 dir="auto">${h(CUR.title||'Wakhan Music')}</h1><p dir="auto">${h(CUR.artist||CUR.ch||'')}</p></div><button onclick="favToggle('CUR',0,this)" aria-label="${h(wnT('like'))}">${wnIcon('heart')}</button></div><div class="wn-player-provider">${provider==='yt'?'YOUTUBE AUDIO':provider==='sc'?'SOUNDCLOUD AUDIO':'WAKHAN AUDIO'}</div><div class="wn-player-progress"><input type="range" id="fpr" aria-label="${h(wnT('sound'))}" min="0" max="${Math.floor(duration)}" value="${Math.floor(position)}" ${!CUR.ready||LOADING?'disabled':''} oninput="this._drag=1;document.getElementById('fpc').textContent=fmt(this.value)" onchange="this._drag=0;au.currentTime=+this.value"><div class="tm"><span id="fpc">${fmt(position)}</span><span id="fpd">${fmt(duration)}</span></div></div><div class="wn-player-controls"><button class="${WN60.shuffle?'on':''}" onclick="WN60.shuffle=!WN60.shuffle;drawFP()" aria-label="${h(wnT('shuffle'))}" aria-pressed="${WN60.shuffle}">${wnIcon('shuffle')}</button><button onclick="nextTrack(-1)" aria-label="${h(wnT('back'))}">${wnIcon('previous')}</button><button class="wn-main-play" id="fpp" onclick="togglePlay()" aria-label="${h(LOADING?wnT('loading'):au.paused?'Play':'Pause')}" ${LOADING||!CUR.ready?'disabled':''}>${wnIcon(LOADING?'clock':au.paused?'play':'pause')}</button><button onclick="nextTrack(1)" aria-label="${h(t('next')||wnT('tracks'))}">${wnIcon('next')}</button><button class="${WN60.repeat?'on':''}" onclick="wnLoop()" aria-label="${h(wnT('loop'))}" aria-pressed="${!!WN60.repeat}">${wnIcon('repeat')}${WN60.repeat===2?'<small>1</small>':''}</button></div><div class="wn-player-tools"><button onclick="wnSaveTrack('CUR',0)">${wnIcon('library')}${h(wnT('addTo'))}</button>${ME?.groups?.length?`<button onclick="toGroup('CUR',0)">${wnIcon('group')}${h(wnT('groups'))}</button>`:''}${provider==='sc'?`<button onclick="fx8()" aria-pressed="${!!FX8}" ${AP.busy||LOADING||!CUR.ready?'disabled':''}>${wnIcon('headphones')}8D · ${h(wnT(FX8?'on':'off'))}</button>`:''}</div><p class="wn-player-state" role="status">${h(LOADING?wnT('loading'):WN60.error)}</p>${WN60.error&&!LOADING?`<button class="wn-secondary" onclick="playCur()">${h(wnT('retry'))}</button>`:''}`};
openFP=function(){if(!CUR)return;document.getElementById('fp').classList.add('show');drawFP();setBack()};
closeFP=function(){document.getElementById('fp').classList.remove('show');setBack()};
miniUpd=function(){const mini=document.getElementById('mini');if(!CUR){mini.classList.remove('show');return}mini.classList.add('show');document.getElementById('mth').src=CUR.thumb||'/s/wn60_headphones.svg';document.getElementById('mt1').textContent=CUR.title||'Wakhan Music';document.getElementById('mt2').textContent=LOADING?wnT('loading'):CUR.artist||CUR.ch||'';document.getElementById('mpp').innerHTML=wnIcon(LOADING?'clock':au.paused?'play':'pause');document.getElementById('mpp').setAttribute('aria-label',au.paused?'Play':'Pause');const fp=document.getElementById('fpp');if(fp)fp.innerHTML=wnIcon(LOADING?'clock':au.paused?'play':'pause')};
for(const event of ['play','pause'])au.addEventListener(event,()=>{miniUpd();const current=document.getElementById('fpp');if(current)current.innerHTML=wnIcon(LOADING?'clock':au.paused?'play':'pause')});
function wnQueueSheet(){wnList('WN_QUEUE',QUEUE);sheet(`<h3>${wnIcon('queue')}${h(wnT('queue'))}</h3>${QUEUE.length?wnRows(QUEUE,'WN_QUEUE'):wnEmpty(wnT('empty'),'','queue')}`)}
favToggle=async function(list,index,button){const track=listOf(list)[index];if(!track)return;const found=(ME.favs||[]).find(r=>wnCanonical(r.url)===wnCanonical(track.url));if(button)button.disabled=true;try{const result=await api('/api/fav',found?{url:found.url,del:1}:{url:track.url,title:track.title,thumb:track.thumb||'',dur:track.dur||0,src:wnProvider(track)==='yt'?'Youtube':'Soundcloud'});if(!result.ok)throw Error(result.err);ME.favs=(ME.favs||[]).filter(r=>wnCanonical(r.url)!==wnCanonical(track.url));if(!found)ME.favs.unshift({...track});if(button?.isConnected){button.classList.toggle('on',!found);button.setAttribute('aria-pressed',String(!found))}toast(t(found?'fav_off':'fav_on'));if(TAB==='l'&&SUB?.kind==='favorites')wnLibrary()}catch(e){toast(wnT('failed'))}finally{if(button?.isConnected)button.disabled=false}};

