 const N=10;for(let i=0;i<N;i++){const q=i/(N-1),prof=Math.sin(q*Math.PI);const rr=r0+(q-.15)*w;
  const g=x.createLinearGradient(cx-rr,cx-rr,cx+rr,cx+rr);const hi=mix(m[1],m[0],.35+.65*prof),lo=mix(m[1],[0,0,0],.35*(1-prof));
