 for(let k=0;k<4;k++){const aa=-Math.PI/2+k*Math.PI/2,gx=cx+Math.cos(aa)*(r0+w*.35),gy=cx+Math.sin(aa)*(r0+w*.35),gr=w*(k?.42:.6);x.globalCompositeOperation="source-over";
