  x.lineWidth=R*.02;x.strokeStyle=rgba(m[0],1);x.stroke();const tw=Math.max(0,Math.sin(t*3+k*1.7));if(tw>.6){x.globalCompositeOperation="lighter";blob(x,gx-gr*.3,gy-gr*.3,gr*1.6*tw,[255,255,255],c1,.7*tw)}}
