 if(any)raf=requestAnimationFrame(frame)}
function kick(){if(!raf)raf=requestAnimationFrame(frame)}document.addEventListener('visibilitychange',kick);document.addEventListener('wk-overlay-changed',kick);
const scan=()=>{for(const c of document.querySelectorAll("canvas.wk-halo:not([data-ready])")){c.dataset.ready=1;setup(c)}kick()};
let scanPending=false;new MutationObserver(()=>{if(!scanPending){scanPending=true;requestAnimationFrame(()=>{scanPending=false;scan()})}}).observe(document.documentElement,{childList:true,subtree:true});
