/* ---------- level & rank: a badge for every rank, the level-up moment, the rank-up moment, +XP */
const RANKS=[['newcomer',1,'#C9CFD9','#7B8494'],['bronze',11,'#F1B98A','#8E5427'],['silver',21,'#F4F7FB','#8C9DB0'],['gold',31,'#FFE7A0','#C9921C'],['platinum',41,'#C7F5F7','#3E9FAA'],
 ['diamond',51,'#CFE3FF','#3D7BEA'],['master',61,'#E6D6FF','#7C4FD6'],['legend',71,'#FFD1E8','#C23F84'],['emperor',81,'#FFC9C3','#B23A33'],['sovereign',91,'#FFF1B8','#C9A23A']];
