 return `<svg class="rkb" viewBox="0 0 64 64" aria-label="${esc(tx('r_'+r[0]))}"><defs><linearGradient id="${g}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${r[2]}"/><stop offset="1" stop-color="${r[3]}"/></linearGradient></defs>
 <g fill="url(#${g})">${leaves}<g transform="translate(64 0) scale(-1 1)">${leaves}</g></g>
 <path d="M32 18l4.1 8.4 9.3 1.3-6.7 6.5 1.6 9.2L32 39l-8.3 4.4 1.6-9.2-6.7-6.5 9.3-1.3z" fill="url(#${g})" stroke="${r[3]}" stroke-width=".9" stroke-linejoin="round"/>
