function draw(offline){const v=host();if(!v)return;
 try{if(typeof TAB!=='undefined'&&TAB!=='m')return}catch(e){}
 const c=CARD||{name:(window.ME&&ME.me&&ME.me.name)||'',level:{level:1,xp:0,to:20,pct:0},stats:{},showcase:[]};
 v.innerHTML=page(c,offline);document.body.classList.add('wk3-on');bind(v.querySelector('.wk3'))}
