async function load(){
 gifts();
 try{const [r,k]=await Promise.all([api('/api/app/me/card'),api('/api/ctl/me').catch(()=>null)]);
  CTL=k&&k.ok?k:null;
  if(r&&r.ok){CARD=r;try{localStorage.setItem('me3_card',JSON.stringify(r))}catch(e){}draw(false);progressCheck(r)}else if(CARD)draw(true)}
 catch(e){if(CARD)draw(true)}}
