function install(){try{if(typeof rMe!=='function')return false;if(rMe.__me3)return true;rMe3.__me3=1;rMe=rMe3;window.rMe=rMe3;return true}catch(e){return false}}
const iv=setInterval(()=>{if(install()){clearInterval(iv);try{if(typeof TAB!=='undefined'&&TAB==='m')rMe3()}catch(e){}}},200);
setTimeout(()=>clearInterval(iv),20000);
