/* ---------- screen stack (Android back button closes the top one) */
const STACK=[];
function push(title,body,onBind){
 const el=document.createElement('div');el.className='s3';el.setAttribute('role','dialog');
 el.innerHTML=`<div class="s3-in"><div class="s3-hd"><h1>${esc(title)}</h1><button class="s3-bk" data-x="back" aria-label="back">${sv('bkL')}</button></div><div class="s3-b">${body}</div></div>`;
 document.body.appendChild(el);STACK.push(el);document.body.classList.add('s3-open');
 try{history.pushState({s3:STACK.length},'')}catch(e){}
 el.addEventListener('click',e=>{const b=e.target.closest('[data-x]');if(!b)return;if(b.dataset.x==='back'){back();return}const f=el.__acts&&el.__acts[b.dataset.x];if(f){try{hap()}catch(_){}f(b)}});
 if(onBind)onBind(el);return el}
function drop(){const el=STACK.pop();if(!el)return;el.classList.add('out');setTimeout(()=>el.remove(),180);if(!STACK.length)document.body.classList.remove('s3-open')}
function back(){if(!STACK.length)return;try{history.back()}catch(e){drop()}}
addEventListener('popstate',()=>{if(STACK.length)drop()});
const setBody=(el,html)=>{const b=el.querySelector('.s3-b');if(b)b.innerHTML=html};

/* ---------- the main settings screen, rows exactly as in the picture */
const R=(id,icon)=>`<button class="s3-row" data-x="${id}"><span class="s3-ic">${sv(icon)}</span><span class="s3-tx"><b>${esc(tx(id))}</b><small>${esc(tx(id+'_d'))}</small></span><span class="s3-ch">${sv('chevl')}</span></button>`;
const G=(t,rows)=>`<div class="s3-gt">${esc(tx(t))}</div><div class="s3-card">${rows}</div>`;
function main(){
 const body=G('g1',R('lang','languages')+R('theme','palette')+R('notif','bell')+R('play','sliders'))+
  G('g2',R('motion','zapoff')+R('data','wifi')+R('cache','drive'))+
  G('g3',R('vis','eye')+R('perm','users')+R('blocked','ban'))+
  G('g4',R('login','key')+R('tfa','shield')+R('dev','phone'))+
  G('g5',R('help','headset')+R('terms','file')+R('about','info'))+
  `<button class="s3-out" data-x="logout"><span>${esc(tx('logout'))}</span>${sv('out')}</button><button class="s3-del" data-x="del">${esc(tx('del'))}</button><div class="s3-ver">${VERSION}</div>`;
 const el=push(tx('title'),body);el.__acts=ACTS;return el}

/* ---------- what each row does */
const ME=()=>window.ME3||{};
const ACTS={
 lang(){try{ME().ACT.lang()}catch(e){try{langSheet()}catch(_){}}},
 theme(){if(window.ME3_PAGES&&ME3_PAGES.theme)return ME3_PAGES.theme((ME().card&&ME().card())||{});say(tx('soon'))},
 notif:pgNotif,
 play(){if(window.ME3_PAGES&&ME3_PAGES.playback)return ME3_PAGES.playback();pgPlay()},
 motion(){pgSwitch('motion','wk_rm','motion_x')},
 data:pgData,
 cache:pgCache,
