/* notifications: the real permission of this phone */
async function pushState(){
 try{const P=window.Capacitor&&Capacitor.Plugins&&Capacitor.Plugins.PushNotifications;if(P&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform()){const p=await P.checkPermissions();return {native:1,st:p.receive}}}catch(e){}
 try{if('Notification' in window)return {native:0,st:Notification.permission==='default'?'prompt':Notification.permission}}catch(e){}
 return {native:0,st:'none'}}
async function pgNotif(){
 const el=push(tx('notif'),`<div class="s3-empty">${esc(tx('loading'))}</div>`);let P=null;
 const sw=(k,on)=>`<div class="s3-kv"><b>${esc(tx('np_'+k))}</b><button class="s3-sw" role="switch" aria-checked="${!!on}" data-x="np" data-k="${k}"${P?'':' disabled'}></button></div>`;
 const draw=async()=>{const s=await pushState();const on=s.st==='granted';
  let html=`<div class="s3-card"><div class="s3-kv"><b>${esc(tx('notif'))}</b><span class="${on?'ok':''}">${esc(on?tx('on'):tx('off'))}</span></div><div class="s3-p">${esc(tx('n_info'))}${s.st==='denied'?'<br><br>'+esc(tx('n_denied')):''}${!s.native?'<br><br>'+esc(tx('n_web')):''}</div></div>`;
  if(!on&&s.st!=='denied'&&s.st!=='none')html+=`<button class="s3-btn" data-x="ask">${esc(tx('n_ask'))}</button>`;
  if(P){const n=P.notifications||{};html+=`<div class="s3-gt" style="margin-top:22px">${esc(tx('np_t'))}</div><div class="s3-card">${['dm','friends','gifts','previews'].map(k=>sw(k,n[k])).join('')}${P.phone_push_configured===false?`<div class="s3-p">${esc(tx('np_wait'))}</div>`:''}</div>`}
  setBody(el,html)};
 el.__acts={
  ask:async()=>{try{if(window.WakhanEnablePush){await WakhanEnablePush()}else if(window.Capacitor&&Capacitor.Plugins&&Capacitor.Plugins.PushNotifications&&Capacitor.isNativePlatform()){const Pn=Capacitor.Plugins.PushNotifications;const p=await Pn.requestPermissions();if(p.receive==='granted')await Pn.register()}else if('Notification' in window)await Notification.requestPermission()}catch(e){}draw()},
  async np(b){const k=b.dataset.k,v=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',v);b.disabled=true;
   try{const r=await call('/api/app/preferences',{[k]:v});if(!r||!r.ok)throw 0;P.notifications[k]=v;say(tx('np_saved'))}catch(e){b.setAttribute('aria-checked',!v);say(tx('err'))}b.disabled=false}};
 draw();try{const r=await call('/api/app/preferences');if(r&&r.ok){P=r;P.notifications=P.notifications||{};draw()}}catch(e){}}

/* data usage: data saver + appearance & data (automatic / light / full — the device render mode) */
function pgData(){
 const v=()=>ls.get('wk_ds')==='1';const RM=window.WakhanRenderMode;
 const opt=(k)=>`<button class="s3-row s3-opt" data-x="rm" data-v="${k}"><span class="s3-tx"><b>${esc(tx('rm_'+k))}</b><small>${esc(tx('rm_'+k+'_d'))}</small></span><span class="s3-rd${RM&&RM.preference===k?' on':''}"></span></button>`;
 const html=()=>`<div class="s3-card"><div class="s3-kv"><b>${esc(tx('data'))}</b><button class="s3-sw" role="switch" aria-checked="${v()}" data-x="t" aria-label="${esc(tx('data'))}"></button></div><div class="s3-p">${esc(tx('data_x'))}</div></div>
  ${RM&&RM.setPreference?`<div class="s3-gt">${esc(tx('rm'))}</div><div class="s3-card">${['auto','lite','full'].map(opt).join('')}<div class="s3-p">${esc(tx('rm_x'))}</div></div>`:''}`;
 const el=push(tx('data'),html());
 el.__acts={t(){ls.set('wk_ds',v()?null:'1');applyPrefs();setBody(el,html())},rm(b){try{RM.setPreference(b.dataset.v)}catch(e){}setBody(el,html())}}}

/* playback: voice connection of the halls (more settings come with item 11) */
function pgPlay(){const el=push(tx('play'),`<div class="s3-card"><button class="s3-row" data-x="vc"><span class="s3-ic">${sv('sliders')}</span><span class="s3-tx"><b>${esc(tx('vc'))}</b><small>${esc(tx('vc_d'))}</small></span><span class="s3-ch">${sv('chevl')}</span></button></div><div class="s3-p" style="padding:0 4px">${esc(tx('pl_x'))}</div>`);
