/* on/off switch pages (reduce motion, data saver) */
function pgSwitch(id,key,x){
 const v=()=>ls.get(key)==='1';
 const html=()=>`<div class="s3-card"><div class="s3-kv"><b>${esc(tx(id))}</b><button class="s3-sw" role="switch" aria-checked="${v()}" data-x="t" aria-label="${esc(tx(id))}"></button></div><div class="s3-p">${esc(tx(x))}</div></div>`;
 const el=push(tx(id),html());
 el.__acts={t(){ls.set(key,v()?null:'1');applyPrefs();setBody(el,html())}}}

/* temporary storage: Cache Storage + saved screen data — never the sign-in */
const KEEP=/^(wka|wk_native|wkt_active|wk_rm|wk_ds|auth|token|session|sid|lang|LG)/i;
async function cacheSize(){let n=0;try{if(navigator.storage&&navigator.storage.estimate){const e=await navigator.storage.estimate();n=e.usage||0}}catch(e){}
 try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(!KEEP.test(k))n+=(localStorage.getItem(k)||'').length*2}}catch(e){}return n}
const mb=n=>n<1024*1024?(n/1024).toFixed(0)+' KB':(n/1048576).toFixed(1)+' MB';
async function pgCache(){
 const el=push(tx('cache'),`<div class="s3-empty">${esc(tx('loading'))}</div>`);
 const draw=async()=>setBody(el,`<div class="s3-card"><div class="s3-kv"><b>${esc(tx('cache_size'))}</b><span>${mb(await cacheSize())}</span></div><div class="s3-p">${esc(tx('cache_x'))}</div></div><button class="s3-btn soft" data-x="clr">${esc(tx('cache_btn'))}</button>`);
 el.__acts={clr:async()=>{
  try{if(window.caches){const ks=await caches.keys();await Promise.all(ks.map(k=>caches.delete(k)))}}catch(e){}
  try{const del=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(/^(me3_|wm70_cache|wk_cache|img_)/.test(k))del.push(k)}del.forEach(k=>localStorage.removeItem(k))}catch(e){}
  say(tx('cache_done'));draw()}};
 draw()}

/* privacy: saved on the server (/api/app/me/profile) */
async function pgPrivacy(id,keys,x){
 const el=push(tx(id),`<div class="s3-empty">${esc(tx('loading'))}</div>`);let P={};
 const draw=()=>setBody(el,`<div class="s3-card">${keys.map(k=>`<div class="s3-kv"><b>${esc(tx('p_'+k))}</b><div class="s3-seg">${['all','friends','none'].map(v=>`<button class="${(P[k]||'all')===v?'on':''}" data-x="set" data-k="${k}" data-v="${v}">${esc(tx('v_'+v))}</button>`).join('')}</div></div>`).join('')}<div class="s3-p">${esc(tx(x))}</div></div>`);
 el.__acts={async set(b){const k=b.dataset.k,v=b.dataset.v;const old=P[k];P[k]=v;draw();
  try{const r=await call('/api/app/me/profile',{privacy:{[k]:v}});if(r&&r.ok){P=r.privacy||P;draw();say(tx('saved'))}else throw 0}catch(e){P[k]=old;draw();say(tx('err'))}}};
 try{const r=await call('/api/app/me/profile');if(r&&r.ok){P=r.privacy||{};draw()}else throw 0}catch(e){setBody(el,`<div class="s3-empty">${esc(tx('err'))}</div>`)}}

