 try{
  if(F.photo!==undefined){const r=await call('/api/app/me/avatar',F.photo===null?{reset:true}:{avatar:F.photo});
   if(r&&r.ok){S.avatar=r.avatar||'';S.custom_avatar=F.photo!==null;F.photo=undefined}else{ok=false;say(tx(r&&r.err)||tx('err'))}}
