  if(Object.keys(body).length){const r=await call('/api/app/me/edit',body);if(!r)throw 0;
   const E=r.errors||{};
   if(r.name!=null&&!E.name)S.name=r.name;if(r.username!=null&&!E.username)S.username=r.username;if(r.bio!=null&&!E.bio)S.bio=r.bio;if(r.public!=null&&!E.public)S.public=r.public;if(r.username_next!=null)S.username_next=r.username_next;
   if(!E.name)F.name=S.name;if(!E.bio)F.bio=S.bio;
