   if(E.username)msg('e3um',E.username==='username_wait'?tx('u_wait',{d:date(r.username_next)}):tx({username_taken:'u_taken',username_bad:'u_bad'}[E.username]||'err'),'bad')}
 }catch(e){ok=false;say(tx('err'))}
