/* tiny QR code maker (byte mode, error level M, versions 1–6, best mask) — returns an SVG string.
   Used for «دریافت سکه»: the code holds only https://<site>/u/<WAKHAN ID>. */
(()=>{'use strict';if(window.QR3)return;
const DATA=[0,16,28,44,64,86,108],BLOCKS=[0,1,1,1,2,2,4],ECB=[0,10,16,26,18,24,16],ALIGN=[0,0,18,22,26,30,34];
