 finder(3,3);finder(size-4,3);finder(3,size-4);
 for(let i=8;i<size-8;i++){set(6,i,i%2===0);set(i,6,i%2===0)}
 if(ALIGN[v]){const p=[6,ALIGN[v]];p.forEach(ax=>p.forEach(ay=>{if((ax===6&&ay===6)||(ax===6&&ay===p[1]&&false))return;if(F[ay][ax])return;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)set(ax+dx,ay+dy,Math.max(Math.abs(dx),Math.abs(dy))!==1)}))}
