const css=`
.bk{--bk-on:#fff;--bk-a:var(--wk-accent,#A855F7);--bk-a2:color-mix(in srgb,var(--bk-a) 55%,var(--wk-text));--bk-soft:color-mix(in srgb,var(--bk-a) 14%,var(--wk-surface));--bk-line:color-mix(in srgb,var(--bk-a) 30%,var(--wk-border));--bk-ok:#3BE07A;--bk-bad:#FF4D5E;--bk-gold:#F5C451}
