.s3.bk .s3-bk{position:absolute!important;left:-6px;right:auto;top:6px;width:40px;height:40px;display:grid!important;place-items:center}
.s3.bk .s3-bk svg{width:24px;height:24px}
.s3.bk .bk-hx{position:absolute!important;right:-6px;top:6px;width:40px;height:40px;display:grid!important;place-items:center;color:var(--wk-text)}
.s3.bk .bk-hx svg{width:22px;height:22px}
.bk-c{width:1em;height:1em;flex:none;vertical-align:-.14em}
/* cards */
.bk-hero{position:relative;display:flex;align-items:center;min-height:118px;border-radius:18px;overflow:hidden;border:1px solid var(--bk-line);background:radial-gradient(120% 140% at 85% 30%,color-mix(in srgb,var(--bk-a) 34%,transparent),transparent 60%),linear-gradient(135deg,color-mix(in srgb,var(--bk-a) 22%,var(--wk-surface)),var(--wk-surface));box-shadow:0 0 22px color-mix(in srgb,var(--bk-a) 22%,transparent)}
.bk-hero img{position:absolute;top:50%;transform:translateY(-50%);height:118%;pointer-events:none}
.bk-bal{flex:1;padding:18px 18px 18px 0;text-align:center;direction:var(--wk-dir,rtl)}
.bk-bal small{display:block;font-size:14px;color:var(--wk-text2);margin-bottom:6px}
