.s3 .bk-act button svg,.s3 .bk-q button svg{width:24px;height:24px}
.s3 .bk-act button.on{background:var(--bk-soft)!important;border-color:var(--bk-a)!important;box-shadow:0 0 14px color-mix(in srgb,var(--bk-a) 35%,transparent)}
