/* life: gentle float, a light sweep over the art, twinkles, soft glow — transform/opacity only; off with «کاهش حرکت» */
.bk-live{position:absolute;top:50%;height:118%;aspect-ratio:var(--ar,1);transform:translateY(-50%);pointer-events:none}
