.bk-empty{padding:26px 10px;text-align:center;font-size:13.5px;color:var(--wk-text2)}`;
try{const s=document.createElement('style');s.id='bk3-css';s.textContent=css;document.head.appendChild(s)}catch(e){}

/* ---------- page shell: back on the left, title with icon, small subtitle, optional right button */
function page(title,icon,sub,body,right){
 const el=SET3.push(title,body);el.classList.add('bk');
 const hd=el.querySelector('.s3-hd');
 hd.innerHTML=`<button class="s3-bk" data-x="back" aria-label="back">${sv('back')}</button><div class="bk-t"><span>${esc(title)}</span>${icon}</div>${sub?`<div class="bk-sub">${esc(sub)}</div>`:''}${right||''}`;
 el.__acts={};return el}
const set=(el,h)=>SET3.setBody(el,h);
/* the same picture, only brought to life (float + light sweep + twinkles) */
const live=(n,style,ar)=>`<span class="bk-live" style="${style};--ar:${ar||1};--m:url('${ART(n)}')"><span class="fl"><span class="gl"></span><img src="${ART(n)}" alt=""><span class="sh"></span><b class="sp" style="top:14%;right:18%"></b><b class="sp b" style="top:62%;left:10%"></b><b class="sp c" style="top:30%;left:22%"></b></span></span>`;
const amt=(n,cls='')=>`<span class="bk-amt ${n>0?'p':n<0?'m':''} ${cls}">${sgn(n)} ${COIN}</span>`;

/* ---------- data */
let D=null;
async function load(force){if(D&&!force)return D;const r=await call('/api/app/bk');if(!r||!r.ok)throw 0;D=r;return D}
const KIND={reward:['cal','k_reward'],code:['qrs','k_code'],topup:['plus','k_topup'],buy:['plus','k_topup'],in:['down','k_in'],out:['swap','k_out'],gift_in:['gift','k_gift_in'],gift_out:['gift','k_gift_out'],item:['shirt','k_item'],vip:['shirt','k_vip'],admin:['gift','k_admin']};
function row(t){const k=KIND[t.kind]||['swap','k_other'];const u=t.other&&t.other.username?'@'+t.other.username:(t.other&&t.other.name)||'';
 return `<button class="bk-tx" data-x="tx" data-i="${esc(t.id)}"><span class="ic">${sv(k[0])}</span><span class="tt"><b>${esc(tx(k[1],{u}))}</b><small>${esc(when(t.ts))}</small></span>${amt(+t.coins)}</button>`}

/* ---------- 1. home */
async function home(){
 const el=page(tx('wallet'),COINS,tx('wallet_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`,`<button class="bk-hx" data-x="menu" aria-label="menu">${sv('dots')}</button>`);
 el.__acts={buy:()=>buy(),gift:()=>say(tx('soon')),transfer:()=>transfer(),history:()=>history(),special:()=>services(),closet:()=>closet(),vip:()=>vip(),all:()=>history(),tx:b=>details(b.dataset.i),menu:()=>menu()};
 const draw=d=>set(el,`
  <div class="bk-hero">${live('coin','right:-4px',306/270)}<div class="bk-bal" style="padding-right:150px;padding-left:10px"><small>${esc(tx('bal'))}</small><b>${num(d.balance)} ${COIN}</b></div></div>
  <div class="bk-act"><button class="on" data-x="buy">${sv('plus')}<span>${esc(tx('buy'))}</span></button><button data-x="gift">${sv('gift')}<span>${esc(tx('gift'))}</span></button><button data-x="transfer">${sv('swap')}<span>${esc(tx('transfer'))}</span></button><button data-x="history">${sv('hist')}<span>${esc(tx('history'))}</span></button></div>
  <div class="bk-info"><img class="bk-bob" src="${ART('chest')}" alt=""><div class="tx"><h3><span class="bk-wb">W</span>${esc(tx('coin_t'))}</h3><p>${esc(tx('coin_s'))}</p><ul class="bk-ck">${['coin_1','coin_2','coin_3','coin_4'].map(k=>`<li>${sv('check')}<span>${esc(tx(k))}</span></li>`).join('')}</ul></div></div>
  <div class="bk-h"><b>${esc(tx('quick'))}${sv('bolt')}</b></div>
  <div class="bk-q"><button data-x="special">${sv('game')}<span>${esc(tx('special'))}</span></button><button data-x="gift">${sv('gift')}<span>${esc(tx('gift'))}</span></button><button data-x="closet">${sv('shirt')}<span>${esc(tx('closet'))}</span></button><button data-x="vip">${sv('crown','g')}<span>${esc(tx('vipUp'))}</span></button></div>
  <div class="bk-h"><b>${sv('list')}${esc(tx('last'))}</b><button data-x="all">${esc(tx('all'))}${sv('back')}</button></div>
  ${(d.history||[]).slice(0,3).map(row).join('')||`<div class="bk-empty">${esc(tx('empty'))}</div>`}`);
 try{draw(await load(true))}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}}

/* ---------- 2. buy coins */
const METHODS=[['apple',`<span class="lg" style="font-family:-apple-system,system-ui"> Pay</span>`],['card',`<span class="lg"><svg viewBox="0 0 40 24" width="40" height="24"><circle cx="15" cy="12" r="9" fill="#EB001B"/><circle cx="25" cy="12" r="9" fill="#F79E1B" fill-opacity=".9"/></svg></span>`],['paypal',`<span class="lg" style="color:#2B7BE5;font-style:italic;font-family:Arial,sans-serif">P</span>`],['crypto',`<span class="lg"><svg viewBox="0 0 24 24" width="30" height="30"><circle cx="12" cy="12" r="11" fill="#26A17B"/><path d="M6.5 7h11M12 7v11M8 11c0 1 1.8 1.6 4 1.6s4-.6 4-1.6" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg></span>`]];
async function buy(){
 const el=page(tx('buy'),sv('bag'),tx('buy_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`,`<button class="bk-hx" data-x="orders" aria-label="history">${sv('receipt')}</button>`);
 let d,pick=null,meth=null;
 const isApple=/iPhone|iPad|Macintosh/.test(navigator.userAgent);
 const mlabel=m=>m==='apple'?(isApple?tx('m_apple'):tx('m_google')):tx('m_'+m);
 const draw=()=>{const P=d.packs||[];if(pick==null){const h=P.find(p=>p.hot===1);pick=h?h.id:P[0]&&P[0].id}
  const M=d.methods||{};if(!meth)meth='apple';
  set(el,`<div class="bk-promo">${live('promo','left:0;height:104%',360/231)}<div class="tx"><small>${sv('diamond')}${esc(tx('pack'))}</small><b><em>+${Math.max(0,...P.map(p=>p.bonus||0))}%</em> ${esc(tx('more'))}</b></div></div>
   <div class="bk-packs">${P.map(p=>`<button class="bk-pk ${p.id===pick?'on bk-pulse':''}" data-x="pk" data-i="${esc(p.id)}"><span class="bk-pr">${esc(p.price)}</span><span class="bk-pc">${num(p.coins)} ${COIN}</span><span class="bk-bn ${p.hot?'hot':''}">+${p.bonus||0}%${p.hot===1?'🔥':p.hot===2?sv('crown'):''}</span></button>`).join('')}</div>
   <div class="bk-h"><b>${sv('card')}${esc(tx('pay'))}</b></div>
   <div class="bk-m">${METHODS.map(([k,lg])=>`<button class="${k===meth?'on':''} ${M[k]?'':'off'}" data-x="m" data-i="${k}">${k===meth?`<span class="tick">${sv('check')}</span>`:''}${k==='apple'&&!isApple?`<span class="lg">G Pay</span>`:lg}<span>${esc(mlabel(k))}</span></button>`).join('')}</div>
   <button class="bk-go" data-x="pay">${sv('cart')}<span>${esc(tx('buyPay'))}</span></button>
   ${M[meth]?'':`<div class="bk-note">${esc(meth==='apple'?tx('m_store'):tx('m_soon'))}</div>`}`)};
 el.__acts={pk(b){pick=b.dataset.i;draw()},m(b){meth=b.dataset.i;draw()},orders:()=>history('buy'),
  async pay(b){const M=d.methods||{};if(!M[meth]){say(meth==='apple'?tx('m_store'):tx('m_soon'));return}
