/* QR: phones with a camera reader scan a friend's Wakhan code (wakhan://u/<WAKHAN ID>) */
async function scan(done){
 if(!('BarcodeDetector' in window)){say(tx('qr_no'));return}
 let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}})}catch(e){say(tx('qr_no'));return}
 const d=document.createElement('div');d.className='e3-crop';d.style.background='#000';
 d.innerHTML=`<div class="hd"><button data-c="0">${esc(tx('cancel'))}</button><b>${esc(tx('t_qr'))}</b><span></span></div><div class="st"><video playsinline muted style="width:100%;height:100%;object-fit:cover"></video></div>`;
 document.body.appendChild(d);const v=d.querySelector('video');v.srcObject=stream;await v.play().catch(()=>{});
 const det=new BarcodeDetector({formats:['qr_code']});let live=true;
 const stop=()=>{live=false;stream.getTracks().forEach(t=>t.stop());d.remove()};d.querySelector('[data-c]').onclick=stop;
 const tick=async()=>{if(!live)return;try{const c=await det.detect(v);const m=c[0]&&String(c[0].rawValue).match(/(?:wakhan:\/\/u\/|\/u\/)(\d{8})/);
  if(m){stop();const r=await call('/api/app/bk/user?q='+m[1]);if(r&&r.items&&r.items[0])done(r.items[0]);else say(tx('nouser'));return}}catch(e){}setTimeout(tick,350)};tick()}

