const ago=t=>{const d=Math.max(0,Date.now()/1000-t);if(d<60)return tx('now');if(d<3600)return tx('ago_m',{n:Math.floor(d/60)});if(d<86400)return tx('ago_h',{n:Math.floor(d/3600)});return tx('ago_d',{n:Math.floor(d/86400)})};
const giftArt=code=>{try{if(typeof wm70GiftArt==='function'){const a=wm70GiftArt(code);if(a)return a}}catch(e){}return sv('gift')};
const copyTxt=async v=>{try{await navigator.clipboard.writeText(v)}catch(e){const t=document.createElement('textarea');t.value=v;t.style.cssText='position:fixed;opacity:0';document.body.appendChild(t);t.select();try{document.execCommand('copy')}catch(_){}t.remove()}say(tx('copied'))};
const shareTxt=async(text,url)=>{try{if(navigator.share){await navigator.share({text,url});return}}catch(e){return}copyTxt(url?text+' '+url:text)};
const R2=(x,icon,t,d,tail)=>`<button class="bk-row" data-x="${x}"><span class="ic">${sv(icon)}</span><span class="tt"><b>${esc(t)}</b>${d?`<small>${esc(d)}</small>`:''}</span>${tail==null?`<span class="ch">${sv('back')}</span>`:tail}</button>`;
const errMsg=e=>tx(e)!==e?tx(e):tx('err');

