/* 1. received gifts */
async function gifts(){
 const el=page(tx('g_t'),sv('gift'),tx('g_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`);let f='all',items=[],next=null;
 const draw=()=>set(el,`<div class="bk-fil">${['all','gift','coins','vip'].map(k=>`<button class="${k===f?'on':''}" data-x="f" data-i="${k}">${esc(tx('g_'+k))}</button>`).join('')}</div>
  ${items.map(g=>`<button class="bk-gf" data-x="one" data-i="${esc(g.id)}"><span class="av">${g.from&&g.from.avatar?`<img src="${esc(g.from.avatar)}" alt="" loading="lazy">`:esc(String((g.from&&g.from.name)||'W').charAt(0))}</span>
   <span class="tt"><b>@${esc((g.from&&(g.from.username||g.from.name))||'')}</b><span>${sv('back')}${esc(tx(g.kind==='coins'?'g_coin_sent':'g_sent'))}</span><small>${esc(ago(g.ts))}</small></span>
   <span class="gi"><span class="art">${g.kind==='coins'?COIN.replace('class="bk-c"','class="bk-c" style="width:40px;height:40px"'):giftArt(g.code)}</span>${amt(+g.coins).replace(/class="bk-amt [pm]/,'class="bk-amt').replace(/[+-](?=\d)/,'')}</span></button>`).join('')||`<div class="bk-empty">${esc(tx('g_none'))}</div>`}
  ${next?`<button class="bk-go" style="height:44px;font-size:14px!important" data-x="more">${esc(tx('all'))}</button>`:''}`);
 const get=async more=>{try{const r=await call('/api/app/bk/gifts?f='+f+(more&&next?'&before='+next:''));if(!r||!r.ok)throw 0;items=more?items.concat(r.items):r.items;next=r.next||null;draw()}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}};
 el.__acts={f(b){f=b.dataset.i;items=[];draw();get()},more:()=>get(true),one(b){const g=items.find(x=>x.id===b.dataset.i);if(g&&g.op)details(g.op)}};
 get()}

