async function free(){
 const el=page(tx('fr_t'),sv('cal'),tx('fr_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`);let d;
 const mt=m=>tx('m_'+m.id,{n:m.goal});
 const draw=()=>{const dy=d.daily||{};
  set(el,`<div class="bk-rw">${live('reward','right:4px',396/306)}<div style="width:52%;margin-right:auto;text-align:center"><h4>${esc(tx('daily'))}</h4><div class="v">+${num(dy.coins)} ${COIN}</div></div>
   <button class="bk-go" data-x="daily" ${dy.ready?'':'disabled'}>${esc(dy.ready?tx('daily_go'):tx('daily_done'))}</button></div>
   <div class="bk-h"><b>${esc(tx('missions'))}</b></div>
   ${(d.missions||[]).map(m=>`<div class="bk-mi"><span class="ic ${m.state==='claimed'?'ok':''}">${m.state==='claimed'?sv('check'):m.state==='ready'?sv('gift'):`${Math.min(m.progress,m.goal)}/${m.goal}`}</span>
    <span class="tt"><b>${esc(mt(m))}</b><small>${esc(tx('done_n',{a:Math.min(m.progress,m.goal),b:m.goal}))}</small><div class="bk-bar"><i style="width:${Math.round(Math.min(1,m.progress/m.goal)*100)}%"></i></div></span>
    ${m.state==='ready'?`<button class="cl" data-x="claim" data-i="${esc(m.id)}">${esc(tx('claim'))}</button>`:m.state==='claimed'?`<span class="cd">${esc(tx('claimed'))}</span>`:''}
    <span class="rw">+${num(m.coins)} ${COIN}</span></div>`).join('')}`)};
 const claim=async(id,b)=>{if(b)b.disabled=true;try{const r=await call('/api/app/bk/free',{id});if(r&&r.ok){d=r;D=null;draw();if(r.got)say(tx('got',{n:num(r.got)}))}else{say(errMsg(r&&r.err));if(b)b.disabled=false}}catch(e){say(tx('err'));if(b)b.disabled=false}};
 el.__acts={daily:b=>claim('daily',b),claim:b=>claim(b.dataset.i,b)};
 try{d=await call('/api/app/bk/free');if(!d||!d.ok)throw 0;draw()}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}}

