/* 4. deposit with code (one-time codes; the server checks expiry and uses) */
function redeem(){
 const el=page(tx('rd_t'),sv('qrs'),tx('rd_s'),`<div class="bk-bob"><img class="bk-art" src="${ART('ticket')}" alt="" style="width:66%"></div>
  <div class="bk-cbox"><label>${esc(tx('rd_in'))}</label><input id="bkcode" placeholder="WAKHAN-XXXX-XXXX-XXXX" maxlength="24" autocomplete="off" autocapitalize="characters" spellcheck="false">
  <button class="bk-sc" data-x="scan">${sv('scan')}<span>${esc(tx('rd_scan'))}</span></button></div>
  <div class="bk-note">${esc(tx('rd_hint'))}</div>
  <button class="bk-go" data-x="go">${esc(tx('rd_go'))}</button><div id="bkst"></div>`);
 const inp=el.querySelector('#bkcode');inp.oninput=()=>{const v=inp.value.toUpperCase().replace(/[^A-Z0-9]/g,'');let s=v.startsWith('WAKHAN')?v.slice(6):v;s=s.slice(0,12).replace(/(.{4})(?=.)/g,'$1-');inp.value=s?'WAKHAN-'+s:v.slice(0,6)};
 el.__acts={scan:()=>scanText(t=>{inp.value=t;inp.oninput()}),
  async go(b){const code=inp.value.trim();if(code.length<10){say(tx('code_bad'));return}b.disabled=true;
   try{const r=await call('/api/app/bk/redeem',{code});const st=el.querySelector('#bkst');
    if(r&&r.ok){D=null;inp.value='';st.innerHTML=`<div class="bk-msg" style="color:var(--bk-ok)">${esc(tx('rd_ok',{n:num(r.coins)}))}</div>`}
    else st.innerHTML=`<div class="bk-msg" style="color:var(--bk-bad)">${esc(errMsg(r&&r.err))}</div>`}catch(e){say(tx('err'))}b.disabled=false}}}
/* reads any QR text (for codes) */
async function scanText(done){
 if(!('BarcodeDetector' in window)){say(tx('qr_no'));return}
 let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}})}catch(e){say(tx('qr_no'));return}
 const d=document.createElement('div');d.className='e3-crop';d.innerHTML=`<div class="hd"><button data-c="0">${esc(tx('cancel'))}</button><b>${esc(tx('rd_scan'))}</b><span></span></div><div class="st"><video playsinline muted style="width:100%;height:100%;object-fit:cover"></video></div>`;
 document.body.appendChild(d);const v=d.querySelector('video');v.srcObject=stream;await v.play().catch(()=>{});
 const det=new BarcodeDetector({formats:['qr_code']});let alive=true;const stop=()=>{alive=false;stream.getTracks().forEach(t=>t.stop());d.remove()};d.querySelector('[data-c]').onclick=stop;
 const tick=async()=>{if(!alive)return;try{const c=await det.detect(v);if(c[0]){stop();done(String(c[0].rawValue).slice(0,64));return}}catch(e){}setTimeout(tick,350)};tick()}

