let S=null;
async function load(force){if(S&&!force)return S;const q=await api('/api/app/sub');if(!q||!q.ok)throw 0;S=q;return S}
const plans=t=>(S.plans||[]).filter(p=>p.tier===t).sort((a,b)=>a.months-b.months);
const price=p=>p?(p.price||'—'):'—';
const off=p=>{const m=plans(p.tier).find(x=>x.months===1);if(!m||p.months===1||!m.eur||!p.eur)return 0;const r=Math.round((1-(+p.eur)/((+m.eur)*p.months))*100);return r>0?r:0};
const lbl=t=>NAME[t]||t;
const fail=el=>set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`);
const wrap=(title,icon,sub,fn,right)=>{const el=page(title,icon,sub,`<div class="bk-empty">${esc(tx('loading'))}</div>`,right);el.classList.add('sb');load(true).then(()=>fn(el)).catch(()=>fail(el));return el};

/* 1. home */
function home(){wrap(tx('s_home'),sv('crownl').replace('<svg','<svg style="color:#F5C451"'),tx('s_home_s'),el=>{
 set(el,`<img class="sb-hero" src="${ART('crest')}" alt=""><div class="sb-int"><b>${esc(tx('s_intro_t'))}</b><p>${esc(tx('s_intro'))}</p></div>
  ${R2('buy','cart',tx('s_buy'),tx('s_buy_d'))}${R2('ben','gem',tx('s_ben'),tx('s_ben_d'))}${R2('mine','person',tx('s_mine'),tx('s_mine_d'))}`);
 el.__acts={buy:()=>pick(),ben:()=>benefits(),mine:()=>mine()}})}
/* 2. choose a plan */
function pick(){wrap(tx('s_pick'),'',tx('s_pick_s'),el=>{
 set(el,ORDER.map(t=>`<button class="sb-plan ${t}" data-x="t" data-i="${t}"><img src="${ART(t)}" alt="" loading="lazy"><span class="tt"><b>${lbl(t)}</b><small>${esc(tx('d_'+t))}</small></span><span class="ch">${sv('fwd')}</span></button>`).join('')
  +`<button class="bk-row" data-x="cmp"><span class="ic">${sv('list')}</span><span class="tt"><b>${esc(tx('s_cmp_btn'))}</b></span><span class="ch">${sv('back')}</span></button>`);
 el.__acts={t:b=>details(b.dataset.i),cmp:()=>compare()}})}
/* 3. compare — rows only for benefits the server has on */
function compare(){wrap(tx('s_cmp'),'',tx('s_cmp_s'),el=>{const B=(S.benefits||[]).filter(b=>b.tiers&&b.tiers.length);const T3=['royal','premium','vip'];
 set(el,`<div class="sb-cmp"><div class="sb-ch">${T3.map(t=>`<div class="${t}"><img src="${ART(t)}" alt="">${lbl(t)}</div>`).join('')}<span></span></div>
  ${B.map(b=>`<div class="sb-cr">${T3.map(t=>b.tiers.includes(t)?`<i class="y ${t}">${sv('check')}</i>`:'<i>—</i>').join('')}<span>${esc(tx('b_'+b.id))}</span></div>`).join('')}
  <div class="sb-cp">${T3.map(t=>`<b class="${t}">${esc(price(plans(t)[0]))}</b>`).join('')}<span>${esc(tx('monthly'))}</span></div></div>`)})}
/* 4. plan details */
function details(t,pre){let sel=pre||1;wrap(lbl(t),'',tx('s_det_s',{t:lbl(t)}),el=>{
 const B=(S.benefits||[]).filter(b=>(b.tiers||[]).includes(t));
 const draw=()=>{const P=plans(t);set(el,`<div class="sb-dh" style="--sb-name:${t==='royal'?'#F5C451':'var(--wk-text)'}"><img src="${ART(t==='premium'?'premium_h':t)}" alt=""><b>${lbl(t)}</b></div>
  <ul class="bk-vl">${B.map(b=>`<li><i>${sv('check')}</i><span>${esc(tx('b_'+b.id))}</span></li>`).join('')}</ul>
  <div class="bk-h"><b>${esc(tx('dur'))}</b></div>
  <div class="sb-durs">${P.map(p=>{const o=off(p);return `<button class="sb-du ${p.months===sel?'on':''}" data-x="d" data-i="${p.months}"><span>${esc(tx('m1',{n:p.months}))}</span><b>${esc(price(p))}</b>${p.regular&&p.regular!==p.eur?`<s style="font-size:11.5px;color:var(--wk-text2)">€${esc(p.regular)}</s>`:''}${p.months===sel?`<span class="tk">${sv('check')}</span>`:o?`<span class="of">-${o}%</span>`:''}</button>`}).join('')}</div>
  <button class="bk-go" data-x="go" style="margin-top:22px!important">${sv('up')}<span>${esc(tx('cont'))}</span></button>`)};
 el.__acts={d(b){sel=+b.dataset.i;draw()},go:()=>pay(t,sel)};draw()})}
/* 5. payment — only methods the server really has */
function pay(t,months,renewing){let m=null;wrap(tx('s_pay'),'',tx('s_pay_s'),el=>{
 const p=plans(t).find(x=>x.months===months);const M=S.methods||{};const isA=/iPhone|iPad|Macintosh/.test(navigator.userAgent);
 if(!m)m=M.store?'store':'coins';
 const draw=()=>set(el,`<button class="sb-pm ${m==='store'?'on':''} ${M.store?'':'off'}" data-x="m" data-i="store"><span class="lg">${isA?sv('apple'):`<b style="font-size:15px">G</b>`}</span><span class="tt"><b>${esc(isA?tx('p_store_a'):tx('p_store_g'))}</b>${M.store?'':`<small>${esc(tx('p_store_d'))}</small>`}</span><span class="rd">${m==='store'?sv('check'):''}</span></button>
  <button class="sb-pm ${m==='coins'?'on':''}" data-x="m" data-i="coins"><span class="lg">${COIN.replace('class="bk-c"','style="width:26px;height:26px"')}</span><span class="tt"><b>${esc(tx('p_coins'))}</b><small>${esc(tx('p_coins_d',{n:num(p&&p.coins),b:num(S.balance)}))}</small></span><span class="rd">${m==='coins'?sv('check'):''}</span></button>
  <div class="sb-sum"><div><b><bdi>${esc(lbl(t))}</bdi>&nbsp;<bdi>(${esc(tx('m1',{n:months}))})</bdi></b><span>${esc(tx('plan_l'))}</span></div><div><b>${m==='coins'?`${num(p&&p.coins)} ${COIN}`:esc(price(p))}</b><span>${esc(tx('amount_l'))}</span></div></div>
  <button class="bk-go" data-x="go">${sv('shieldc')}<span>${esc(tx('pay_go'))}</span></button>`);
 el.__acts={m(b){m=b.dataset.i;draw()},async go(b){if(m==='store'&&!M.store){say2(tx('use_store'));return}
  b.disabled=true;try{const r=await withPin('/api/app/sub/buy',{tier:t,months,method:m,client_key:ck()});
   if(r&&r.ok){S=null;try{WKT.sync();ME3.reload()}catch(e){}success(r.receipt)}else say2(errMsg(r&&r.err))}catch(e){say2(tx('err'))}b.disabled=false}};draw()})}
const say2=m=>{try{toast(m)}catch(e){}};
/* 6. my subscription */
function mine(){wrap(tx('s_mine_t'),sv('person'),tx('s_mine_s'),el=>{const t=S.tier||{},now=Date.now()/1000,act=t.tier&&t.tier!=='free';const last=act?t.tier:(t.last||null);
 const left=act&&t.until?Math.max(0,Math.ceil((t.until-now)/86400)):0;const up=ORDER.find(x=>RANK[x]>RANK[t.tier||'free']&&x!=='vip')||null;
 set(el,last?`<div class="sb-mine"><img src="${ART(last==='premium'?'premium_h':last)}" alt=""><div class="nm" style="color:${last==='royal'?'#F5C451':'inherit'}">${lbl(last)}</div>
   <span class="sb-st ${act?'':'off'}">${esc(tx(act?'active':'expired'))}</span><div class="sub">${esc(tx('sub_of',{t:lbl(last)}))}</div>
   ${t.via==='creator'?`<div class="bk-note">${esc(tx('creator'))}</div>`:`<div class="sb-kv"><div>${sv('calS')}<span>${esc(tx('start'))}</span><b>${t.start?esc(ymd(t.start).split(' - ')[0]):'—'}</b></div><div>${sv('gift')}<span>${esc(tx('end'))}</span><b>${t.until?esc(ymd(t.until).split(' - ')[0]):'—'}</b></div><div>${sv('clock')}<span>${esc(tx('left'))}</span><b class="g">${esc(tx('days',{n:left}))}</b></div>${t.store?`<div>${sv('refresh')}<span>${esc(tx('auto'))}</span><b class="g">${esc(tx('auto_on'))}</b></div>`:''}</div>`}</div>
   ${t.via==='creator'?'':`<button class="bk-go" data-x="rn">${sv('refresh')}<span>${esc(tx('renew'))}</span></button>`}
   ${up&&t.via!=='creator'?`<button class="sb-gold" data-x="up">${sv('crownl')}<span>${esc(tx('up_to',{t:lbl(up)}))}</span></button>`:''}
   ${t.store?R2('man','gear',tx('manage'),''):''}${R2('hist','hist',tx('s_hist'),'')}`
  :`<div class="bk-empty">${esc(tx('no_sub'))}</div><button class="bk-go" data-x="buy">${sv('cart')}<span>${esc(tx('s_buy'))}</span></button>${R2('hist','hist',tx('s_hist'),'')}`);
 el.__acts={rn:()=>renew(),up:()=>details(up),buy:()=>pick(),hist:()=>history(),man(){const isA=/iPhone|iPad|Macintosh/.test(navigator.userAgent);const u=isA?'https://apps.apple.com/account/subscriptions':'https://play.google.com/store/account/subscriptions';try{SET3.openUrl?window.open(u,'_blank'):0}catch(e){}window.open(u,'_blank')}}})}
