function success(r){r=r||{};const el=page(tx('s_ok'),`<span class="bk-tok">${sv('check')}</span>`,'',`<div class="sb-okc bk-pop">${sv('check')}</div><div class="sb-ok">${esc(tx('s_ok_t'))}</div>
 <div class="sb-sum"><div><b>${esc(lbl(r.tier))}</b><span>${esc(tx('plan_l'))}</span></div><div><b>${esc(tx('m1',{n:r.months}))}</b><span>${esc(tx('dur_l'))}</span></div>
 <div><b>${r.coins?`${num(r.coins)} ${COIN}`:esc(r.price||'')}</b><span>${esc(tx('amount_l'))}</span></div><div><b>${r.ts?esc(ymd(r.ts).split(' - ')[0]):''}</b><span>${esc(tx('act_l'))}</span></div><div><b>${esc(r.code||'')}</b><span>${esc(tx('tid_l'))}</span></div></div>
