  ${S.tier&&S.tier.until?`<div class="bk-note" style="margin:-4px 0 12px">${esc(tx('rn_end',{d:ymd(S.tier.until).split(' - ')[0]}))}</div>`:''}
  ${plans(t).map(p=>`<button class="sb-rn ${p.months===sel?'on':''}" data-x="d" data-i="${p.months}"><span class="rd">${p.months===sel?sv('check'):''}</span><b>${esc(price(p))}</b><span>${esc(tx('rn_for',{n:p.months}))}</span></button>`).join('')}
  <button class="bk-go" data-x="go">${sv('refresh')}<span>${esc(tx('rn_go'))}</span></button>`);
 el.__acts={d(b){sel=+b.dataset.i;draw()},go:()=>pay(t,sel,true)};draw()})}
