 const draw=()=>set(el,(items.map(h=>`<div class="sb-hi"><span class="pr">${h.coins?`${num(h.coins)} ${COIN}`:esc(h.price||'')}</span><span class="tt"><b><bdi>${esc(lbl(h.tier))}</bdi> - <bdi>${esc(tx('m1',{n:h.months}))}</bdi></b><small>${esc(ymd(h.ts).split(' - ')[0])} - ${h.active?`<em>${esc(tx('h_active'))}</em><i class="on"></i>`:`${esc(tx('h_done'))}<i></i>`}</small></span><img src="${ART(h.tier)}" alt="" loading="lazy"></div>`).join('')||`<div class="bk-empty">${esc(tx('h_none'))}</div>`)
  +(next?`<button class="bk-go" style="height:44px;font-size:14px!important" data-x="more">${esc(tx('more2'))}</button>`:''));
 const get=async more=>{try{const r=await api('/api/app/sub/history'+(more&&next?'?before='+next:''));if(!r||!r.ok)throw 0;items=more?items.concat(r.items):r.items;next=r.next||null;draw()}catch(e){fail(el)}};
 el.__acts={more:()=>get(true)};get()}
