const PAL={gold:['#FFE38A','#E0A21F','#8A5A0B'],violet:['#E9D5FF','#A855F7','#5B21B6'],ice:['#DBF4FF','#38BDF8','#1E3A8A'],fire:['#FFE0B2','#F97316','#991B1B'],rose:['#FFE4E6','#F43F5E','#881337'],green:['#DCFCE7','#22C55E','#14532D'],night:['#C7D2FE','#6366F1','#1E1B4B']};
const col=it=>PAL[it.color]||PAL[{vip:'violet',premium:'violet',royal:'gold',legend:'fire',epic:'violet',rare:'ice',event:'rose'}[it.rarity]]||PAL.violet;
let uidN=0;
function frameSVG(it,photo){const [a,b,c]=col(it),id='f'+(++uidN),n=12;let dots='';for(let i=0;i<n;i++){const r=Math.PI*2*i/n,x=50+44*Math.cos(r),y=50+44*Math.sin(r);dots+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${i%3?1.6:2.6}" fill="${a}"/>`}
 return `<svg viewBox="0 0 100 100" class="st-fr" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${a}"/><stop offset=".5" stop-color="${b}"/><stop offset="1" stop-color="${c}"/></linearGradient><clipPath id="${id}c"><circle cx="50" cy="50" r="34"/></clipPath></defs>
  ${photo?`<image href="${esc(photo)}" x="16" y="16" width="68" height="68" clip-path="url(#${id}c)" preserveAspectRatio="xMidYMid slice"/>`:''}
  <circle cx="50" cy="50" r="40" fill="none" stroke="url(#${id})" stroke-width="7"/><circle cx="50" cy="50" r="35.5" fill="none" stroke="${c}" stroke-width="1"/>${dots}${it.rarity==='royal'||it.color==='gold'?`<path d="M40 12 44 4l6 6 6-6 4 8Z" fill="url(#${id})"/>`:''}</svg>`}
function badgeSVG(it){const [a,b,c]=col(it),id='b'+(++uidN);const icon={vip:'<text x="50" y="58" font-size="20" font-weight="900" text-anchor="middle" fill="#fff" font-family="Georgia,serif">VIP</text>',gem:'<path d="M38 42h24l6 8-18 20-18-20Z" fill="#fff" opacity=".9"/>',star:'<path d="m50 32 5.5 11.5 12.5 1.5-9 8.5 2.5 12.5L50 60l-11.5 6 2.5-12.5-9-8.5 12.5-1.5Z" fill="#fff"/>',wing:'<path d="M50 62C40 52 30 50 26 40c10 2 18 6 24 14 6-8 14-12 24-14-4 10-14 12-24 22Z" fill="#fff"/>'}[it.icon]||'<path d="m50 34 14 8v14L50 66 36 56V42Z" fill="#fff" opacity=".9"/>';
 return `<svg viewBox="0 0 100 100" class="st-bd" aria-hidden="true"><defs><radialGradient id="${id}" cx=".4" cy=".35"><stop offset="0" stop-color="${a}"/><stop offset=".6" stop-color="${b}"/><stop offset="1" stop-color="${c}"/></radialGradient></defs><circle cx="50" cy="50" r="40" fill="url(#${id})"/><circle cx="50" cy="50" r="40" fill="none" stroke="${a}" stroke-width="3"/><circle cx="50" cy="50" r="32" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="1.5"/>${icon}</svg>`}
function fxSVG(it){const [a,b]=col(it),id='e'+(++uidN);let p='';for(let i=0;i<18;i++){const r=Math.PI*2*i/18,R=40+(i%2?4:-2),x=50+R*Math.cos(r),y=50+R*Math.sin(r);p+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${i%3?1.4:2.4}" fill="${a}"/>`}
 return `<svg viewBox="0 0 100 100" class="st-fx" aria-hidden="true"><defs><radialGradient id="${id}"><stop offset=".72" stop-color="${b}" stop-opacity="0"/><stop offset=".86" stop-color="${b}" stop-opacity=".9"/><stop offset="1" stop-color="${b}" stop-opacity="0"/></radialGradient></defs><circle cx="50" cy="50" r="46" fill="url(#${id})"/><circle cx="50" cy="50" r="38" fill="none" stroke="${a}" stroke-width="2"/>${p}</svg>`}
const giftArt=code=>{try{const w=window.WM70;if(typeof wm70GiftArt==='function'&&w&&w.gifts&&w.gifts.some(v=>v.code===code)){const a=wm70GiftArt(code);if(a)return a}}catch(e){}return `<span class="st-ph">${sv('gift')}</span>`};
/* the gift pictures come from the app's own gift list (loaded once) */
let GL=null;const gifts0=()=>GL||(GL=(async()=>{try{const w=window.WM70=window.WM70||{};if(!(w.gifts&&w.gifts.length)){const r=await api('/api/app/gifts');if(r&&r.ok&&r.gifts)w.gifts=r.gifts}}catch(e){}})());
function art(it,photo){if(it.art)return `<img src="${esc(it.art)}" alt="" loading="lazy" decoding="async">`;
 if(it.cat==='gifts')return giftArt(it.code||it.id);if(it.cat==='frames')return frameSVG(it,photo);if(it.cat==='effects')return fxSVG(it);if(it.cat==='badges'||it.cat==='vip')return badgeSVG(it);
 if(it.cat==='avatars')return `<span class="st-ph">${sv('hood')}</span>`;if(it.cat==='bgs')return `<span class="st-ph st-bgph" style="--a:${col(it)[1]}"></span>`;return `<span class="st-ph">${sv('spark')}</span>`}
