/* ---------- cart (ids + qty on this phone; prices always re-checked by the server) */
const CK='st3_cart';
const cartGet=()=>{try{return JSON.parse(localStorage.getItem(CK)||'[]').filter(x=>x&&x.id)}catch(e){return []}};
const cartPut=c=>{try{localStorage.setItem(CK,JSON.stringify(c.slice(0,30)))}catch(e){}};
function cartAdd(it){const c=cartGet();const x=c.find(y=>y.id===it.id);if(x){if(it.repeatable)x.qty=Math.min(99,(x.qty||1)+1)}else c.push({id:it.id,qty:1});cartPut(c);U.tx&&toast2(tx('added'))}
const toast2=m=>{try{toast(m)}catch(e){}};
const cartBtn=()=>{const n=cartGet().reduce((a,b)=>a+(b.qty||1),0);return `<button class="bk-hx st-cartb" data-x="cart" aria-label="cart">${sv('cart')}${n?`<i>${n}</i>`:''}</button>`};
const CAT_PAGE={gifts:['c_gifts','g_s2','gift',['all','new','special','vip']],frames:['c_frames','f_s','ring',['all','new','pop','vip']],badges:['b_t','b_s','shieldw',['all','special','event','rare']],
 effects:['e_t','e_s','spark',null],bgs:['c_bgs','bg_s','image',['all','new','pop','vip']],avatars:['c_avatars','av_s','hood',['all','new','pop','vip']],vip:['c_vip','vip_s','crownl',['all','new','pop','vip']],all:['c_all','all_s','grid4',['all','new','pop','vip']]};

/* 1. store home */
async function home(){
 const el=page(tx('st'),sv('bag2').replace('<svg','<svg style="color:#F5C451"'),tx('st_s'),'',cartBtn());
 const cats1=[['badges','shieldw'],['effects','spark'],['bgs','image']],cats2=[['gifts','gift'],['avatars','hood'],['vip','crownl'],['all','grid4']];
 set(el,`<div class="st-q">${sv('search')}<input id="stq" placeholder="${esc(tx('st_q'))}" enterkeyhint="search"></div>
  <button class="st-ban" data-x="new"><span class="tt"><b>${esc(tx('st_new'))}</b><small>${esc(tx('st_new_s'))}</small></span>${U.live?U.live('promo','left:0',360/231):''}</button>
  <div class="st-cats">${cats1.map(([k,ic])=>`<button class="st-cat" data-x="cat" data-i="${k}">${sv(ic)}<span>${esc(tx(k==='badges'?'c_badges':'c_'+k))}</span></button>`).join('')}</div>
  <div class="st-cats r2">${cats2.map(([k,ic])=>`<button class="st-cat" data-x="cat" data-i="${k}">${sv(ic,k==='vip'?'g':'')}<span>${esc(tx('c_'+k))}</span></button>`).join('')}</div>
  <button class="st-pack" data-x="pack"><img src="${SUBART('royal')}" alt=""><span class="tt"><b>${esc(tx('st_pack'))}</b><small>${esc(tx('st_pack_s',{n:50}))}</small></span><span class="ch">${sv('back')}</span></button>
  <button class="bk-go" data-x="all2">${esc(tx('st_all'))}</button>`);
 const q=el.querySelector('#stq');q.onkeydown=e=>{if(e.key==='Enter'&&q.value.trim())grid('all',q.value.trim())};
 el.__acts={cat:b=>b.dataset.i==='effects'?effects():grid(b.dataset.i),new:()=>grid('all',null,'new'),pack:()=>{try{BK3.buy()}catch(e){}},all2:()=>grid('all'),cart:()=>cart()}}
/* 2–4 + backgrounds/avatars/VIP/all: one grid page per category (paged) */
async function grid(cat,q,tab0){if(cat==='gifts'||cat==='all')await gifts0();
 const P=CAT_PAGE[cat]||CAT_PAGE.all;let tab=tab0||'all',pg=0,d=null;
 const el=page(q?`«${q}»`:tx(P[0]),sv(P[2]),tx(P[1]),`<div class="bk-empty">${esc(tx('loading'))}</div>`,cartBtn());
 const photo=myPhoto();
 const draw=()=>{const items=d.items||[];set(el,`${P[3]&&!q?`<div class="st-tabs">${P[3].map(t=>`<button class="${t===tab?'on':''}" data-x="t" data-i="${t}">${esc(tx('t_'+t))}</button>`).join('')}</div>`:''}
  <div class="st-grid">${items.map(it=>`<button class="st-it ${esc(it.cat)}" data-x="it" data-i="${esc(it.id)}">${it.owned?`<span class="tg">${esc(tx('on_l')==='فعال'?'✓':'✓')}</span>`:it.locked?`<span class="tg lk">${sv('lockS')}</span>`:''}<span class="ar">${art(it,it.cat==='frames'?'':'')}</span><span class="pr">${num(it.price)} ${COIN}</span></button>`).join('')||`<div class="bk-empty" style="grid-column:1/-1">${esc(tx('empty'))}</div>`}</div>
  ${d.pages>1?`<div class="st-pg"><button data-x="pv" ${pg<=0?'disabled':''}>${sv('back')}</button><span class="st-dots">${Array.from({length:Math.min(d.pages,6)},(_,i)=>`<i class="${i===pg?'on':''}"></i>`).join('')}</span><button data-x="nx" ${pg>=d.pages-1?'disabled':''}>${sv('fwd')}</button></div>`:''}`)};
 const get=async()=>{try{const r=await api('/api/app/store?cat='+cat+'&tab='+tab+'&page='+pg+(q?'&q='+encodeURIComponent(q):''));if(!r||!r.ok)throw 0;d=r;draw()}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}};
 el.__acts={t(b){tab=b.dataset.i;pg=0;get()},pv(){pg=Math.max(0,pg-1);get()},nx(){pg++;get()},it:b=>item(b.dataset.i),cart:()=>cart()};get()}
/* 5. effects (rows with preview) */
async function effects(){
 const el=page(tx('e_t'),sv('spark'),tx('e_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`,cartBtn());
 try{const r=await api('/api/app/store?cat=effects');if(!r||!r.ok)throw 0;
  set(el,(r.items||[]).map(it=>`<button class="st-fxr" data-x="it" data-i="${esc(it.id)}"><span class="ar">${art(it)}</span><span class="tt"><b>${esc(it.name)}</b><small>${esc(it.desc||'')}</small><span class="pp">${num(it.price)} ${COIN}</span></span><span class="pv">${sv('playc')}</span></button>`).join('')||`<div class="bk-empty">${esc(tx('empty'))}</div>`);
  el.__acts={it:b=>item(b.dataset.i),cart:()=>cart()}}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}}
/* 6. item details — frames preview on your round photo */
async function item(id){
 const el=page(tx('det2'),sv('info2'),tx('det2_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`,cartBtn());let it;
 const draw=()=>{const photo=myPhoto();const fx=it.cat==='effects';
  const big=it.cat==='frames'||fx?`<div class="st-big ${fx?'fxon':''}"><span class="ph">${photo?`<img src="${esc(photo)}" alt="">`:sv('person')}</span>${art(it)}</div>`:`<div class="st-big">${art(it)}</div>`;
  const feats=(it.features&&it.features.length?it.features:(it.cat==='frames'?['f1','f2','f3','f4']:it.cat==='gifts'?['f5','f3']:fx?['f2','f6','f4']:['f2','f3','f4']));
  set(el,`${big}${fx&&document.documentElement.classList.contains('wk-rm')?`<div class="bk-note">${esc(tx('fx_off'))}</div>`:''}<div class="st-nm">${esc(it.name)}</div>
   <div class="st-chips"><span class="a">${esc(tx(CAT_PAGE[it.cat]?CAT_PAGE[it.cat][0]:'c_all'))}</span><span>${esc(tx('r_'+(it.rarity||'common')))}</span>${it.popular?`<span>${esc(tx('t_pop'))}</span>`:''}</div>
   ${it.desc?`<div class="bk-note" style="margin:-4px 0 10px">${esc(it.desc)}</div>`:''}
   <ul class="st-feat">${feats.map(f=>`<li>${sv('check')}<span>${esc(tx(f))}</span></li>`).join('')}${it.how?`<li>${sv('info2')}<span>${esc(tx('how_get',{x:it.how}))}</span></li>`:''}</ul>
   ${it.art?'':`<div class="bk-note" style="margin:-4px 0 10px">${esc(tx('art_soon'))}</div>`}
   <div class="st-pb"><button class="${it.fav?'on':''}" data-x="fav" aria-label="fav">${sv('heart')}</button><span class="pr">${COIN} ${num(it.price)}</span></div>
   ${it.owned&&!it.repeatable?`<div class="st-own">${esc(tx('owned2'))}</div><button class="bk-go" data-x="mine">${sv('layers')}<span>${esc(tx('see_items'))}</span></button>`
    :it.locked?`<button class="bk-go" disabled>${sv('lockS')}<span>${esc(it.need?tx('need_t',{t:it.need}):tx('not_sale'))}</span></button>`
    :`<button class="bk-go" data-x="buy">${esc(tx('buy_it'))}</button><button class="bk-row" data-x="add" style="margin-top:10px!important"><span class="ic">${sv('cart')}</span><span class="tt"><b>${esc(tx('add_cart'))}</b></span><span class="ch">${sv('back')}</span></button>`}`)};
 el.__acts={async fav(){it.fav=!it.fav;draw();try{const r=await api('/api/app/store/fav',{id:it.id,on:it.fav});if(!r||!r.ok)throw 0;toast2(tx(it.fav?'fav_on':'fav_off'))}catch(e){it.fav=!it.fav;draw()}},
  buy(){pay([{id:it.id,qty:1}])},add(){cartAdd(it);item(it.id);SET3.drop()},mine:()=>mine(),cart:()=>cart()};
 try{const r=await api('/api/app/store/item?id='+encodeURIComponent(id));if(!r||!r.ok)throw 0;it=r.item;draw()}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}}
/* 7. cart */
async function cart(){
 const el=page(tx('cart'),sv('cart'),tx('cart_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`);let q;
 const quote=async()=>{const c=cartGet();if(!c.length){set(el,`<div class="bk-empty">${esc(tx('cart_empty'))}</div>`);return}
  try{q=await api('/api/app/store/quote',{items:c});if(!q||!q.ok)throw 0;draw()}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`)}};
 const draw=()=>set(el,(q.items||[]).map(it=>`<div class="st-cr"><button class="x" data-x="rm" data-i="${esc(it.id)}" aria-label="remove">${sv('x')}</button><span class="tt"><b>${esc(it.name)}</b><span class="pr">${num(it.price)} ${COIN}</span></span>
   ${it.repeatable?`<span class="st-q2"><button data-x="dn" data-i="${esc(it.id)}">${sv('minus')}</button><span>${it.qty}</span><button data-x="up" data-i="${esc(it.id)}">${sv('plus')}</button></span>`:''}<span class="ar">${art(it)}</span></div>`).join('')
  +`<div class="st-sum"><span>${esc(tx('total'))}</span><b>${num(q.total)} ${COIN}</b></div><button class="bk-go" data-x="go">${sv('cart')}<span>${esc(tx('to_pay'))}</span></button>`);
 const ch=(id,f)=>{const c=cartGet();const x=c.find(y=>y.id===id);if(x)f(c,x);cartPut(c.filter(y=>(y.qty||1)>0));quote()};
 el.__acts={rm:b=>ch(b.dataset.i,(c,x)=>{x.qty=0}),up:b=>ch(b.dataset.i,(c,x)=>{x.qty=Math.min(99,(x.qty||1)+1)}),dn:b=>ch(b.dataset.i,(c,x)=>{x.qty=(x.qty||1)-1}),go:()=>pay(cartGet(),true)};
 quote()}
/* 8. payment — store items are bought with coins (atomic on the server) */
async function pay(items,fromCart){
 const el=page(tx('pay2'),sv('card'),tx('pay2_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`);let q;
 try{q=await api('/api/app/store/quote',{items});if(!q||!q.ok)throw 0}catch(e){set(el,`<div class="bk-empty">${esc(tx('offline'))}</div>`);return}
 const n=(q.items||[]).reduce((a,b)=>a+(b.qty||1),0);
 set(el,`<div class="st-ord">${sv('cart')}<span class="tt"><span>${esc(tx('items_n',{n}))}</span><b>${esc(tx('payable'))}<em>${num(q.total)} ${COIN}</em></b></span></div>
  <div class="bk-h"><b>${esc(tx('pay_m'))}</b></div>
  <button class="st-coin" data-x="noop"><span>${COIN} ${esc(tx('pay_coin'))} · ${num(q.balance)}</span><span class="rd">${sv('check')}</span></button>
  <div class="st-mx"><div>${esc(tx('m_apple'))}</div><div>${esc(tx('m_card'))}</div><div>${esc(tx('m_paypal'))}</div><div>${esc(tx('m_crypto'))}</div></div>
  <div class="bk-note">${esc(tx('ext_off'))}</div>
  <button class="bk-go" data-x="go">${sv('shieldw')}<span>${esc(tx('pay_final'))}</span></button>`);
 el.__acts={noop(){},async go(b){if(+q.balance<+q.total){toast2(tx('low'));try{BK3.buy()}catch(e){}return}b.disabled=true;
  try{const r=await withPin('/api/app/store/buy',{items,total:q.total,client_key:ck()});if(r&&r.ok){if(fromCart)cartPut([]);try{ME3.reload()}catch(e){}success(r.receipt)}else toast2(errMsg(r&&r.err))}catch(e){toast2(tx('err'))}b.disabled=false}}}
/* 9. success */
function success(r){r=r||{};const n=(r.items||[]).reduce((a,b)=>a+(b.qty||1),0);
 const el=page(tx('ok2t'),`<span class="bk-tok">${sv('check')}</span>`,'',`<div class="st-win"><div class="st-burst"><i style="--x:-120px;--y:-70px;--r:200deg;--c:#FACC15;--d:0.0s"></i><i style="--x:110px;--y:-80px;--r:-160deg;--c:#F472B6;--d:0.05s"></i><i style="--x:-90px;--y:-120px;--r:120deg;--c:#A78BFA;--d:0.1s"></i><i style="--x:130px;--y:-30px;--r:240deg;--c:#FDE047;--d:0.08s"></i><i style="--x:-140px;--y:10px;--r:-200deg;--c:#C084FC;--d:0.12s"></i><i style="--x:80px;--y:-130px;--r:180deg;--c:#FB923C;--d:0.03s"></i><i style="--x:20px;--y:-150px;--r:-120deg;--c:#FACC15;--d:0.15s"></i><i style="--x:-40px;--y:-140px;--r:90deg;--c:#F472B6;--d:0.07s"></i><i style="--x:150px;--y:-110px;--r:140deg;--c:#A78BFA;--d:0.11s"></i><i style="--x:-150px;--y:-40px;--r:-90deg;--c:#FDE047;--d:0.02s"></i></div><img class="st-rise" src="${LA('/s/wk2/st/success.webp?v=106')}" alt=""></div><div class="sb-ok" style="text-align:center;font-size:18px;font-weight:800;margin:0 0 14px">${esc(tx('ok2'))}</div>
  <div class="bk-kv2"><div><span>${esc(tx('l_items'))}</span><b>${esc(tx('items_n',{n}).split(':').pop())}</b></div><div><span>${esc(tx('l_amt'))}</span><b>${num(r.total)} ${COIN}</b></div><div><span>${esc(tx('l_meth'))}</span><b>${esc(tx('pay_coin'))}</b></div>
  <div><span>${esc(tx('l_id'))}</span><b>${esc(r.code||'')}</b></div><div><span>${esc(tx('l_date'))}</span><b>${esc(r.ts?ymd(r.ts):'')}</b></div></div>
  <button class="bk-go" data-x="mine">${sv('layers')}<span>${esc(tx('see_items'))}</span></button>`);el.__acts={mine:()=>mine()}}
/* 10. my items (Me → wardrobe) */
async function mine(tab0){await gifts0();
 let tab=tab0||'all',d;const el=page(tx('my'),sv('layers'),tx('my_s'),`<div class="bk-empty">${esc(tx('loading'))}</div>`);
 const TABS=['all','badges','effects','gifts'];
 const draw=()=>{const it=(d.items||[]).filter(i=>tab==='all'||i.cat===tab);
  set(el,`<div class="st-mt">${TABS.map(t=>`<button class="${t===tab?'on':''}" data-x="t" data-i="${t}">${esc(tx('m_'+t))}</button>`).join('')}</div>
  ${it.map(i=>`<div class="st-mi"><span class="ar">${art(i,i.cat==='frames'?myPhoto():'')}</span><span class="tt"><b>${esc(i.name)}${i.qty>1?` <small style="color:var(--wk-text2)">${esc(tx('x_n',{n:i.qty}))}</small>`:''}</b>${i.cat==='gifts'?`<span class="st snd">${esc(tx('sendable'))}</span>`:`<span class="st ${i.active?'':'off'}">${esc(tx(i.active?'on_l':'off_l'))}</span>`}</span><button class="mn" data-x="mn" data-i="${esc(i.id)}" aria-label="manage">${sv('more')}</button></div>`).join('')||`<div class="bk-empty">${esc(tx('my_empty'))}</div>`}`)};
 const use=async(i,on)=>{try{const r=await api('/api/app/store/use',{id:i.id,on});if(r&&r.ok){d=r;draw();try{ME3.reload()}catch(e){}}else toast2(errMsg(r&&r.err))}catch(e){toast2(tx('err'))}};
