 try{const d=await api('/api/app/level');if(!d||!d.ok)throw 0;const l=d.level,r=d.rank;const span=Math.max(1,l.to-l.from),cur=l.xp-l.from,pct=l.max&&l.level>=l.max?100:Math.round(cur/span*1000)/10;
  set(el,`<div class="lv-card"><div class="lv-top"><span class="lv-ring">${l.level}</span><span class="tt"><b>${esc(tx('lv',{n:l.level}))}</b><small>${esc(tx('rank_of',{r:rk(r.key)}))}</small></span><span class="md">${sv('medal')}</span></div>
