   <div class="lv-left">${l.level>=l.max?esc(tx('max')):esc(tx('to_next',{n:num(l.to-l.xp)}))}</div></div>
   <div class="lv-g"><button data-x="ranks">${sv('layers')}<b>${esc(tx('ranks'))}</b></button><button data-x="hist">${sv('hist')}<b>${esc(tx('xph'))}</b></button><button data-x="mine">${sv('trophy')}<b>${esc(tx('mine'))}</b></button><button data-x="rw">${sv('gift')}<b>${esc(tx('rewards'))}</b></button></div>
   <div class="lv-h"><b>${esc(tx('recent'))}</b><button data-x="mine">${esc(tx('all'))}</button></div>
