  el.__acts={ranks:()=>ranks(),hist:()=>history(),mine:()=>achievements(),rw:()=>rewards(),ways:()=>ways(),ach:b=>achievement(b.dataset.i)}}catch(e){fail(el)}}
/* ranks */
async function ranks(){const el=page(tx('ranks'),`<div class="lv-empty">${esc(tx('loading'))}</div>`);
 try{const d=await api('/api/app/level/ranks');if(!d||!d.ok)throw 0;
  set(el,`<div class="lv-list">${d.ranks.slice().reverse().map(r=>`<button class="lv-r ${r.open?'':'dim'}" data-x="rk" data-i="${esc(r.key)}">${rBadge(r)}<span class="tt"><b>${esc(rk(r.key))}</b><small>${esc(tx('range',{a:r.from,b:r.to}))}</small></span>${r.current?`<span class="tag">${esc(tx('current'))}</span>`:r.open?`<span class="tag ok">${esc(tx('opened'))}</span>`:`<span class="tag lk">${esc(tx('locked'))}</span>`}<span class="ch">${sv('chevl')}</span></button>`).join('')}</div>`);
  el.__acts={rk(b){const r=d.ranks.find(x=>x.key===b.dataset.i);if(!r)return;
   page(rk(r.key),`<div class="lv-big ${r.open?'':'lk'}" style="border-color:${esc(r.color)};color:${esc(r.color)}">${r.index>=7?sv('crown'):`<b style="font-size:28px">${r.from}</b>`}</div><div class="lv-nm">${esc(rk(r.key))}</div><div class="lv-ds">${esc(tx('range',{a:r.from,b:r.to}))}</div>
