/* XP history (paged, filters) */
async function history(){const el=page(tx('xph'),'');let f='all',items=[],next=null;
 const draw=()=>set(el,`<div class="lv-tabs">${['all','in','fix'].map(k=>`<button class="${k===f?'on':''}" data-x="f" data-i="${k}">${esc(tx('f_'+k))}</button>`).join('')}</div>
  ${items.length?`<div class="lv-list">${items.map(x=>`<div class="lv-r"><span class="ic">${sv(SRC_IC[x.src]||'bolt')}</span><span class="tt"><b>${esc(tx('s_'+x.src))}</b><small>${esc(ymd(x.ts))} · ${esc(tx('ev',{id:x.id}))}</small></span><span class="v ${x.xp>=0?'p':'m'}">${x.xp>=0?'+':''}${num(x.xp)} XP</span></div>`).join('')}</div>`:`<div class="lv-list"><div class="lv-empty">${esc(tx('empty'))}</div></div>`}
  ${next?`<button class="s3-btn soft" style="margin-top:12px;color:var(--wk-text)!important" data-x="more">${esc(tx('more'))}</button>`:''}`);
 const get=async more=>{try{const r=await api('/api/app/me/xp?f='+f+(more&&next?'&before='+next:''));if(!r||!r.ok)throw 0;items=more?items.concat(r.items):r.items;next=r.next||null;draw()}catch(e){fail(el)}};
 el.__acts={f(b){f=b.dataset.i;items=[];get()},more:()=>get(true)};draw();get()}
/* my achievements */
let ACH=null;
async function achievements(){const el=page(tx('mine'),`<div class="lv-empty">${esc(tx('loading'))}</div>`);let f='all';
 const draw=()=>{const it=(ACH||[]).filter(a=>f==='all'||(f==='earned'?a.earned:!a.earned));set(el,`<div class="lv-tabs">${['all','earned','locked'].map(k=>`<button class="${k===f?'on':''}" data-x="f" data-i="${k}">${esc(tx('a_'+k))}</button>`).join('')}</div>
  ${it.length?`<div class="lv-list">${it.map(achRow).join('')}</div>`:`<div class="lv-list"><div class="lv-empty">${esc(tx(f==='earned'?'no_ach':'empty'))}</div></div>`}`)};
 el.__acts={f(b){f=b.dataset.i;draw()},ach:b=>achievement(b.dataset.i)};
 try{const r=await api('/api/app/me/achievements');if(!r||!r.ok)throw 0;ACH=r.items;draw()}catch(e){fail(el)}}
/* achievement details */
async function achievement(id){if(!ACH){try{const r=await api('/api/app/me/achievements');ACH=r.items}catch(e){}}const a=(ACH||[]).find(x=>x.id===id);if(!a)return;
 page(tx('ach_'+a.id),`<div class="lv-big ${a.earned?'':'lk'}">${sv(a.earned?(ACH_IC[a.icon]||'trophy'):'lock')}</div><div class="lv-nm">${esc(tx('ach_'+a.id))}</div><div class="lv-ds">${esc(tx('k_'+a.kind,{n:num(a.goal)}))}</div>
