  <div><span>${esc(tx('progress',{a:'',b:''}).split(':')[0])}</span><b>${num(Math.min(a.progress,a.goal))} / ${num(a.goal)}</b></div>
  ${a.xp?`<div><span>${esc(tx('reward_xp',{n:''}).split(':')[0])}</span><b>+${num(a.xp)} XP</b></div>`:''}
  <div><span>${esc(tx('a_all')==='همه'?'وضعیت':'Status')}</span><b class="${a.earned?'ok':''}">${esc(tx(a.earned?'st_earned':'st_locked'))}${a.earned&&a.ts?' · '+esc(ymd(a.ts).split(' - ')[0]):''}</b></div></div>`)}
