 const draw=()=>set(el,d.items.length?`<div class="lv-list">${d.items.map(r=>`<div class="lv-r ${r.state==='locked'?'dim':''}"><span class="lv-rb" style="--rc:var(--s3-hd)">${r.level}</span><span class="tt"><b>${esc(r.kind==='coins'?tx('rw_coins',{n:num(r.coins)}):r.name||r.item)}</b><small>${esc(tx('lv',{n:r.level}))}</small></span>
