 el.__acts={async cl(b){b.disabled=true;try{const r=await api('/api/app/level/rewards',{level:+b.dataset.i});if(r&&r.ok){d=r;draw();say(tx('rw_ok'))}else{say(tx(r&&r.err)||tx('err'));b.disabled=false}}catch(e){say(tx('err'));b.disabled=false}}};
