const ring=p=>{const r=28,c=2*Math.PI*r;return `<span class="mn-ring"><svg viewBox="0 0 64 64"><circle cx="32" cy="32" r="${r}" fill="none" stroke="var(--wk-border)" stroke-width="4"/><circle cx="32" cy="32" r="${r}" fill="none" stroke="var(--s3-hd)" stroke-width="4" stroke-linecap="round" stroke-dasharray="${(c*p/100).toFixed(1)} ${c.toFixed(1)}"/></svg>${p}%</span>`};
