 const right=m.state==='ready'?`<button class="cb" data-x="claim" data-i="${esc(m.id)}">${esc(tx('claim'))}</button>`:m.state==='claimed'?`<span class="rt ok">${esc(tx('claimed'))}</span>`:m.state==='expired'?`<span class="rt ex">${esc(tx('expired'))}</span>`:`<span class="rt">${rwH(m.reward)}</span>`;
 return `<div class="mn-m ${m.state==='expired'?'exp':''}" role="button" tabindex="0" data-x="one" data-i="${esc(m.id)}"><span class="r1"><span class="ic">${sv(MIC[m.id]||m.icon||'target')}</span><span class="tt"><b>${esc(title(m))}</b><small>${esc(desc(m))}</small></span>${right}</span><span class="r2"><span class="pb"><i style="width:${p}%"></i></span><span>${num(Math.min(m.progress,m.goal))} / ${num(m.goal)}</span></span></div>`};
