async function claim(id,after){try{const r=await api('/api/app/missions/claim',{id});if(r&&r.ok){say(tx('got',{r:rw(r.got)}));after(r)}else say(tx(r&&r.err)||tx('err'))}
 catch(e){say(tx('checking'));try{const r=await api('/api/app/missions?period=all');if(r&&r.ok)after(r)}catch(_){say(tx('offline'))}}}
const ACTS=(el,reload,list)=>({claim:b=>claim(b.dataset.i,reload),one:b=>details(b.dataset.i,list())});

