async function home(){const el=page(tx('home'),'target','');let tab='day',d;
 const draw=()=>{const items=tab==='event'?[]:(d.items||[]).filter(m=>m.period===tab);
  set(el,`${sum(tx('today_p'),d.summary.day)}<div class="mn-tabs"><button class="${tab==='day'?'on':''}" data-x="t" data-i="day">${esc(tx('t_daily'))}</button><button class="${tab==='week'?'on':''}" data-x="t" data-i="week">${esc(tx('t_weekly'))}</button><button data-x="ev">${esc(tx('t_events'))}</button></div>
