   ${items.map(card).join('')||`<div class="mn-empty">${esc(tx('empty'))}</div>`}
   <button class="mn-row" data-x="ci"><span class="ic">${sv('flame')}</span><span class="tt">${esc(tx('streak_row'))}</span><span class="v">${esc(tx('streak_d',{n:d.streak||0}))}</span><span class="ch">${sv('chevl')}</span></button>
