 el.__acts={async go(b){b.disabled=true;try{const r=await api('/api/app/checkin',{});if(r&&r.ok){d=r;draw();if(r.got)say(tx('got',{r:rw(r.got)}))}else{say(tx(r&&r.err)||tx('err'));b.disabled=false}}catch(e){say(tx('checking'));try{const r=await api('/api/app/checkin');if(r&&r.ok){d=r;draw()}}catch(_){}}}};
