.s3 .fr-seg button{flex:1;height:34px;border-radius:10px!important;font-size:12px;font-weight:700;color:var(--wk-text2)!important;text-align:center!important;white-space:nowrap}
.s3 .fr-seg button.on{background:color-mix(in srgb,var(--s3-hd) 70%,var(--wk-surface))!important;color:#fff!important}
/* report + gift */
.s3 .fr-rr{display:flex!important;align-items:center;gap:12px;width:100%;min-height:52px;padding:0 16px!important;direction:var(--wk-dir,rtl);text-align:start!important;font-size:14.5px;font-weight:700;color:var(--wk-text)!important}
.s3 .fr-rr+.fr-rr{border-top:1px solid var(--wk-border)!important}.fr-rr i{width:20px;height:20px;border-radius:50%;border:2px solid var(--wk-border);flex:none}.fr-rr.on i{border:6px solid var(--s3-hd)}
.fr-ta{width:100%;min-height:80px;margin-top:12px;padding:12px 14px;border-radius:14px;background:var(--wk-surface);border:1px solid var(--wk-border);color:var(--wk-text);font:inherit;font-size:14px;direction:var(--wk-dir,rtl);resize:none;outline:0;box-sizing:border-box}
.fr-gg{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.s3 .fr-gi{display:flex!important;flex-direction:column;align-items:center;gap:4px;padding:12px 4px!important;border-radius:14px!important;background:var(--wk-surface)!important;border:1px solid var(--wk-border)!important;font-size:12px;font-weight:700;color:var(--wk-text)!important;text-align:center!important}
.s3 .fr-gi.on{border-color:var(--s3-hd)!important;background:color-mix(in srgb,var(--s3-hd) 18%,var(--wk-surface))!important}
.fr-gi .a{width:54px;height:54px;display:grid;place-items:center}.fr-gi .a img,.fr-gi .a svg{width:100%;height:100%;object-fit:contain;margin:0}.fr-gi small{font-size:11px;color:var(--wk-text2);direction:ltr}`;
try{const s=document.createElement('style');s.id='fr3-css';s.textContent=css;document.head.appendChild(s)}catch(e){}

/* ---------- small pieces ---------- */
function page(title,icon,body,act){const el=S3().push(title,body);el.classList.add('fr3');if(icon)el.querySelector('.s3-hd').insertAdjacentHTML('beforeend',`<span class="fr-hi${act?' tap':''}" ${act?`data-x="${act}" role="button"`:''}>${sv(icon)}</span>`);el.__acts={};return el}
const set=(el,h)=>S3().setBody(el,h);
const sk=n=>`<div class="fr-list">${'<div class="fr-sk"></div>'.repeat(n||5)}</div>`;
const empty=(ic,t,d,btn)=>`<div class="fr-empty"><div class="ic">${sv(ic)}</div><b>${esc(t)}</b>${d?`<p>${esc(d)}</p>`:''}${btn||''}</div>`;
const offline=()=>empty('bolt',tx('offline'),'',`<button data-x="retry">${esc(tx('retry'))}</button>`);
const avSrc=u=>{const a=u&&u.avatar;return !a?'':typeof a==='string'?a:(a.url||a.src||'')};
const ini=u=>esc(String((u&&(u.name||u.username))||'W').trim().charAt(0).toUpperCase());
const av=(u,dot=true)=>{const s=avSrc(u);return `<span class="fr-av">${s?`<img class="p" src="${esc(s)}" alt="" loading="lazy" decoding="async" onerror="this.remove()">`:''}${s?'':ini(u)}${dot&&u.online?'<i class="dot"></i>':''}</span>`};
const marks=u=>(u.verified?VER:'')+(u.tier&&TIER[u.tier]?`<img class="fr-tier" src="${TIER[u.tier]}" alt="">`:'');
const status=u=>u.online?`<i class="g"></i>${esc(tx('online'))}`:u.seen?esc(tx('seen',{t:ago(u.seen)})):'';
const sub=u=>u.mutual?esc(tx('mut_n',{n:u.mutual})):u.username?`<bdi dir="ltr">@${esc(u.username)}</bdi>`:'';
const row=(u,right,line)=>`<div class="fr-u" role="button" tabindex="0" data-x="pf" data-u="${Number(u.id)}">${av(u)}<span class="tt"><span class="nm"><bdi>${esc(u.name||u.username||'—')}</bdi>${marks(u)}</span><small>${line!=null?line:sub(u)}</small></span>${right||''}</div>`;
const msgBtn=u=>`<button class="fr-ib" data-x="dm" data-u="${Number(u.id)}" aria-label="${esc(tx('p_msg'))}">${sv('msg')}</button>`;
const relBtn=u=>{const r=u.relation;const id=Number(u.id);
 if(r==='accepted')return `<span class="fr-pill ok">${esc(tx('a_friend'))}</span>`;
 if(r==='outgoing')return `<button class="fr-pill soft" data-x="fa" data-a="cancel" data-u="${id}">${esc(tx('a_sent'))}</button>`;
 if(r==='incoming')return `<button class="fr-pill" data-x="fa" data-a="accept" data-u="${id}">${esc(tx('a_reply'))}</button>`;
 if(u.can_request===false)return u.following?`<button class="fr-pill soft" data-x="fo" data-on="0" data-u="${id}">${esc(tx('a_unfollow'))}</button>`:`<button class="fr-pill" data-x="fo" data-on="1" data-u="${id}">+${esc(tx('a_follow'))}</button>`;
 return `<button class="fr-pill" data-x="fa" data-a="request" data-u="${id}">+${esc(tx('a_add'))}</button>`};
async function call(path,body){return await api(path,body)}
function dm(uid){try{if(window.wm70OpenDM)return wm70OpenDM(Number(uid))}catch(e){}say(tx('err'))}
function confirm2(q,yes,f){const d=document.createElement('div');d.className='s3-dim';d.innerHTML=`<div class="s3-sh"><p>${esc(q)}</p><button class="s3-btn" style="background:#B91C1C!important" data-y="1">${esc(yes)}</button><button class="s3-btn soft" style="color:var(--wk-text)!important" data-y="0">${esc(tx('cancel'))}</button></div>`;
 d.onclick=e=>{const b=e.target.closest('[data-y]');if(e.target===d||b){d.remove();if(b&&b.dataset.y==='1')f()}};document.body.appendChild(d)}
/* friend / follow actions shared by every list; the server answers with the real relation */
async function friendAct(uid,action,after){try{const r=await call('/api/app/social/friend',{uid:Number(uid),action});if(r&&r.ok){say(tx({request:'done_req',accept:'done_acc',decline:'done_dec',cancel:'done_can',remove:'done_rem'}[action]||'saved'));after&&after(r)}else say(ERR(r&&r.err))}catch(e){say(tx('offline'))}}
async function followAct(uid,on,after){try{const r=await call('/api/app/social/follow',{uid:Number(uid),on:!!on});if(r&&r.ok)after&&after(r);else say(ERR(r&&r.err))}catch(e){say(tx('offline'))}}
/* common row actions; reload() redraws the page with fresh server data */
const ROWS=(reload)=>({pf:b=>profile(+b.dataset.u),dm:b=>dm(b.dataset.u),retry:()=>reload(),
 fa(b){const a=b.dataset.a,u=b.dataset.u;b.disabled=true;if(a==='remove'){b.disabled=false;return confirm2(tx('q_unfr',{n:b.closest('.fr-u').querySelector('.nm bdi').textContent}),tx('yes_unfr'),()=>friendAct(u,a,reload))}friendAct(u,a,reload).finally(()=>{b.disabled=false})},
 fo(b){b.disabled=true;followAct(b.dataset.u,b.dataset.on==='1',reload).finally(()=>{b.disabled=false})}});
function bindStop(el){/* buttons inside a row must not open the profile */
 el.addEventListener('click',e=>{const b=e.target.closest('[data-x]');if(b&&b.dataset.x!=='pf'&&b.closest('.fr-u'))e.stopPropagation()},true)}
/* debounced search box */
const input=(id,ph,v)=>`<label class="fr-in">${sv('search')}<input id="${id}" type="search" placeholder="${esc(ph)}" value="${esc(v||'')}" maxlength="40" autocapitalize="off" autocomplete="off" enterkeyhint="search"></label>`;
function onType(el,id,f){let t=0;el.addEventListener('input',e=>{if(e.target.id!==id)return;clearTimeout(t);t=setTimeout(()=>f(e.target.value.trim()),300)})}
const keepFocus=(el,id)=>{const i=el.querySelector('#'+id);if(i){i.focus();const n=i.value.length;try{i.setSelectionRange(n,n)}catch(e){}}};

/* ---------- 1. hub ---------- */
async function hub(){const el=page(tx('hub'),'users','');let d=null;
 const draw=()=>{const c=(d&&d.counts)||{};const n=v=>d?kfmt(v):'—';
  set(el,`<div class="fr-card fr-stats">
   <button data-x="go" data-p="following"><span class="ic">${sv('user')}</span><small>${esc(tx('following'))}</small><b>${n(c.following)}</b></button>
   <button data-x="go" data-p="followers"><span class="ic">${sv('users')}</span><small>${esc(tx('followers'))}</small><b>${n(c.followers)}</b></button>
   <button data-x="go" data-p="req"><span class="ic">${sv('uplus')}${c.requests_in?`<i class="fr-badge">${c.requests_in>99?'99+':c.requests_in}</i>`:''}</span><small>${esc(tx('requests'))}</small><b>${n(c.requests_in)}</b></button></div>
  <div class="fr-card fr-menu">
   ${mi('users','mine',d?num(c.friends):'')}${mi('star','sug')}${mi('search','find')}${mi('uplus','req',c.requests_in?num(c.requests_in):'')}${mi('send','invite','',tx('inv_d'))}</div>
  <div class="fr-card fr-menu">${mi('shield','blocked',c.blocked?num(c.blocked):'')}${mi('gear','priv')}</div>`)};
 const mi=(ic,p,v,s)=>`<button class="fr-mi" data-x="go" data-p="${p}"><span class="ic">${sv(ic)}</span><span class="tt">${esc(tx(p))}${s?`<small>${esc(s)}</small>`:''}</span>${v?`<span class="v">${esc(v)}</span>`:''}<span class="ch">${sv('chevl')}</span></button>`;
 const load=async()=>{try{const r=await call('/api/app/social');if(r&&r.ok){d=r;draw()}else throw 0}catch(e){if(!d)set(el,offline())}};
 el.__acts={go(b){({following:()=>follows('following'),followers:()=>follows('followers'),req:()=>requests(),mine:()=>friends(),sug:()=>find('sug'),find:()=>find('res'),invite:()=>invite(),blocked:()=>blocked(),priv:()=>privacy()})[b.dataset.p]()},retry:load};
 el.__reload=load;draw();load();return el}

/* ---------- 2. my friends ---------- */
async function friends(){const el=page(tx('mine'),'uplus','',  'add');let f='all',q='',d=null,items=[],next=null;bindStop(el);
 const draw=()=>{const c=(d&&d.counts)||{};
  el.querySelector('.s3-hd h1').textContent=tx('mine')+(d?` (${num(c.all)})`:'');
  set(el,`${input('frq',tx('ph_fr'),q)}<div class="fr-tabs">${[['all','f_all'],['online','f_on'],['offline','f_off']].map(([k,l])=>`<button class="${f===k?'on':''}" data-x="f" data-f="${k}">${esc(tx(l))}${d&&k!=='all'&&c[k]!=null?` (${num(c[k])})`:''}</button>`).join('')}</div>
   ${!d?sk(6):items.length?`<div class="fr-list">${items.map(u=>row(u,msgBtn(u),status(u)||sub(u))).join('')}</div>${next?`<button class="fr-wide" data-x="more">${esc(tx('more'))}</button>`:''}`
    :q?empty('search',tx('e_res'),''):empty('users',tx('e_friends'),tx('e_friends_d'),`<button data-x="add">${esc(tx('find'))}</button>`)}`);keepFocus(el,'frq')};
 const load=async more=>{try{const r=await call('/api/app/social/list?kind=friends&f='+f+'&q='+encodeURIComponent(q)+(more&&next?'&before='+next:''));if(!r||!r.ok)throw 0;d=r;items=more?items.concat(r.items):r.items;next=r.next||null;draw()}catch(e){if(!d)set(el,offline());else say(tx('offline'))}};
 el.__acts=Object.assign(ROWS(()=>load()),{f(b){f=b.dataset.f;d=null;draw();load()},more:()=>load(true),add:()=>find('res')});
 onType(el,'frq',v=>{q=v;load()});draw();load();return el}

/* ---------- 3. find users (search + suggestions) ---------- */
async function find(tab){const el=page(tab==='sug'?tx('sug'):tx('find'),'search','');let t=tab||'res',q='',items=null,next=null,busy=false;bindStop(el);
 const body=()=>{if(t==='res'&&q.length<2)return empty('search',tx('e_type'),tx('e_res_d'));if(items===null)return sk(5);
  if(!items.length)return t==='res'?empty('search',tx('e_res'),tx('e_res_d')):empty('star',tx('e_sug'),'');
  return `<div class="fr-list">${items.map(u=>row(u,relBtn(u))).join('')}</div>${next?`<button class="fr-wide" data-x="more">${esc(tx('more'))}</button>`:''}`};
 const draw=()=>{set(el,`${input('fdq',tx('ph_find'),q)}<div class="fr-tabs"><button class="${t==='res'?'on':''}" data-x="t" data-t="res">${esc(tx('t_res'))}</button><button class="${t==='sug'?'on':''}" data-x="t" data-t="sug">${esc(tx('t_sug'))}</button></div>${body()}`);keepFocus(el,'fdq')};
 const load=async more=>{if(t==='res'&&q.length<2){items=[];draw();return}if(busy)return;busy=true;
  try{const r=await call(t==='res'?'/api/app/social/search?q='+encodeURIComponent(q)+(more&&next?'&page='+next:''):'/api/app/social/list?kind=suggest');if(!r||!r.ok)throw r;items=more?(items||[]).concat(r.items):r.items;next=r.next||null;draw()}
  catch(e){if(e&&e.err)say(ERR(e.err));else if(items===null)set(el,offline())}finally{busy=false}};
 el.__acts=Object.assign(ROWS(()=>load()),{t(b){t=b.dataset.t;items=null;draw();load()},more:()=>load(true)});
 onType(el,'fdq',v=>{q=v;if(t!=='res'){t='res'}items=null;draw();load()});
 if(t==='res')items=[];draw();if(t!=='res')load();return el}

/* ---------- 4. friend requests ---------- */
async function requests(){const el=page(tx('req'),'uplus','');let t='in',d=null;bindStop(el);
 const draw=()=>{const c=(d&&d.counts)||{};
  el.querySelector('.s3-hd h1').textContent=tx('req')+(d?` (${num(c.in)})`:'');
  const list=!d?sk(4):d.items.length?`<div class="fr-list">${d.items.map(u=>t==='in'
    ?row(u,`<button class="fr-ib ok" data-x="fa" data-a="accept" data-u="${u.id}" aria-label="${esc(tx('accept'))}">${sv('check')}</button><button class="fr-ib" data-x="fa" data-a="decline" data-u="${u.id}" aria-label="${esc(tx('decline'))}">${sv('x')}</button>`,(u.mutual?esc(tx('mut_n',{n:u.mutual}))+' · ':'')+esc(ago(u.ts)))
    :row(u,`<button class="fr-pill soft" data-x="fa" data-a="cancel" data-u="${u.id}">${esc(tx('cancel_req'))}</button>`,`${sv('clock').replace('<svg','<svg style="width:13px;height:13px"')} ${esc(tx('pending'))} · ${esc(ago(u.ts))}`)).join('')}</div>
    ${t==='in'&&d.items.length>1?`<button class="fr-wide red" data-x="all">${sv('trash')}${esc(tx('decline_all'))}</button>`:''}`
   :empty('uplus',tx(t==='in'?'e_in':'e_out'),'');
  set(el,`<div class="fr-tabs"><button class="${t==='in'?'on':''}" data-x="t" data-t="in">${esc(tx('t_in'))}${d?` (${num(c.in)})`:''}</button><button class="${t==='out'?'on':''}" data-x="t" data-t="out">${esc(tx('t_out'))}${d?` (${num(c.out)})`:''}</button></div>${list}`)};
 const load=async()=>{try{const r=await call('/api/app/social/requests?tab='+t);if(!r||!r.ok)throw 0;d=r;draw()}catch(e){if(!d)set(el,offline())}};
 el.__acts=Object.assign(ROWS(load),{t(b){t=b.dataset.t;d=null;draw();load()},
  all:()=>confirm2(tx('q_decline_all'),tx('yes_all'),async()=>{try{const r=await call('/api/app/social/friend',{action:'decline_all'});if(r&&r.ok){say(tx('done_dec'));load()}else say(ERR(r&&r.err))}catch(e){say(tx('offline'))}})});
 draw();load();return el}

/* ---------- 5. public profile ---------- */
const MT='<svg class="mt" viewBox="0 0 400 90" preserveAspectRatio="none"><path fill="currentColor" d="M0 90V58l40-22 34 18 46-38 40 30 30-16 52 34 38-26 44 22 36-18 40 20v28Z" opacity=".55"/><path fill="currentColor" d="M0 90V70l52-16 44 14 56-24 48 22 40-12 60 18 46-14 54 16v16Z"/></svg>';
const RANK_FA={newcomer:'تازه‌وارد',bronze:'برنزی',silver:'نقره‌ای',gold:'طلایی',platinum:'پلاتینیوم',diamond:'الماس',master:'استاد',legend:'افسانه',emperor:'امپراتور',sovereign:'فرمانروا'};
const rk=k=>L()==='fa'?(RANK_FA[k]||k):String(k||'').replace(/^./,c=>c.toUpperCase());
const ACH_FA={first_login:'اولین ورود',days_7:'۷ روز حضور',days_30:'۳۰ روز حضور',first_friend:'اولین دوست',friends_50:'۵۰ دوست',first_gift:'اولین هدیه',gifts_100:'۱۰۰ هدیه',first_got:'اولین هدیهٔ دریافتی',missions_100:'۱۰۰ مأموریت',level_50:'سطح ۵۰',level_100:'سطح ۱۰۰',event_launch:'جشن راه‌اندازی'};
const giftArt=code=>{try{if(window.ST3&&ST3.art){const a=ST3.art({cat:'gifts',code,id:'g_'+code});if(a&&!/fr-ph/.test(a))return a}}catch(e){}try{const w=window.WM70;if(w&&w.gifts&&w.gifts.some(g=>g.code===code)&&window.wm70GiftArt)return wm70GiftArt(w.gifts.find(g=>g.code===code))}catch(e){}return sv('gift')};
async function profile(uid){uid=Number(uid);if(!uid)return;const el=page('', '','');el.classList.add('frp');let d=null,tab='about';bindStop(el);
 const hd=el.querySelector('.s3-hd');if(hd)hd.style.cssText='position:absolute;z-index:3;inset:0 0 auto 0;background:none;border:0';
 const frame=u=>{const f=null;/* no profile frames for now */if(!f)return '';if(f.art)return `<img class="fr-fr" src="${esc(f.art)}" alt="">`;try{return window.ST3?ST3.frameSVG(f).replace('class="st-fr"','class="fr-fr"'):''}catch(e){return ''}};
 const draw=()=>{if(!d){set(el,`<div class="fr-pf"><div class="fr-cov">${MT}</div><div class="fr-pav"><div class="ph"></div></div><div style="padding:24px 16px">${sk(3)}</div></div>`);return}
  const u=d.user,s=u.stats||{},c=u.can||{},r=u.relation;const S=v=>v==null?`<span class="lk">${sv('lock')}</span>`:kfmt(v);
  const fbtn=r==='accepted'?`<button class="ok" data-x="opt">${sv('ucheck')}${esc(tx('p_friends'))}</button>`:r==='outgoing'?`<button data-x="pfa" data-a="cancel">${sv('clock')}${esc(tx('p_sent'))}</button>`:r==='incoming'?`<button class="main" data-x="pfa" data-a="accept">${sv('uplus')}${esc(tx('p_reply'))}</button>`:c.friend?`<button class="main" data-x="pfa" data-a="request">${sv('uplus')}${esc(tx('p_add'))}</button>`:'';
  const fol=c.follow||u.following?(u.following?`<button data-x="pfo" data-on="0">${sv('ucheck')}${esc(tx('p_following'))}</button>`:`<button class="${fbtn.includes('main')?'':'main'}" data-x="pfo" data-on="1">${esc(tx('p_follow'))}</button>`):'';
  const top=[fbtn,fol].filter(Boolean);
  set(el,`<div class="fr-pf"><div class="fr-cov">${u.bg&&u.bg.url?`<img class="bg" src="${esc(u.bg.url)}" alt="">`:MT}<button class="fr-pm" data-x="opt" aria-label="more">${sv('more')}</button></div>
   <div class="fr-pav"><div class="ph">${avSrc(u)?`<img src="${esc(avSrc(u))}" alt="">`:ini(u)}</div>${frame(u)}${u.online?'<i class="dot"></i>':''}</div>
   <div class="fr-pn"><b><bdi>${esc(u.name||u.username)}</bdi>${u.verified?VER:''}</b>${u.username?`<small>@${esc(u.username)}</small>`:''}${window.WK2_BADGES?WK2_BADGES.html({role:u.role,tier:u.tier}):''}</div>
   <div class="fr-chips">${u.level?`<span class="fr-chip" style="--rc:${esc((u.rank&&u.rank.color)||'#9CA3AF')}"><i></i>${esc(tx('lvl',{n:u.level}))} · ${esc(rk(u.rank&&u.rank.key))}</span>`:''}${u.follows_you?`<span class="fr-chip">${esc(tx('follows_you'))}</span>`:''}${!u.online&&u.seen?`<span class="fr-chip">${esc(tx('seen',{t:ago(u.seen)}))}</span>`:''}</div>
   ${u.blocked_by_me?'':`${u.bio?`<div class="fr-bio" dir="auto">${esc(u.bio)}</div>`:''}
   <div class="fr-pst"><button data-x="pl" data-k="friends"><b>${S(s.friends)}</b><small>${esc(tx('friends'))}</small></button><button data-x="pl" data-k="followers"><b>${S(s.followers)}</b><small>${esc(tx('followers'))}</small></button><button data-x="pl" data-k="following"><b>${S(s.following)}</b><small>${esc(tx('following'))}</small></button></div>
   <div class="fr-acts" style="grid-template-columns:${top.length===2?'1fr 1fr':'1fr'} 1fr auto">${top.join('')}<button data-x="msg" ${c.message?'':'disabled style="opacity:.5"'}>${sv('msg')}${esc(tx('p_msg'))}</button>${c.gift?`<button class="sq" data-x="gift" aria-label="${esc(tx('p_gift'))}">${sv('gift')}</button>`:''}</div>`}
   ${u.blocked_by_me?`<div class="fr-lock"><div class="ic">${sv('ban')}</div><b>${esc(tx('blocked_t'))}</b><p>${esc(tx('blocked_d'))}</p></div><div style="padding:0 16px"><button class="fr-wide main" data-x="unblock">${esc(tx('o_unblock'))}</button></div>`
    :u.private?`<div class="fr-lock"><div class="ic">${sv('lock')}</div><b>${esc(tx('private_t'))}</b><p>${esc(tx('private_d'))}</p></div>`
