 const tabBody=u=>{if(tab==='about'){const g=u.showcase;return `${u.joined?`<div class="fr-kv">${sv('cal')}<span>${esc(tx('joined',{d:ymd(u.joined)}))}</span></div>`:''}${u.wid?`<div class="fr-kv">${sv('user')}<span dir="ltr">ID ${esc(u.wid)}</span></div>`:''}
