/* ---------- pieces ---------- */
function page(title,body){const el=S3().push(title,body);el.classList.add('ct3');el.querySelector('.s3-hd').insertAdjacentHTML('beforeend','<span class="ct-chip">W CONTROL</span>');el.__acts={};return el}
const set=(el,h)=>S3().setBody(el,h);
const sk=n=>'<div class="ct-sk"></div>'.repeat(n||4);
const empty=(ic,t,d,btn)=>`<div class="ct-empty"><div class="ic">${sv(ic)}</div>${t?`<b>${esc(t)}</b>`:''}${d?esc(d):''}${btn||''}</div>`;
const offline=()=>empty('alert',tx('offline'),'',`<button data-x="retry">${esc(tx('retry'))}</button>`);
const denied=()=>empty('lock',tx('denied'),tx('denied_d'));
const ini=u=>esc(String((u&&(u.username||u.name))||'W').replace(/^@/,'').slice(0,2).toUpperCase());
const av=u=>{const a=u&&u.avatar;return `<span class="ct-av">${a&&!/^\/ava\//.test(a)?`<img src="${esc(a)}" alt="" onerror="this.remove()">`:ini(u)}</span>`};
const wkh=u=>u&&u.wid?'WKH-'+u.wid:'';
const handle=u=>[u.username?'@'+u.username:'',wkh(u)].filter(Boolean).join(' · ');
const stPill=u=>u.state==='blocked'?`<span class="ct-pill r">${esc(tx('st_blocked'))}</span>`:u.state==='limited'?`<span class="ct-pill r">${esc(tx('st_limited'))}</span>`:u.tier&&u.tier.tier&&u.tier.tier!=='free'?`<span class="ct-pill y">${esc(u.tier.tier.replace(/^./,c=>c.toUpperCase()))}</span>`:`<span class="ct-pill g">${esc(tx('st_active'))}</span>`;
const urow=(u,right)=>`<div class="ct-u" role="button" data-x="user" data-q="${esc(u.username||u.wid||u.uid)}">${av(u)}<span class="tt"><b>${esc(u.name||u.username||'—')}</b><small>${esc(handle(u))}</small></span>${right!=null?right:stPill(u)}</div>`;
async function call(path,body){return await api(path,body)}
/* sheet with optional PIN; resolves {pin} or null */
function sheet({title,text,sumHtml,pin,yes,red,extra}){return new Promise(res=>{const d=document.createElement('div');d.className='ct-dim';
 d.innerHTML=`<div class="ct-sheet"><h3>${esc(title)}</h3>${text?`<p>${esc(text)}</p>`:''}${sumHtml||''}${extra||''}${pin?`<input class="pin" type="password" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="••••">`:''}
  <button class="${red?'r':'y'}" data-y="1">${esc(yes||tx('pin_go'))}</button><button class="n" data-y="0">${esc(tx('cancel'))}</button></div>`;
 const close=v=>{d.remove();res(v)};
 d.onclick=e=>{const b=e.target.closest('[data-y]');if(e.target===d)return close(null);if(!b)return;if(b.dataset.y==='0')return close(null);
  const p=d.querySelector('.pin');const ex=d.querySelector('[data-extra]');if(pin&&!/^\d{4,6}$/.test(p.value))return p.focus();close({pin:p?p.value:'',extra:ex?ex.value:''})};
 document.body.appendChild(d);const p=d.querySelector('.pin')||d.querySelector('[data-extra]');if(p)setTimeout(()=>p.focus(),60)})}
const needPin=p=>!!(ME&&(ME.pin_for||[]).includes(p));
/* run a server action; nothing is shown as done before the server says ok */
async function act(path,body,perm,{title,sumHtml,yes,red,text}={}){const s=await sheet({title:title||tx('confirm_t'),text,sumHtml,pin:needPin(perm),yes,red});if(!s)return null;
 if(s.pin)body.pin=s.pin;say(tx('pending'));
 try{let r=await call(path,body);if(r&&r.err==='confirm_big'){const c=await sheet({title:tx('confirm_t'),text:tx('confirm_big'),extra:`<input class="pin" data-extra style="letter-spacing:2px" inputmode="numeric" placeholder="${esc(tx('retype'))}">`,yes:tx('pin_go')});if(!c)return null;body.confirm=Number(c.extra||0);r=await call(path,body)}
  if(r&&r.ok)return r;say(ERR(r&&r.err));return null}catch(e){say(tx('offline'));return null}}
const sumBox=rows=>`<div class="ct-sum">${rows.map(([k,v,c])=>`<div><span>${esc(k)}</span><b class="${c||''}">${v}</b></div>`).join('')}</div>`;
/* picks a user with a search box; calls back with the user (server lookup) */
function pickUser(el,id,onPick){let t=0;el.addEventListener('input',e=>{if(e.target.id!==id)return;clearTimeout(t);const v=e.target.value.trim();t=setTimeout(async()=>{if(v.length<2)return onPick(null);
 try{const r=await call('/api/ctl/user?q='+encodeURIComponent(v));onPick(r&&r.ok?r.user:null)}catch(_){onPick(null)}},450)})}
const uIn=(id,v)=>`<label class="ct-in">${sv('search')}<input id="${id}" value="${esc(v||'')}" placeholder="${esc(tx('ph_user'))}" autocapitalize="off" autocomplete="off" maxlength="40"></label>`;
const keep=(el,id)=>{const i=el.querySelector('#'+id);if(i&&document.activeElement!==i){const n=i.value.length;i.focus();try{i.setSelectionRange(n,n)}catch(e){}}};
const val=(el,id)=>((el.querySelector('#'+id)||{}).value||'').trim();
function done(title,lines){const el=page(tx('done'),'');set(el,`<div class="ct-ok"><div class="ic">${sv('check')}</div><b>${esc(title)}</b></div>${sumBox(lines)}<button class="ct-btn soft" data-x="home">${esc(tx('back_home'))}</button>`);
 el.__acts={home(){S3().back();setTimeout(()=>S3().back(),60)}}}

