 ['crown','subs','c_subs','subscriptions.grant'],['shirt','items','c_items','inventory.grant'],['chart-column','stats','c_stats','stats.read'],['settings-2','settings','c_set','settings.manage']];
async function home(){const el=page(tx('home'),sk(4));
 const draw=()=>set(el,`<div class="ct-hero"><span class="k">${esc(tx('hero_k'))}</span><span class="own">${esc((ME.role||'').toUpperCase().replace('_',' '))}</span><b>${esc(tx('hero_t'))}</b><small>${esc(tx('hero_d'))}</small></div>
  <div class="ct-grid">${CARDS.map(([ic,p,l,perm])=>{const on=can(perm);return `<button class="ct-tile ${on?'':'off'}" data-x="go" data-p="${p}" ${on?'':'aria-disabled="true"'}>${IC(ic)}<b>${esc(tx(l))}</b><small>${esc(tx(l+'_d'))}</small></button>`}).join('')}</div>
  <div class="ct-h"><b>${esc(tx('tools'))}</b></div>
  <div class="ct-card"><button class="ct-row" data-x="go" data-p="audit"><span class="ic">${sv('list')}</span><span class="tt">${esc(tx('activity'))}</span><span class="ch">${sv('chevl')}</span></button>
  ${can('reports.read')?`<button class="ct-row" data-x="go" data-p="reports"><span class="ic">${sv('flag')}</span><span class="tt">${esc(tx('reports_q'))}</span><span class="ch">${sv('chevl')}</span></button>`:''}</div>`);
 el.__acts={go(b){const p=b.dataset.p,c=CARDS.find(x=>x[1]===p);if(c&&!can(c[3]))return say(tx('forbidden'));({users,roles,coins,gift:()=>items('gifts'),subs,items:()=>items('badges'),stats,settings,audit,reports})[p]()},retry:()=>{S3().back();open()}};
 try{const r=await call('/api/ctl/me');if(!r||!r.ok){set(el,denied());return}ME=r;draw()}catch(e){set(el,offline())}}

/* ---------- 2. users ---------- */
async function users(){const el=page(tx('users'),'');let f='all',q='',d=null,sel=null;
 const draw=()=>{set(el,`${uIn('cuq',q)}<div class="ct-chips">${[['all','f_all'],['active','f_active'],['limited','f_limited'],['blocked','f_blocked'],['reported','f_reported']].map(([k,l])=>`<button class="${f===k?'on':''}" data-x="f" data-f="${k}">${esc(tx(l))}</button>`).join('')}</div>
