  q_account:[['چگونه وارد واخان شوم؟','با Google، Facebook یا ایمیل. اگر پیش‌تر ثبت‌نام کرده‌اید، با همان روش وارد شوید تا حساب، دوستان و سکه‌های شما حفظ شود.'],['کد ایمیل به من نرسید.','پوشهٔ اسپم را بررسی کنید و چند دقیقه صبر کنید. سپس در همان صفحه «ارسال دوبارهٔ کد» را بزنید.'],['چگونه نام کاربری خود را تغییر دهم؟','از «من › ویرایش پروفایل». نام کاربری را هر 14 روز یک بار می‌توان تغییر داد.'],['چگونه حساب خود را حذف کنم؟','از «من › تنظیمات › حذف حساب». با حذف حساب، سکه‌ها، اشتراک‌ها و آیتم‌های شما نیز برای همیشه پاک می‌شوند.']],
  q_media:[['آیا موسیقی و سینما رایگان است؟','بله. موسیقی و سینمای واخان برای همه رایگان است.'],['موسیقی از کجا پخش می‌شود؟','از YouTube و SoundCloud. منبع را بالای صفحهٔ موسیقی انتخاب کنید.'],['چگونه با دوستانم فلم ببینم؟','سینمای خود را باز کنید و شناسهٔ واخان یا نام کاربری خود را به دوستانتان بدهید تا وارد سینمای شما شوند.']],
  q_halls:[['چگونه در سالون صحبت کنم؟','روی یک صندلی بنشینید و میکروفون را روشن کنید. بار اول، اجازهٔ دسترسی به میکروفون را بدهید.'],['صدای سالون قطع می‌شود.','از «تنظیمات › تنظیمات پخش › اتصال صدا» گزینهٔ «مسیر امن» را انتخاب کنید و بررسی اتصال را انجام دهید.'],['دکمهٔ شناور پخش را مخفی کرده‌ام.','از «تنظیمات › تنظیمات پخش» کلید «میانبر شناور پخش» را روشن کنید.']],
  q_friends:[['چگونه دوست اضافه کنم؟','با نام کاربری یا شناسهٔ واخان جستجو کنید، یا کد QR پروفایل یکدیگر را اسکن کنید.'],['چگونه کسی را مسدود یا گزارش کنم؟','پروفایل آن شخص را باز کنید و «گزارش» یا «مسدود کردن» را بزنید. فهرست کاربران مسدودشده در «من» است.']],
  q_wallet:[['سکهٔ واخان چیست؟','سکه پول واقعی نیست و فقط داخل واخان برای هدیه، آیتم و خدمات به کار می‌رود.'],['اشتراک VIP، Premium و Royal چه چیزی می‌دهد؟','نشان، تم و امکانات ویژه. جزئیات هر اشتراک در «من › اشتراک VIP» آمده است.'],['چگونه اشتراک را لغو کنم؟','از App Store یا Google Play. اشتراک تا پایان دورهٔ پرداخت‌شده فعال می‌ماند.']],
  q_safety:[['چه کسی پروفایل مرا می‌بیند؟','نام، نام کاربری و عکس شما برای دیگران دیده می‌شود. بقیه را در «تنظیمات › حریم خصوصی» تعیین کنید.'],['واخان برای چه سنی است؟','برای افراد 16 سال و بالاتر.'],['محتوای نامناسب دیدم.','آن را گزارش دهید. تیم واخان گزارش‌ها را بررسی می‌کند و در صورت نقض قوانین اقدام می‌کند.']]},
