.sl-body .tk{animation:slrise .45s cubic-bezier(.2,.8,.2,1) both}.sl-body .tk:nth-child(2){animation-delay:.05s}.sl-body .tk:nth-child(3){animation-delay:.1s}.sl-body .tk:nth-child(n+4){animation-delay:.15s}
