  <span class="tx"><b><bdi>${esc(v.title)}</bdi></b><small><bdi>${esc(v.ch)}</bdi> · ${esc(v.live?tx('views',{n:short(v.views)}):tx('views',{n:short(v.views)})+' · '+ago(v.ts))}</small></span></span></div>`}
