 v.addEventListener('touchmove',e=>{if(y0==null)return;dy=e.touches[0].clientY-y0;if(dy<=0){if(on)set(0);return}if(!top())return;on=true;e.preventDefault();set(Math.min(110,dy*.5))},{passive:false});
