/* ---------- the queue (shared by the 2×2 row, the sources sheet and the queue page) */
const Q={d:null,at:0,subs:new Set()};
async function loadQ(force){const k=K();if(!k)return null;if(!force&&Q.d&&Date.now()-Q.at<3000)return Q.d;
 try{const j=await req('/api/app/salon/queue?code='+encodeURIComponent(k.cid()));Q.d=j;Q.at=Date.now();Q.subs.forEach(f=>f(j));return j}catch(e){return Q.d}}
async function qPost(body){const k=K();try{const j=await req('/api/app/salon/queue',Object.assign({code:k.cid()},body));Q.d=Object.assign(Q.d||{},j);Q.at=Date.now();Q.subs.forEach(f=>f(Q.d));return j}catch(e){note(t6('offline'),'x');loadQ(true);return null}}
const isHost=()=>{const k=K();return !!((Q.d&&Q.d.host)||(k&&k.canCtl()))};

