 const pop=w.querySelector('.s6-pop');const W=Math.min(348,innerWidth-24);pop.style.width=W+'px';
 const br=(bar||btn).getBoundingClientRect(),bx=(btn||bar).getBoundingClientRect();pop.style.bottom=Math.max(12,innerHeight-br.top+10)+'px';
 const left=Math.max(12,Math.min(innerWidth-W-12,bx.left+bx.width/2-W/2));pop.style.left=left+'px';pop.style.transformOrigin=`${bx.left+bx.width/2-left}px 110%`;
 if(btn)btn.classList.add('r-open');
 const done=()=>{if(btn)btn.classList.remove('r-open');shut(w)};
 const cnt=d=>{const e=w.querySelector('.s6-qn');if(!e||!d)return;const n=(d.next||[]).length;e.hidden=!n;e.textContent=t6('videos',{n:num(n)})};
 cnt(Q.d);loadQ().then(cnt);
 w.addEventListener('click',e=>{const b=e.target.closest('[data-t]');if(!b)return done();hap();const t=b.dataset.t;done();
