/* ---------- gift: (who) → (which gift, real price, my balance) → one tap sends; a repeat tap cannot charge twice */
async function gift(uid){const k=K();if(!k)return;const st={uid:Number(uid)||0,from:!uid,sel:null,busy:false,key:null,err:'',gifts:(typeof WM70!=='undefined'&&WM70.gifts&&WM70.gifts.length)?WM70.gifts:null,bal:null};
 const w=mk('s6 s6-sh');const person=id=>{const p=k.seats().find(x=>x&&Number(x.id)===Number(id));return p||null};
 const art=g=>{try{if(typeof wm70GiftArt==='function')return wm70GiftArt(g)}catch(e){}return S(IC.gift,1.5)};
 const gname=g=>{const n=g&&g.name;return (n&&(n[L()]||n.fa||n.en))||(g&&g.code)||''};
 const draw=()=>{const p=st.uid?person(st.uid):null;let h='';
  if(!st.uid||!p){const ppl=k.seats().filter(x=>x&&Number(x.id)!==k.me());st.uid=0;
   h=`<div class="s6-hd"><b>${esc(t6('giftFor'))}</b><button class="s6-x" data-g="x" aria-label="${esc(t6('close'))}">${S(IC.x,2)}</button></div>
    ${ppl.length?`<div class="s6-ppl">${ppl.map((x,i)=>`<button class="s6-pp" data-u="${Number(x.id)}" style="--k:${i}">${k.ava(x)}<span><bdi>${esc(x.name||'')}</bdi></span></button>`).join('')}</div>`:`<p class="s6-e">${S(IC.gift,1.6)}<span>${esc(t6('nobody'))}</span></p>`}`}
  else{const g=(st.gifts||[]).find(x=>x.code===st.sel);const price=g?Number(g.coins):0;const low=g&&st.bal!=null&&Number(st.bal)<price;
   h=`<div class="s6-hd s6-to">${st.from?`<button class="s6-x s6-bk" data-g="who" aria-label="${esc(t6('change'))}">${S(IC.back,2)}</button>`:''}<span class="s6-rc">${k.ava(p)}<span><small>${esc(t6('giftFor'))}</small><b><bdi>${esc(p.name||'')}</bdi></b></span></span>
     <span class="s6-bal" aria-label="${esc(t6('balance'))}">${S(IC.coin,1.6)}<b>${st.bal==null?'—':esc(coins(st.bal))}</b></span></div>
    <div class="s6-gg">${st.gifts?st.gifts.map((x,i)=>`<button class="s6-gi${x.code===st.sel?' s6-on':''}" data-c="${esc(x.code)}" style="--k:${Math.min(i,11)}" aria-pressed="${x.code===st.sel}"><i>${art(x)}</i><span>${esc(gname(x))}</span><em>${S(IC.coin,1.6)}${esc(coins(x.coins))}</em></button>`).join(''):'<i class="s6-sk"></i>'.repeat(8)}</div>
    ${st.err?`<p class="s6-err">${esc(st.err)}</p>`:''}
    <button class="s6-go" data-g="send" ${!g||low||st.busy?'disabled':''}>${st.busy?'<i class="s6-spin"></i>':low?`<span>${esc(t6('low'))}</span>`:g?`${S(IC.gift,1.8)}<span>${esc(t6('sendTo',{n:p.name||''}))}</span><em>${S(IC.coin,1.6)}${esc(coins(price))}</em>`:`<span>${esc(t6('pickGift'))}</span>`}</button>`}
  w.innerHTML=`<div class="s6-bx" role="dialog"><i class="s6-gr"></i>${h}</div>`};
 draw();
 (async()=>{try{if(!st.gifts){const j=await req('/api/v70/gifts');st.gifts=j.gifts||[];try{if(typeof WM70!=='undefined'&&WM70.gifts&&!WM70.gifts.length)WM70.gifts=st.gifts}catch(e){}}}catch(e){st.gifts=[]}
  try{const b=await req('/api/app/salon/wallet');st.bal=b.balance}catch(e){try{st.bal=WC23.data.balance}catch(_){}}if(w.isConnected)draw()})();
 w.addEventListener('click',async e=>{if(e.target===w)return shut(w);const u=e.target.closest('[data-u]');if(u){hap();st.uid=+u.dataset.u;st.err='';return draw()}
  const c=e.target.closest('[data-c]');if(c){hap();st.sel=c.dataset.c;st.key=null;st.err='';return draw()}
  const b=e.target.closest('[data-g]');if(!b||b.disabled)return;const a=b.dataset.g;hap();
  if(a==='x')return shut(w);if(a==='who'){st.uid=0;st.sel=null;st.err='';return draw()}
  if(a==='send'&&!st.busy){const g=(st.gifts||[]).find(x=>x.code===st.sel),p=person(st.uid);if(!g)return;if(!p){st.err=t6('left');return draw()}
   st.busy=true;st.err='';draw();
   try{const q=await req('/api/v70/gifts',{action:'quote',uid:st.uid,room:k.cid(),gift:g.code});st.key=st.key||key();
    const v=await req('/api/v70/gifts',{action:'send',uid:st.uid,room:k.cid(),gift:g.code,token:q.token,client_key:st.key});
    try{if(window.WC23&&WC23.data)WC23.data.balance=v.balance}catch(_){}shut(w);fly(g,p.name||'');try{window.wc23Refresh&&wc23Refresh()}catch(_){}}
   catch(x){st.busy=false;const m=x.message;if(m==='quote_invalid'||m==='quote_changed')st.key=null;st.err=m==='balance'||m==='insufficient'||m==='low_balance'?t6('low'):m==='recipient_left'?t6('left'):t6('offline');if(w.isConnected)draw()}}});
 function fly(g,name){const d=document.createElement('div');d.className='s6-fly';d.dir=RTL()?'rtl':'ltr';d.innerHTML=`<i>${art(g)}</i><span>${esc(t6('sent',{g:gname(g),n:name}))}</span>`;document.body.appendChild(d);setTimeout(()=>d.remove(),3000)}}

