 w.innerHTML=`<div class="s6-bx" role="dialog"><i class="s6-gr"></i><div class="s6-hd"><b>${esc(t6('pick'))}</b><button class="s6-x" data-s="x" aria-label="${esc(t6('close'))}">${S(IC.x,2)}</button></div>
