    <form class="s6-lf" hidden novalidate><input type="text" inputmode="url" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="${esc(t6('paste'))}" aria-label="${esc(t6('paste'))}"><button type="submit" aria-label="${esc(t6('check'))}">${S(IC.check,2.2)}</button></form><div class="s6-lr"></div></div></div></div>`;
 const cnt=d=>{const e=w.querySelector('.s6-qn');if(!e||!d)return;const n=(d.next||[]).length;e.hidden=!n;e.textContent=t6('videos',{n:num(n)})};cnt(Q.d);loadQ().then(cnt);
 const lr=w.querySelector('.s6-lr');
 const res=()=>{if(!item){lr.innerHTML='';return}lr.innerHTML=`<div class="s6-pv"><span class="s6-th"><img src="${esc(item.thumb||'')}" alt=""></span><span class="s6-tt"><b><bdi>${esc(item.title||'')}</bdi></b><small>${srcH(item.src)}</small></span></div>
   <div class="s6-two">${host?`<button class="s6-go" data-s="play">${S(IC.play)}<span>${esc(t6('playNow'))}</span></button><button class="s6-go s6-cl" data-s="add">${S(IC.plus,2)}<span>${esc(t6('addQ'))}</span></button>`:`<button class="s6-go" data-s="add">${S(IC.plus,2)}<span>${esc(t6('suggest'))}</span></button>`}</div>`};
 const err=m=>{item=null;lr.innerHTML=`<p class="s6-err">${esc(m)}</p>`};
 const check=async()=>{const i=w.querySelector('.s6-lf input');const u=i.value.trim();if(!u||busy)return;busy=true;lr.innerHTML='<i class="s6-spin s6-spl"></i>';
  try{const j=await api('/api/app/salon/link',{code:k.cid(),url:u});if(j&&j.ok&&j.item){item=j.item;res()}else err(t6(j&&j.err==='unplayable'?'unplayable':j&&j.err==='not_found'?'notFound':'bad'))}catch(e){err(t6('offline'))}busy=false};
 w.addEventListener('submit',e=>{e.preventDefault();check()});
