/* ---------- the queue page: now playing, up next (owner drags and removes), friends' suggestions (owner approves) */
function queuePage(){const k=K();if(!k)return;const w=document.createElement('div');w.className='slr-pg s6-qp';w.dir=RTL()?'rtl':'ltr';
 w.innerHTML=`<div class="r-pgh"><button class="r-pgb" data-q="back" aria-label="${esc(t6('back'))}">${S(IC.chev,2)}</button><div><b>${esc(t6('queue'))}</b><small><bdi>${esc(k.room().name||'')}</bdi></small></div></div>
  <div class="s6-qb"><div class="s6-now s6-skn"></div></div><div class="s6-qf"><button class="s6-go s6-add" data-q="add">${S(IC.plus,2.2)}<span>${esc(t6(isHost()?'addV':'suggestV'))}</span></button></div>`;
 document.body.appendChild(w);requestAnimationFrame(()=>w.classList.add('in'));
 let D=Q.d,drag=false;const body=w.querySelector('.s6-qb');
 const row=(x,i,host)=>`<div class="s6-it" data-id="${Number(x.id)}" style="--k:${Math.min(i,8)}"><em class="s6-n">${num(i+1)}</em><span class="s6-th"><img src="${esc(x.thumb||'')}" alt=""></span><span class="s6-tt"><b><bdi>${esc(x.title||'')}</bdi></b><small>${srcH(x.src)}</small></span>${host?`<button class="s6-ia" data-q="rm" aria-label="${esc(t6('remove'))}">${S(IC.trash,1.7)}</button><button class="s6-ia s6-grip" data-q="grip" aria-label="${esc(t6('move'))}">${S(IC.grip)}</button>`:''}</div>`;
 const prow=(x,i,host)=>{const mine=x.by&&Number(x.by.id)===k.me();return `<div class="s6-it s6-pi" data-id="${Number(x.id)}" style="--k:${Math.min(i,8)}"><span class="s6-th"><img src="${esc(x.thumb||'')}" alt=""></span><span class="s6-tt"><b><bdi>${esc(x.title||'')}</bdi></b><small class="s6-by">${x.by?k.ava(x.by):''}<span>${esc(t6('from',{n:(x.by&&x.by.name)||''}))}</span></small></span>
