 const time=()=>{let t=0,d=0;try{t=YTP.getCurrentTime();d=YTP.getDuration()}catch(e){}if(!d&&D&&D.now){t=D.now.t||0;d=D.now.d||0}return [t,d]};
 const tick=()=>{const n=w.querySelector('.s6-now');if(!n||!D||!D.now)return;const [t,d]=time();const a=n.querySelector('.s6-tm');if(a)a.textContent=mmss(t)+' / '+mmss(d);const p=n.querySelector('.s6-pr i');if(p)p.style.width=(d?Math.min(100,t/d*100):0)+'%'};
 const draw=()=>{if(!D||drag)return;const host=isHost();const nx=D.next||[],pd=D.pending||[];
  body.innerHTML=(D.now?`<div class="s6-now"><img src="${esc(D.now.thumb||'')}" alt=""><i class="s6-shd"></i><span class="s6-live"><i></i>${esc(t6('nowPlaying'))}</span>
