/* WAKHAN 2.0 — «سالون» part 9: minimise and leave.
   The exit button opens a small clear-glass menu: «کوچک‌کردن» / «ترک سالون».
   Minimising keeps membership, seat and voice (hall2's keep-alive does that for seated people; this module keeps
   presence for the audience too) and shows a floating, draggable card with the film still playing, the salon's
   name, mic, back and leave. Tapping the card brings back the same salon at the same moment of the film.
   The old hall2 bubble stays as the engine but is hidden while this card is shown. Nothing on the server changes. */
(()=>{
const T={fa:{min:'کوچک‌کردن',leave:'ترک سالون',back:'برگشت به سالون',sure:'ترک سالون؟',cancel:'لغو',mic:'میکروفون',lost:'جایگاهت در سالون آزاد شد',gone:'سالون بسته شد',close:'بستن'},
 en:{min:'Minimise',leave:'Leave salon',back:'Back to the salon',sure:'Leave the salon?',cancel:'Cancel',mic:'Microphone',lost:'Your seat was released',gone:'The salon has closed',close:'Close'}};
const L=()=>{let l='en';try{l=((window.WK2L&&WK2L())||'en').slice(0,2)}catch(e){}return l};
const RTL=()=>['fa','ps','ar','ur'].includes(L());
const t9=k=>(window.WK2P&&WK2P('slr9',k))??(T[L()]||T.en)[k]??T.en[k]??k;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hap=()=>{try{navigator.vibrate&&navigator.vibrate(8)}catch(e){}};
const K=()=>(window.SLR3&&SLR3.k)||null;
const S=(d,w)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${w||1.9}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const IC={pip:'<rect x="3" y="5" width="18" height="14" rx="3"/><rect x="12" y="11.5" width="6.5" height="5" rx="1.4" fill="currentColor" stroke="none"/>',
 exit:'<path d="M14 4h4.5A1.5 1.5 0 0 1 20 5.5v13a1.5 1.5 0 0 1-1.5 1.5H14"/><path d="M10 8l-4 4 4 4M6 12h10"/>',
 expand:'<path d="M14 4h6v6M10 20H4v-6M20 4l-6.5 6.5M4 20l6.5-6.5"/>',x:'<path d="M6 6l12 12M18 6 6 18"/>',
 mic:'<rect x="9" y="3.5" width="6" height="11" rx="3"/><path d="M5.5 11.5a6.5 6.5 0 0 0 13 0M12 18v2.5"/>',
 shrink:'<rect x="3.5" y="4.5" width="17" height="15" rx="3.5" stroke-opacity=".55"/><rect x="11.5" y="11.5" width="6.5" height="5.5" rx="1.6" fill="currentColor" stroke="none"/><path d="M7 8l3.6 3.6M10.8 8.6v3.2H7.6"/>',
 door:'<path d="M13.5 3.5h4A1.5 1.5 0 0 1 19 5v14a1.5 1.5 0 0 1-1.5 1.5h-4"/><path d="M13.5 3.5 6.5 5.2A1.5 1.5 0 0 0 5.4 6.7v10.6a1.5 1.5 0 0 0 1.1 1.5l7 1.7z"/><circle cx="11" cy="12" r="1" fill="currentColor" stroke="none"/>',
