/* ---------- exit menu: a clear-glass drop falls out of the exit button with two icon orbs (no words) */
function exitMenu(){const k=K();if(!k)return;const r=k.root();if(!r)return;const btn=r.querySelector('[data-a=exit]');
 document.querySelectorAll('.s9-pop').forEach(x=>x.remove());
