 w.innerHTML=`<div class="s9-dr" role="menu"><i class="s9-nk"></i><button class="s9-o" data-m="min" role="menuitem" aria-label="${esc(t9('min'))}" title="${esc(t9('min'))}">${S(IC.shrink,1.9)}</button><button class="s9-o s9-dg" data-m="leave" role="menuitem" aria-label="${esc(t9('leave'))}" title="${esc(t9('leave'))}">${S(IC.door,1.9)}</button></div>`;
 document.body.appendChild(w);const dr=w.querySelector('.s9-dr');
 if(btn){const b=btn.getBoundingClientRect();dr.style.top=(b.bottom+10)+'px';dr.style.left=(b.left+b.width/2-29)+'px';btn.classList.add('r-open')}
