 w.addEventListener('click',e=>{const b=e.target.closest('[data-m]');if(!b)return done();hap();b.classList.add('s9-hit');setTimeout(()=>{done();if(b.dataset.m==='min')minimize();else leaveNow()},160)})}

/* ---------- leave completely: frees the seat and presence, back to the salon list */
function leaveNow(){closeCard(true);try{exitRoom()}catch(e){try{const c=K()&&K().cid();if(c)api('/api/c/'+c,{a:'leave'}).catch(()=>{})}catch(_){}}}

/* ---------- minimise: keep seat, voice and presence, go home, show the floating card */
function minimize(then){const k=K();if(!k)return;const code=k.cid();if(!code)return;
 M.code=code;M.info=Object.assign({},k.room());
 const vl=window.vcLeave;try{window.vcLeave=function(){} ;go('h')}catch(e){}finally{window.vcLeave=vl}
 try{if(typeof CID!=='undefined'&&!CID){CID=code}}catch(e){}
 dropRoom();showCard();if(typeof then==='function')setTimeout(then,60)}

/* the room page itself is not needed while minimised (it is drawn again on return) */
function dropRoom(){try{if(TAB==='c')return;const r=document.querySelector('#view .slr');if(!r)return;const pane=r.closest('[data-wk-page]');if(pane)pane.innerHTML='';else r.remove();document.body.classList.remove('slr-on')}catch(e){}}
function micOn(){try{return !!(VC.on&&!VC.mute)}catch(e){return false}}
function seated(){try{return typeof CS!=='undefined'&&CS&&CS.mine>=0}catch(e){return false}}
function cardHTML(){const i=M.info||{};
 return `<div class="s9-in"><div class="s9-f"><div class="s9-v" data-c="open" aria-label="${esc(t9('back'))}" role="button">
   <div class="s9-po" style="background-image:url('${esc(poster())}')"></div><div id="s9-yt"></div><i class="s9-sh"></i><i class="s9-gl"></i>
   <span class="s9-lv1"><i></i></span>
   <span class="s9-nm">${i.photo?`<img src="${esc(i.photo)}" alt="">`:''}<b><bdi>${esc(i.name||'')}</bdi></b></span>
   <span class="s9-pr"><i></i></span></div><i class="s9-ring"></i></div>
  <div class="s9-bk" aria-label="${esc(t9('sure'))}" role="group"><div class="s9-bg" style="background-image:url('${esc(poster())}')"></div>
   <button class="s9-lv" data-c="yes" aria-label="${esc(t9('leave'))}"><i class="s9-rg"></i><i class="s9-rg s9-rg2"></i>${S(IC.door,1.9)}</button>
   <button class="s9-un" data-c="no" aria-label="${esc(t9('cancel'))}">${S(IC.undo,2)}</button></div></div>
  <button class="s9-sat s9-x" data-c="x" aria-label="${esc(t9('leave'))}">${S(IC.x,2.4)}</button>
  <button class="s9-sat s9-mic${micOn()?' on':''}" data-c="mic" aria-label="${esc(t9('mic'))}" ${seated()?'':'hidden'}>${S(micOn()?IC.mic:IC.micOff,2)}</button>
  <div class="s9-spk" aria-hidden="true"></div>`}
function poster(){try{if(CS&&CS.vid&&/^[\w-]{11}$/.test(CS.vid))return 'https://i.ytimg.com/vi/'+CS.vid+'/hqdefault.jpg'}catch(e){}return (M.info&&M.info.bg)||'/s/wk2/salon/pamir.jpg'}
function exp(){try{return cExp()}catch(e){return 0}}
function showCard(){if(M.card)return paint();const c=document.createElement('div');c.className='s9-card';c.dir=RTL()?'rtl':'ltr';c.innerHTML=cardHTML();document.body.appendChild(c);M.card=c;document.body.classList.add('slr9-min');
 let p=null;try{p=JSON.parse(localStorage.getItem('slr9_pos')||'null')}catch(e){}place(p||{side:RTL()?'l':'r',y:innerHeight-300});
 requestAnimationFrame(()=>c.classList.add('in'));bindDrag(c);startYT();
 clearInterval(M.iv);M.iv=setInterval(tick,1000);clearInterval(M.poll);M.poll=setInterval(keep,5000)}
function place(p){const c=M.card;if(!c)return;const W=c.offsetWidth||184,H=c.offsetHeight||150;const top=Math.max(70,Math.min(innerHeight-H-96,p.y));
 c.style.top=top+'px';c.style.left=(p.side==='l'?12:innerWidth-W-12)+'px';M.pos={side:p.side,y:top};try{localStorage.setItem('slr9_pos',JSON.stringify(M.pos))}catch(e){}}
function paint(){const c=M.card;if(!c)return;const m=c.querySelector('.s9-mic');if(m){const on=micOn();m.hidden=!seated();m.classList.toggle('on',on);if(m.dataset.on!==String(on)){m.dataset.on=String(on);m.innerHTML=S(on?IC.mic:IC.micOff,2)}}tick()}
/* who is talking: their faces pop up above the card (at most 3) */
function speakers(){const c=M.card;if(!c)return;const box=c.querySelector('.s9-spk');if(!box)return;let ids=[];try{ids=Object.entries(VC.spk||{}).filter(([u,v])=>v).map(([u])=>Number(u)).slice(0,3)}catch(e){}
 const key=ids.join(',');if(box.dataset.k===key)return;box.dataset.k=key;const k=K();
 box.innerHTML=ids.map((u,i)=>{let p=null;try{p=(CS.seats||[]).find(x=>x&&Number(x.id)===u)||(k&&k.personOf&&k.personOf(u))}catch(e){}return `<span style="--i:${i}">${k&&p?k.ava(p):''}</span>`}).join('')}
function tick(){const c=M.card;if(!c)return;let d=0;try{d=M.yt&&M.yt.getDuration?M.yt.getDuration():0}catch(e){}const t=exp();const pr=c.querySelector('.s9-pr i');if(pr)pr.style.width=(d?Math.min(100,t/d*100):0)+'%';
