/* ---------------------------------------------------------------- 12 staying in the hall while browsing */
/* Leaving the hall page (seated) keeps the seat and the voice; a bubble brings you back. */
function quietly(fn){const vl=vcLeave,ap=api,tok=(typeof CG!=='undefined')?CG.token:null;
 vcLeave=function(){};
 api=function(p,b){if(typeof p==='string'){if(b&&b.a==='leave'&&p.indexOf('/api/c')===0)return Promise.resolve({ok:true})}return ap.apply(this,arguments)};
 try{return fn()}finally{vcLeave=vl;api=ap;try{if(tok&&typeof CG!=='undefined'&&!CG.token)CG.token=tok}catch(e){}}}
function minimize(k,sub,realGo){const code=CID,keepCS=CS;
 const r=quietly(()=>realGo(k,sub));
 try{if(!CID){CID=code;CS=keepCS}}catch(e){}
 S.min=true;S.minRoom=code;S.miss=0;keepAlive();bubble();document.body.classList.remove('h2-open','wm78-room-open','wmc-hall-active');try{tg.enableVerticalSwipes&&tg.enableVerticalSwipes()}catch(e){}
 return r}
function keepAlive(){
 clearInterval(S.ka);if(S.keepJob?.online)window.removeEventListener?.('online',S.keepJob.online);
 const job={room:S.minRoom,busy:false,failures:0,next:0};S.keepJob=job;
 const owns=()=>S.keepJob===job&&S.min&&CID===job.room&&S.minRoom===job.room;
 const paint=()=>{paintBubble();const b=S.bub?.querySelector('.h2-bmain');if(b){b.classList.toggle('is-reconnecting',!!S.connectionLost);if(S.connectionLost)b.title=LG==='en'?'Reconnecting…':LG==='ps'?'بیا نښلېږي…':'در حال اتصال دوباره…';else b.removeAttribute('title')}};
 const tick=async()=>{
  if(!owns())return;
  if(job.busy||Date.now()<job.next)return;
  job.busy=true;
  try{
   const j=await api('/api/c/'+job.room+'?v=0');if(!owns())return;
   if(j&&j.ok){job.failures=0;job.next=0;S.connectionLost=false;j._cid=job.room;CS=j;try{CVER=j.ver}catch(e){}
    // Only an authoritative response can report that this seat was lost.
    if(j.mine<0){say(tx('lost'));return fullLeave(false)}
   }else{job.failures++;S.connectionLost=true;job.next=Date.now()+Math.min(2000*2**Math.min(job.failures,3),15000)}
  }catch(e){if(!owns())return;job.failures++;S.connectionLost=true;job.next=Date.now()+Math.min(2000*2**Math.min(job.failures,3),15000)}
  finally{job.busy=false;if(owns())paint()}
 };
 job.online=()=>{if(owns()){job.next=0;tick()}};window.addEventListener?.('online',job.online);
 S.ka=setInterval(tick,3000);S.keepTick=tick;
}
function finishMin(){S.min=false;clearInterval(S.ka);S.ka=0;if(S.keepJob?.online)window.removeEventListener?.('online',S.keepJob.online);S.keepJob=null;S.keepTick=null;S.connectionLost=false;if(S.bub){S.bub.remove();S.bub=null}}
function fullLeave(tell){const code=S.minRoom||CID;finishMin();try{vcLeave()}catch(e){}
 if(code&&tell!==false){try{api('/api/c/'+code,{a:'leave'}).catch(()=>{})}catch(e){}}
 try{CID=null;CS=null;CVER=0;CV='hall'}catch(e){}S.room='';try{wmrDockUpdate()}catch(e){}}
function restore(sub,realGo){finishMin();try{CV='hall';CLOG=true}catch(e){}return quietly(()=>realGo('c',sub))}
function bubble(){if(S.bub)return paintBubble();const b=document.createElement('div');b.id='h2-bub';b.dir='ltr';
 b.innerHTML=`<button type="button" class="h2-bmain" aria-label="${esc(tx('backHall'))}"><span class="h2-bring"></span><span class="h2-bic">${ic('cinema')}</span><b class="h2-bn"></b></button><button type="button" class="h2-bmic"></button><button type="button" class="h2-bx" aria-label="${esc(tx('leave'))}">${ic('close')}</button>`;
 b.querySelector('.h2-bmain').onclick=()=>{vib();go('c')};
 b.querySelector('.h2-bmic').onclick=async e=>{e.stopPropagation();vib();try{await vcMute()}catch(_){}paintBubble()};
 b.querySelector('.h2-bx').onclick=e=>{e.stopPropagation();vib();ask(tx('sure'),()=>fullLeave(true))};
