 if(WM70.hall!==CID){WM70.hall=CID;WM70.hallMessages=[];WM70.hallCursor=0;++WM70.hallSeq;WM70.hallBusy=false;WM70.roomPending=null;S.base=null;S.peopleRef=WM70.hallPeople;S.mountAt=Date.now()}
