(()=>{const s=document.createElement('style');s.id='h2-css';s.textContent="/* =====================================================================\n   WAKHAN HALL v2 — styles. Everything is scoped to .h2 (the hall) or\n   to sheets the hall opens (.h2-*). Glass over the hall background.\n   1 page   2 top bar   3 stage   4 seats   5 chat   6 footer\n   7 search panel   8 sheets   9 settings   10 bubble\n   ===================================================================== */\n\n/* ---------- 1 page */\nhtml:has(body.h2-open),body.h2-open{overflow:hidden!important;overscroll-behavior:none}\nbody.h2-open #view{padding:0!important}\nbody #view > [data-wk-page-active] #wm78-room.h2{\n --h2-acc:var(--a1,#10b981);--h2-glass:rgba(255,255,255,.1);--h2-line:rgba(255,255,255,.14);--h2-dim:rgba(255,255,255,.62);\n position:fixed;left:0;right:0;top:0;z-index:30;height:var(--h2-h,100dvh);max-width:760px;margin:0 auto;padding:0!important;\n display:flex;flex-direction:column;overflow:hidden;color:#fff;\n font-family:Vazirmatn,system-ui,-apple-system,sans-serif;-webkit-tap-highlight-color:transparent;\n background:radial-gradient(120% 65% at 50% 0%,color-mix(in srgb,var(--h2-acc) 34%,#141a2c) 0%,#0c1020 55%,#06070d 100%)}\n#wm78-room.h2 button{font-family:inherit;-webkit-user-select:none;user-select:none;touch-action:manipulation}\n#wm78-room.h2 .h2-i,#wm78-room.h2 svg.wi{width:22px;height:22px;display:block;flex:none}\n#wm78-room.h2[data-bg=night]{background:radial-gradient(ellipse at 50% 0%,#24305e 0%,#0b1024 60%,#05060f 100%)}\n#wm78-room.h2[data-bg=aurora]{background:linear-gradient(160deg,#0b3b3a 0%,#123a5c 45%,#2a1450 100%)}\n#wm78-room.h2[data-bg=sunset]{background:linear-gradient(170deg,#4a1d3f 0%,#7a2e2e 45%,#1d0f1f 100%)}\n#wm78-room.h2[data-bg=ocean]{background:linear-gradient(180deg,#06324a 0%,#0a1f3d 55%,#050b1a 100%)}\n#wm78-room.h2[data-bg=forest]{background:linear-gradient(180deg,#123d27 0%,#0b2418 55%,#050e09 100%)}\n#wm78-room.h2[data-bg=royal]{background:radial-gradient(ellipse at 50% 10%,#2c3fd6 0%,#141f7a 45%,#070b2e 100%)}\n#wm78-room.h2[data-bg=rose]{background:linear-gradient(170deg,#5a1f45 0%,#3a1238 50%,#140611 100%)}\n#wm78-room.h2.has-photo{background:linear-gradient(180deg,rgba(0,0,0,.5) 0%,rgba(0,0,0,.15) 30%,rgba(0,0,0,.25) 62%,rgba(0,0,0,.78) 100%),var(--h2-photo) center/cover no-repeat}\n\n/* ---------- 2 top bar */\n.h2-top{flex:none;display:flex;align-items:center;gap:8px;padding:calc(8px + env(safe-area-inset-top,0px)) 10px 6px;direction:ltr}\n.h2-btn{flex:none;width:38px;height:38px;border-radius:50%;border:0;padding:0;display:grid;place-items:center;color:#fff;background:var(--h2-glass);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}\n.h2-id{min-width:0;max-width:56%;display:flex;align-items:center;gap:8px;height:42px;padding:3px 12px 3px 3px;border-radius:21px;border:0;color:#fff;background:rgba(0,0,0,.28);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);text-align:start}\n.h2-cov{flex:none;width:36px;height:36px;border-radius:12px;overflow:hidden;display:grid;place-items:center;background:linear-gradient(135deg,var(--h2-acc),color-mix(in srgb,var(--h2-acc) 45%,#000))}\n.h2-cov img{width:100%;height:100%;object-fit:cover}.h2-cov i{font:900 16px/1 inherit;font-style:normal}\n.h2-nm{min-width:0;display:flex;flex-direction:column;line-height:1.25}\n.h2-nm b{font-size:14px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.h2-nm small{display:flex;align-items:center;gap:4px;min-width:0;font-size:11px;font-weight:700;color:rgba(255,255,255,.82)}\n.h2-nm small .h2-i,.h2-nm small svg{width:13px!important;height:13px!important;color:#f5c451}\n.h2-nm small span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.h2-fill{flex:1}\n.h2-ppl{flex:none;display:flex;align-items:center;height:32px;padding:0 4px 0 4px;border:0;border-radius:16px;background:rgba(0,0,0,.28);color:#fff}\n.h2-ppl>span{width:24px;height:24px;margin-left:-8px;border-radius:50%;overflow:hidden;box-shadow:0 0 0 1.5px #10131f}.h2-ppl>span:first-child{margin-left:0}\n.h2-ppl em{font:800 12px/1 inherit;font-style:normal;padding:0 6px 0 5px}\n.h2-mini{width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;background:rgba(255,255,255,.08)}\n\n/* ---------- 3 stage */\n#wm78-room.h2 .h2-stage{flex:none;position:relative;margin:2px 10px 4px;border-radius:16px;overflow:hidden;background:#04060a;border:1px solid var(--h2-line)}\n#wm78-room.h2 .h2-stage .screen{min-height:0;height:auto;position:relative;width:100%;aspect-ratio:16/9;max-height:calc(var(--h2-h,100dvh) * .32);margin:0 auto;overflow:hidden;background:#04060a}\n#wm78-room.h2 .h2-stage .screen>video,#wm78-room.h2 .h2-stage .screen>iframe,#wm78-room.h2 .h2-stage #yt{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}\n#wm78-room.h2 .h2-stage .wmc-stage-toolbar{padding:2px 6px;min-height:36px}\n#wm78-room.h2 .h2-stage .wmc-controls button,#wm78-room.h2 .h2-stage .wmc-view-controls button{height:34px;min-height:34px;width:34px;padding:7px}\n#wm78-room.h2 .h2-stage #vbarw{display:none!important}\nbody.wmc-theater #wm78-room.h2 #wmc-stage.wmc-expanded{position:fixed;inset:0;margin:0;border:0;border-radius:0;z-index:50}\nbody.wmc-theater #wm78-room.h2 #wmc-stage.wmc-expanded .screen{width:100%;height:100%;max-height:none;aspect-ratio:auto}\n.h2-title{flex:none;margin:0 14px 2px;font-size:12px;font-weight:700;color:var(--h2-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}\n.h2-title:empty{display:none}\n\n/* ---------- 4 seats: 2 on top, then 4 + 4 */\n.h2-seats{flex:none;display:grid;grid-template-columns:repeat(4,1fr);gap:10px 6px;padding:6px 14px 4px}\n.h2-seat:nth-child(1){grid-column:2}.h2-seat:nth-child(2){grid-column:3}.h2-seat:nth-child(3){grid-column:1}\n.h2-seat{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;min-width:0;padding:0;border:0;background:none;color:#fff;cursor:pointer}\n.h2-seat,.h2-seat *{transition:none!important;animation:none}\n.h2-face{position:relative;width:52px;height:52px;border-radius:50%;display:grid;place-items:center}\n.h2-av{position:absolute;inset:0;display:grid;place-items:center;border-radius:50%}\n.h2-av>.wm70-avatar,.h2-av>span{width:100%!important;height:100%!important;font-size:inherit}\n.h2-seat.is-empty .h2-av{background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.18);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);color:rgba(255,255,255,.75)}\n.h2-seat.is-empty .h2-av .h2-i,.h2-seat.is-empty .h2-av svg{width:20px;height:20px}\n.h2-seat.is-locked .h2-av{color:#fb7185;border-color:rgba(251,113,133,.45);background:rgba(251,113,133,.12)}\n.h2-mic{position:absolute;right:-2px;bottom:-2px;z-index:6;width:19px;height:19px;border-radius:50%;display:grid;place-items:center;background:#22c55e;color:#fff;box-shadow:0 0 0 2px rgba(10,12,20,.85);font-style:normal}\n.h2-mic:empty{display:none}.h2-mic .h2-i,.h2-mic svg{width:11px!important;height:11px!important}\n.h2-seat.is-muted .h2-mic{background:#1e2230;color:#fb7185}\n.h2-name{max-width:100%;font-size:11px;font-weight:700;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 1px 3px rgba(0,0,0,.85)}\n.h2-seat.is-empty .h2-name{color:var(--h2-dim);font-weight:600}\n.h2-seat.is-me .h2-av{box-shadow:0 0 0 2px var(--h2-acc)}\n.h2-seat.is-host .h2-name{color:#ffd76a}\n.h2-seat.is-speaking .h2-face::after{content:\"\";position:absolute;inset:-5px;border-radius:50%;border:2px solid var(--h2-acc);animation:h2talk 1.1s ease-out infinite!important;pointer-events:none}\n@keyframes h2talk{0%{transform:scale(.92);opacity:.95}100%{transform:scale(1.18);opacity:0}}\n/* nothing playing: seats go to the top and get bigger */\n.h2.is-idle .h2-seats{gap:18px 6px;padding-top:14px}\n.h2.is-idle .h2-face{width:66px;height:66px}\n.h2.is-idle .h2-seat.is-empty .h2-av .h2-i,.h2.is-idle .h2-seat.is-empty .h2-av svg{width:24px;height:24px}\n.h2.is-idle .h2-name{font-size:12px}\n.h2.is-idle .h2-mic{width:22px;height:22px}\n.h2-pick{flex:none;display:flex;justify-content:center;padding:8px 0 2px}\n.h2-pick[hidden]{display:none}\n.h2-pick button{display:inline-flex;align-items:center;gap:8px;height:40px;padding:0 20px;border:0;border-radius:20px;color:#fff;font:800 13.5px inherit;background:linear-gradient(135deg,var(--h2-acc),color-mix(in srgb,var(--h2-acc) 55%,#000));box-shadow:0 8px 22px color-mix(in srgb,var(--h2-acc) 30%,transparent)}\n.h2-pick .h2-i,.h2-pick svg{width:18px!important;height:18px!important}\n\n/* ---------- 5 chat (between the seats and the footer — never on top of the seats) */\n.h2-chat{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;padding:4px 12px 0}\n.h2-notice{flex:none;display:flex;align-items:flex-start;gap:8px;margin:2px 0 6px;padding:7px 10px;border-radius:14px;background:rgba(0,0,0,.32);border:1px solid color-mix(in srgb,var(--h2-acc) 35%,transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}\n.h2-notice[hidden]{display:none}\n.h2-ni{flex:none;color:var(--h2-acc)}.h2-ni .h2-i{width:19px;height:19px}\n.h2-notice p{flex:1;margin:1px 0 0;font-size:12.5px;line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;white-space:pre-wrap;word-break:break-word}\n.h2-notice p i{color:var(--h2-dim);font-style:normal}\n.h2-notice button{flex:none;width:28px;height:28px;border:0;border-radius:50%;padding:0;display:grid;place-items:center;background:rgba(255,255,255,.12);color:#fff}\n.h2-notice button .h2-i,.h2-notice button svg{width:14px;height:14px}\nbody #view > [data-wk-page-active] #wm78-room.h2 .h2-msgs{flex:1 1 auto;min-height:0;max-height:none;display:flex;flex-direction:column;gap:7px;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding:14px 0 8px;\n -webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 22px);mask-image:linear-gradient(to bottom,transparent 0,#000 22px);scrollbar-width:none}\n.h2-msgs::-webkit-scrollbar{display:none}\n.h2-msgs>:first-child{margin-top:auto}\n.h2-msg{display:flex;align-items:flex-start;gap:8px;max-width:88%}\n.h2-mav{flex:none;width:30px;height:30px;padding:0;border:0;border-radius:50%;background:none;box-shadow:0 0 0 1.5px rgba(255,255,255,.22)}\n.h2-mb{min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:2px}\n.h2-mname{padding:0;border:0;background:none;color:color-mix(in srgb,var(--h2-acc) 55%,#fff);font:800 11.5px/1.3 inherit;text-shadow:0 1px 3px rgba(0,0,0,.9);max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.h2-msg.is-own .h2-mname{color:#ffd76a}\n.h2-mb p{margin:0;padding:6px 11px;border-radius:4px 14px 14px 14px;background:rgba(0,0,0,.34);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);font-size:14px;font-weight:600;line-height:1.55;white-space:pre-wrap;word-break:break-word;overflow-wrap:anywhere}\n[dir=rtl] .h2-mb p,html[dir=rtl] .h2-mb p{border-radius:14px 4px 14px 14px}\n.h2-msg.is-pending{opacity:.55}\n.h2-giftline{display:flex;align-items:center;gap:8px;padding:5px 10px;border-radius:14px;background:linear-gradient(135deg,rgba(255,196,81,.25),rgba(255,120,80,.18));font-size:12.5px;font-weight:800}\n.h2-giftline img,.h2-giftline svg,.h2-giftline>*:first-child{width:34px;height:34px;flex:none}\n.h2-sys{align-self:flex-start;display:inline-flex;align-items:center;gap:6px;max-width:92%;padding:4px 10px;border-radius:12px;background:rgba(255,255,255,.1);font-size:12px;line-height:1.5;color:rgba(255,255,255,.85)}\n.h2-sys .h2-i,.h2-sys svg{width:14px!important;height:14px!important;opacity:.8}\n.h2-sys b{font-weight:800}\n.h2-sys.welcome{background:color-mix(in srgb,var(--h2-acc) 22%,rgba(0,0,0,.25));color:#fff}\n.h2-hint{margin:auto 0 6px;align-self:center;padding:7px 14px;border-radius:14px;background:rgba(0,0,0,.3);font-size:12.5px;color:var(--h2-dim)}\n\n/* ---------- 6 footer */\n.h2-foot{flex:none;position:relative;padding:6px 10px calc(8px + env(safe-area-inset-bottom,0px))}\n.h2-bar{display:flex;align-items:center;gap:7px;direction:ltr}\n.h2-rb{position:relative;flex:none;width:40px;height:40px;padding:0;border:0;border-radius:50%;display:grid;place-items:center;color:#fff;background:var(--h2-glass);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px)}\n.h2-rb:disabled{opacity:.45}\n#wm78-mic{color:#fb7185}#wm78-mic.is-on{color:#fff;background:linear-gradient(135deg,#22c55e,#15803d)}\n#wm78-speaker.is-off{color:#fb7185}\n.h2-gold{background:linear-gradient(135deg,#ffcf5c,#ff8a3d)!important;color:#3a1d00!important}\n.h2-dot{position:absolute;top:6px;right:7px;width:8px;height:8px;border-radius:50%;background:#ff4d6d;box-shadow:0 0 0 2px rgba(10,12,20,.9)}\n.h2-dot[hidden]{display:none}\n.h2-say{flex:1;min-width:0;height:40px;padding:0 14px;border:0;border-radius:20px;background:var(--h2-glass);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);color:rgba(255,255,255,.72);font:600 13.5px inherit;text-align:start;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;direction:rtl}\nhtml[lang^=en] .h2-say{direction:ltr}\n.h2-compose{position:absolute;left:10px;right:10px;bottom:calc(8px + env(safe-area-inset-bottom,0px));display:flex;align-items:center;gap:7px;opacity:0;pointer-events:none;direction:ltr}\n.h2-compose input{flex:1;min-width:0;height:42px;padding:0 15px;border-radius:21px;border:1px solid var(--h2-line);background:rgba(255,255,255,.12);color:#fff;font:500 16px inherit;outline:0;-webkit-appearance:none;appearance:none}\n.h2-compose input::placeholder{color:rgba(255,255,255,.55)}\n.h2-send{flex:none;width:42px;height:42px;border:0;border-radius:50%;padding:0;display:grid;place-items:center;color:#fff;background:var(--h2-acc)}\n.h2-send:disabled{opacity:.5}\n/* typing: the bar turns into the text box, right on the keyboard; seats stay, chat shrinks */\n.h2.is-legacy-typing .h2-bar{visibility:hidden}\n.h2.is-legacy-typing .h2-compose{opacity:1;p