 if(!peer||!input)return;
 S.drafts.set(peer,{text:input.value,reply:S.replies.get(peer)||null,scroll:$('wm70-dm-messages')?.scrollTop||0});
 while(S.drafts.size>50)S.drafts.delete(S.drafts.keys().next().value);
