 for(const key of [...media.keys()]){
  if(media.size<=24)break;
  if(key===id||key===S.playingId)continue;
  const previous=media.get(key);media.delete(key);Promise.resolve(previous).then(url=>URL.revokeObjectURL(url)).catch(()=>{});
 }
 return promise;
}
