const scope=()=>{const key=JSON.stringify([VC.cid,VC.tok]);if(R.context!==key){R.context=key;R.fix={};R.miss={}}};
const note=m=>{R.log.push(Date.now()+' '+m);if(R.log.length>40)R.log.shift()};
