  if(r&&r.ok&&!r.again){for(const id of Object.keys(VC.pcs)){try{VC.pcs[id].pc.close()}catch(e){}delete VC.pcs[id]}R.fix={};
   if(!VC.mute)await api('/api/cv/'+cid,{a:'mute',m:0});if(current(c))vcSync()}
 }catch(e){}finally{if(R.rejoining===c)R.rejoining=null}}

vcLoop=async function(){const tok=++VC.tok;let miss=0;
