 /* we are the higher id and have no link to someone: ask them to call us */
 const me=myId(),now=Date.now();R.miss=R.miss||{};
 for(const m of VC.members||[]){const id=Number(m.id);if(id>=me||VC.pcs[id]){delete R.miss[id];continue}
