(()=>{'use strict';
 if(typeof WKV2==='undefined'||typeof WMQ==='undefined'||typeof WMC==='undefined'||WKV2.lifecycle)return;
 const R=WKV2;R.lifecycle=true;R.joinJob=null;
 const leave=vcLeave;
