 vcJoin=function(){
  const cid=CID,epoch=WMC.epoch;
  if(!CS||CS.mine<0){toast(t('only_seated'));return Promise.resolve()}
  if(R.joinJob&&R.joinJob.cid===cid&&R.joinJob.epoch===epoch&&R.joinJob.token===WMQ.token)return R.joinJob.promise;
  if(VC.on&&VC.cid===cid)return Promise.resolve();
