/* ---- report sheet */
function report(o){o=o||{};const user=!!o.uid;let pick='';
 const draw=()=>{try{sheet(`<section class="wks" dir="${dir()}"><h3>${esc(t(user?'reportUser':'reportHall'))}${o.name?` · <bdi>${esc(o.name)}</bdi>`:''}</h3><p class="wks-sub">${esc(t('why'))}</p>
  <div class="wks-reasons">${REASONS.map(r=>`<button type="button" data-r="${r}" class="${pick===r?'on':''}">${esc(t('r_'+r))}</button>`).join('')}</div>
  <textarea id="wks-note" maxlength="500" rows="2" placeholder="${esc(t('note'))}" dir="auto"></textarea>
  ${user?`<label class="wks-check"><input type="checkbox" id="wks-block"><span>${esc(t('alsoBlock'))}</span></label>`:''}
  <button type="button" class="wks-send" ${pick?'':'disabled'}>${esc(t('send'))}</button></section>`)}catch(e){return}
  const root=document.querySelector('.wks');if(!root)return;
  root.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{pick=b.dataset.r;root.querySelectorAll('[data-r]').forEach(x=>x.classList.toggle('on',x===b));root.querySelector('.wks-send').disabled=false});
  root.querySelector('.wks-send').onclick=async e=>{e.target.disabled=true;const blk=user&&root.querySelector('#wks-block')?.checked;
   const r=await call('/api/app/report',{uid:o.uid||0,hall:o.hall||'',reason:pick,note:root.querySelector('#wks-note').value,block:!!blk});
   if(!r||!r.ok){e.target.disabled=false;return say(t('err'))}
   try{closeSheet()}catch(x){}say(t('thanks'));
   if(blk){try{WM70.people.get(Number(o.uid))&&(WM70.people.get(Number(o.uid)).relation='blocked')}catch(x){}}}};
 draw()}

/* ---- delete account (Wakhan app only) */
async function del(after){const me=await call('/api/app/me');const un=(me&&me.username)||'';
 try{sheet(`<section class="wks" dir="${dir()}"><h3>${esc(t('delTitle'))}</h3><p class="wks-sub">${esc(t('delText'))}</p>
  ${un?`<p class="wks-sub"><b>${esc(t('delType'))}</b></p><input id="wks-un" dir="ltr" autocapitalize="off" autocomplete="off" spellcheck="false" placeholder="@${esc(un)}">`:''}
  <div class="wks-row"><button type="button" class="wks-cancel">${esc(t('cancel'))}</button><button type="button" class="wks-danger" ${un?'disabled':''}>${esc(t('delBtn'))}</button></div></section>`)}catch(e){return}
 const root=document.querySelector('.wks'),go=root.querySelector('.wks-danger'),inp=root.querySelector('#wks-un');
 root.querySelector('.wks-cancel').onclick=()=>{try{closeSheet()}catch(e){}};
 if(inp)inp.oninput=()=>{go.disabled=inp.value.trim().replace(/^@/,'').toLowerCase()!==un.toLowerCase()};
 go.onclick=async()=>{go.disabled=true;const r=await call('/api/app/delete',{confirm:inp?inp.value:''});if(!r||!r.ok){go.disabled=false;return say(t('err'))}
  try{closeSheet()}catch(e){}say(t('deleted'));setTimeout(()=>{try{after&&after()}catch(e){}},900)}}
function deleteLink(after){const b=document.createElement('button');b.type='button';b.className='wks-del';b.textContent=t('delAcc');b.onclick=()=>del(after);return b}
function legalLinks(open){const d=document.createElement('div');d.className='wks-legal';d.dir=dir();
 d.innerHTML=`<a href="https://music.kabulcafe.uk/terms?lang=${lang()}" target="_blank" rel="noopener">${esc(t('terms'))}</a> · <a href="https://music.kabulcafe.uk/privacy?lang=${lang()}" target="_blank" rel="noopener">${esc(t('privacy'))}</a>`;
 if(open)d.querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();open(a.href)});return d}

