function hook(){if(typeof wm70ProfileDraw!=='function')return false;if(wm70ProfileDraw.__wks)return true;
 const od=wm70ProfileDraw;const nd=function(p){const r=od.apply(this,arguments);try{
  if(p&&Number(p.id)!==Number(ME.me.id)){const box=document.querySelector('.wm70-public-profile');if(box&&!box.querySelector('.wks-prow')){
   const row=document.createElement('div');row.className='wks-prow';const blocked=p.relation==='blocked'&&p.blocked_by_me;
   row.innerHTML=`<button type="button" data-a="rep">${FLAG}<span>${esc(t('report'))}</span></button>${blocked?'':`<button type="button" data-a="blk"><span>${esc(t('block'))}</span></button>`}`;
   row.querySelector('[data-a=rep]').onclick=()=>report({uid:Number(p.id),name:p.name});
   const bb=row.querySelector('[data-a=blk]');if(bb)bb.onclick=()=>{try{wm70Friend('block',Number(p.id))}catch(e){}};
   box.appendChild(row)}}}catch(e){}return r};nd.__wks=1;wm70ProfileDraw=nd;
 if(typeof wm70PeerMenu==='function'&&!wm70PeerMenu.__wks){const om=wm70PeerMenu;const nm=function(uid){const r=om.apply(this,arguments);try{
  const list=document.querySelector('.wn-sheet-list');if(list&&!list.querySelector('.wks-mrep')){const b=document.createElement('button');b.className='wks-mrep';b.textContent=t('report');
   const p=(WM70.people&&WM70.people.get(Number(uid)))||{};b.onclick=()=>report({uid:Number(uid),name:p.name});list.appendChild(b)}}catch(e){}return r};nm.__wks=1;wm70PeerMenu=nm}
 if(typeof window.wp30More==='function'&&!window.wp30More.__wks){const ow=window.wp30More;const nw=function(id){const r=ow.apply(this,arguments);try{
  const blk=document.querySelector('button[onclick*="wm70Friend(\'block\'"],button[onclick*="wm70Friend(\'unblock\'"]');
  if(blk&&!blk.parentNode.querySelector('.wks-mrep')){const b=document.createElement('button');b.type='button';b.className='danger wks-mrep';b.innerHTML=FLAG+'<span>'+esc(t('report'))+'</span>';
   const p=(WM70.people&&WM70.people.get(Number(id)))||{};b.onclick=()=>{try{closeSheet()}catch(e){}setTimeout(()=>report({uid:Number(id),name:p.name}),180)};blk.after(b)}}catch(e){}return r};nw.__wks=1;window.wp30More=nw}
 return true}
if(!hook()){const iv=setInterval(()=>{if(hook())clearInterval(iv)},800)}

