 const icon=key=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${({back:'<path d="m14 6-6 6 6 6"/>',coins:'<circle cx="12" cy="12" r="9"/><path d="m7 9 2 7 3-5 3 5 2-7"/>',transfer:'<path d="M4 8h16m-4-4 4 4-4 4M20 16H4m4-4-4 4 4 4"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 5v6h6m3-5v6l4 2"/>',subscription:'<path d="m3 8 5-4h8l5 4-9 13Zm0 0h18M8 4l4 17 4-17"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'})[key]||'<circle cx="12" cy="12" r="9"/>'}</svg>`;
 const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
 const call=async(path,body)=>{const value=await api(path,body);if(!value?.ok)throw Error(value?.err||'request_failed');return value};
 const money=(amount,currency)=>{try{return new Intl.NumberFormat(document.documentElement.lang,{style:'currency',currency}).format(amount/100)}catch{return (amount/100).toFixed(2)+' '+currency}};
 const number=value=>Number(value||0).toLocaleString(document.documentElement.lang,{maximumFractionDigits:2});
 const billCountry=()=>{try{return localStorage.getItem('wk_billing_country')||window.WakhanBillingCountry||'US'}catch{return 'US'}};
 let current=null,currentState=null;
 function close(){current?.close()}
 function shell(kind){
  close();document.activeElement?.blur();const dialog=document.createElement('dialog');dialog.id=kind==='wallet'?'wc23-panel':'wk-commerce-panel';dialog.className='wk-commerce';dialog.dir=document.documentElement.dir;
  dialog.innerHTML=`<header><button type="button" data-close aria-label="${esc(t('close'))}">${icon('back')}</button><h2>${esc(t(kind))}</h2><span></span></header><div class="wk-commerce-body"><p role="status">${esc(t('loading'))}</p></div>`;
  const state={dialog,kind,country:billCountry(),data:null,view:'packs',selected:null,intent:null,order:null,busy:false,timer:0,transfer:null,quote:null,transferIntent:null,planIntent:null,seq:0};
  const cleanup=()=>{clearTimeout(state.timer);window.removeEventListener('focus',onFocus);dialog.remove();if(current===dialog){current=null;currentState=null}};
  const onFocus=()=>{if(state.order)void check(state,true)};dialog.addEventListener('close',cleanup,{once:true});dialog.querySelector('[data-close]').onclick=()=>dialog.close();window.addEventListener('focus',onFocus);
  document.body.append(dialog);dialog.showModal();current=dialog;currentState=state;void load(state);return state;
 }
 function message(state,text){const node=state.dialog.querySelector('[role=status]');if(node)node.textContent=text}
 function countrySelect(state){const codes=[...new Set([state.country,'AF','DE','AT','FR','NL','IT','ES','BE','US','GB','CA','AU','PK','IN','AE','TR','IR','SE','CH','NO','DK','SA'])];let names;try{names=new Intl.DisplayNames([document.documentElement.lang],{type:'region'})}catch{}
  return `<label class="wk-billing-country"><span>${esc(t('country'))}</span><select data-country>${codes.map(code=>`<option value="${code}"${state.country===code?' selected':''}>${esc(names?.of(code)||code)}</option>`).join('')}</select></label>`;
 }
 async function load(state){const seq=++state.seq;try{const [data,wallet]=await Promise.all([call('/api/app/commerce?country='+state.country),call('/api/wallet')]);if(!state.dialog.isConnected||seq!==state.seq)return;state.data=data;state.wallet=wallet;paint(state)}catch{if(state.dialog.isConnected)state.dialog.querySelector('.wk-commerce-body').innerHTML=`<p role="status">${esc(t('error'))}</p><button data-retry>${esc(t('retry'))}</button>`;state.dialog.querySelector('[data-retry]')?.addEventListener('click',()=>load(state))}}
 function paint(state){
  if(!state.dialog.isConnected||!state.data)return;const data=state.data,plans=state.kind==='subscription';
  let html=plans?`<section class="wk-member-hero">${icon('subscription')}<h3>${esc(t('subscription'))}</h3><p>${esc(t('features'))}</p>${data.entitlement?.until?`<small>${esc(t('remaining'))} ${esc(new Date(data.entitlement.until*1000).toLocaleDateString(document.documentElement.lang))}</small>`:''}</section>`:`<section class="wk-balance"><div><small>${esc(t('balance'))}</small><strong>${esc(number(data.balance))}</strong><span>${esc(t('coins'))}</span></div>${icon('coins')}</section><nav class="wk-wallet-tabs">${['packs','transfer','history'].map(view=>`<button type="button" data-view="${view}" aria-pressed="${state.view===view}">${icon(view==='packs'?'coins':view)}<span>${esc(t(view))}</span></button>`).join('')}</nav>`;
  if(plans||state.view==='packs'){
   html+=countrySelect(state)+`<small class="wk-commerce-hint">${esc(t('countryNote'))}</small><div class="wk-pack-grid${plans?' wk-plan-grid':''}">${(plans?data.plans:data.packs).map(item=>`<button type="button" data-sku="${esc(item.sku)}" aria-pressed="${state.selected?.sku===item.sku}">${icon(plans?'subscription':'coins')}<b>${esc(plans?t(item.months===1?'one':item.months===6?'six':'year'):number(item.coins))}</b>${plans?'':`<small>${esc(t('coins'))}</small>`}<strong>${esc(money(item.amount,data.currency))}</strong>${plans?`<small>${esc(number({1:50,6:250,12:450}[item.months]))} ${esc(t('coins'))}</small>`:''}</button>`).join('')}</div>${plans?`<p class="wk-commerce-hint">${esc(t('noRenew'))}</p>`:''}`;
   if(state.selected){html+=`<section class="wk-payment-choice"><h3>${esc(t('buy'))}</h3>${data.methods.filter(method=>method.id==='stripe'&&method.enabled).map(method=>`<button type="button" data-provider="${method.id}">${esc(t(method.id))}</button>`).join('')}${!data.methods.some(method=>method.id==='stripe'&&method.enabled)?`<p>${esc(t('unavailable'))}</p>`:`<small>${esc(t('methods'))}</small>`}${plans?`<button type="button" data-coins>${icon('coins')}${esc(t('coinPay'))} · ${number({1:50,6:250,12:450}[state.selected.months])}</button><div data-confirm-plan></div>`:''}</section>`}
  }else if(state.view==='transfer')html+=`<form class="wk-transfer-form"><label>${esc(t('recipient'))}<input name="uid" inputmode="numeric" pattern="[0-9]{1,16}" required autocomplete="off" placeholder="77777777"></label><label>${esc(t('amount'))}<input name="coins" inputmode="decimal" required min="1" max="5000" type="number" step="0.01"></label><button type="submit">${esc(t('preview'))}</button></form><div data-transfer-preview></div>`;
  else html+=`<div class="wk-wallet-history">${state.wallet.history.map(item=>`<article><div><b dir="auto">${esc(item.other?.name||t(item.kind==='purchase'?'subscription':item.kind==='transfer'?'transfer':'coins'))}</b><small>${esc(new Date(item.ts*1000).toLocaleString(document.documentElement.lang))}</small></div><strong dir="ltr">${Number(item.coins)>0?'+':''}${esc(number(item.coins))}</strong></article>`).join('')||`<p>${esc(t('empty'))}</p>`}</div>`;
  html+='<p role="status" aria-live="polite"></p><div data-order></div>';
  if(!plans)html+=`<button type="button" class="wk-membership-link" data-sub>${icon('subscription')}${esc(t('subscription'))}</button>`;
  const body=state.dialog.querySelector('.wk-commerce-body');body.innerHTML=html;
  body.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{state.view=button.dataset.view;paint(state)});
  body.querySelectorAll('[data-sku]').forEach(button=>button.onclick=()=>{if(state.busy)return;state.selected=[...data.packs,...data.plans].find(item=>item.sku===button.dataset.sku);state.intent=null;state.planIntent=null;paint(state)});
  body.querySelector('[data-country]')?.addEventListener('change',event=>{if(state.busy)return;state.country=event.target.value;localStorage.setItem('wk_billing_country',state.country);state.selected=null;state.intent=null;void load(state)});
  body.querySelectorAll('[data-provider]').forEach(button=>button.onclick=()=>checkout(state,button.dataset.provider));
  body.querySelector('[data-coins]')?.addEventListener('click',()=>confirmPlan(state));
  body.querySelector('[data-sub]')?.addEventListener('click',()=>shell('subscription'));
  body.querySelector('form')?.addEventListener('submit',event=>{event.preventDefault();void previewTransfer(state,event.target)});
  if(state.order)renderOrder(state);
 }
 async function checkout(state,provider){if(state.busy)return;state.busy=true;message(state,t('loading'));
  try{if(!state.intent||state.intent.provider!==provider||state.intent.sku!==state.selected.sku)state.intent={provider,sku:state.selected.sku,country:state.country,client_key:key()};const result=await call('/api/app/commerce/orders',state.intent);if(!state.dialog.isConnected)return;state.order=result;renderOrder(state);
   if(result.url){const url=new URL(result.url);if(url.protocol!=='https:'||!['checkout.stripe.com'].includes(url.hostname))throw Error('bad_checkout');await WAKHAN_NATIVE_N1.openPayment(result.url)}
   queue(state);message(state,'');
  }catch{message(state,t('error'))}finally{state.busy=false}}
 function renderOrder(state){const node=state.dialog.querySelector('[data-order]');if(!node)return;const order=state.order;node.innerHTML=`<section class="wk-payment-status"><b>${esc(t(order.state==='paid'?'paid':order.state==='paid_review'?'review':'pending'))}</b><small>${esc(money(order.amount,order.currency))}</small>${!['paid','paid_review'].includes(order.state)?`<button type="button" data-check>${esc(t('check'))}</button>`:''}</section>`;node.querySelector('[data-check]')?.addEventListener('click',()=>check(state,true))}
 function queue(state){clearTimeout(state.timer);if(state.dialog.isConnected&&state.order&&!['paid','paid_review'].includes(state.order.state))state.timer=setTimeout(()=>check(state),5000)}
 async function check(state,capture=false){if(!state.order||state.checking||!state.dialog.isConnected)return;state.checking=true;try{const result=await call('/api/app/commerce/orders/'+state.order.token+(capture?'/capture':''),capture?{}:undefined);state.order=result;state.data.balance=result.balance;state.data.entitlement=result.entitlement;if(result.state==='paid')paint(state);else renderOrder(state)}catch{if(capture)message(state,t('pending'))}finally{state.checking=false;queue(state)}}
 function confirmPlan(state){if(state.busy)return;const selected=state.selected;state.planIntent||={sku:selected.sku,country:state.country,client_key:key()};const node=state.dialog.querySelector('[data-confirm-plan]');node.innerHTML=`<p>${esc(t(selected.months===1?'one':selected.months===6?'six':'year'))} · ${number({1:50,6:250,12:450}[selected.months])} ${esc(t('coins'))}</p><button type="button" data-confirm>${esc(t('confirm'))}</button>`;node.querySelector('button').onclick=async event=>{if(state.busy)return;state.busy=true;event.target.disabled=true;try{const result=await call('/api/app/commerce/buy-with-coins',state.planIntent);state.data.balance=result.balance;state.data.entitlement=result.entitlement;state.selected=null;paint(state);message(state,t('paid'))}catch(error){message(state,t(error.message==='insufficient_coins'?'insufficient':'error'));event.target.disabled=false}finally{state.busy=false}}}
 async function previewTransfer(state,form){if(state.busy)return;state.busy=true;try{const uid=Number(form.elements.uid.value),coins=form.elements.coins.value;const quote=await call('/api/wallet',{action:'transfer_quote',uid,coins});if(!state.dialog.isConnected)return;state.quote=quote;state.transferIntent={action:'transfer',token:quote.token,client_key:key()};const node=state.dialog.querySelector('[data-transfer-preview]');node.innerHTML=`<section class="wk-transfer-confirm"><b dir="auto">${esc(quote.recipient?.name)}</b><strong>${esc(number(quote.coins))} ${esc(t('coins'))}</strong><button type="button">${esc(t('confirm'))}</button></section>`;node.querySelector('button').onclick=()=>transfer(state)}catch(error){message(state,t(error.message==='recipient_not_found'?'recipientError':'error'))}finally{state.busy=false}}
 async function transfer(state){if(state.busy)return;state.busy=true;try{const result=await call('/api/wallet',state.transferIntent);state.data.balance=result.balance;state.transferIntent=null;state.quote=null;paint(state);message(state,t('sent'))}catch(error){message(state,t(error.message==='insufficient_coins'?'insufficient':'error'))}finally{state.busy=false}}
 const previousGo=go;go=function(tab,sub){if(tab==='s'){shell('subscription');return}return previousGo.apply(this,arguments)};
 wc23Open=function(){return shell('wallet')};wc23Close=close;
 const receiptOpen=wfOpen;
 wfOpen=async function(){
  if(!WF.summary?.allowed)return;
  WF.open=true;wfShell(`<div class="wk-finance-tabs"><button type="button" data-online aria-pressed="true">${esc(t('online'))}</button><button type="button" data-receipts>${esc(t('receipt'))}</button></div><div data-online-orders><p role="status">${esc(t('loading'))}</p></div>`);
  const panel=document.getElementById('wm-finance-panel');panel.querySelector('[data-receipts]').onclick=()=>receiptOpen();
  try{const result=await call('/api/app/commerce/admin/orders');if(!panel.isConnected)return;const container=panel.querySelector('[data-online-orders]');
   container.innerHTML=`<div class="wk-finance-filters"><input type="search" data-query placeholder="${esc(t('recipient'))}"><select data-state><option value="all">${esc(t('all'))}</option><option value="pending">${esc(t('wait'))}</option><option value="paid">${esc(t('done'))}</option></select></div><div data-list></div>`;
   function draw(){const query=container.querySelector('[data-query]').value.trim().toLowerCase(),status=container.querySelector('[data-state]').value;const rows=result.orders.filter(order=>(status==='all'||(status==='pending'?['created','pending'].includes(order.state):order.state==='paid'))&&(!query||[order.buyer?.name,order.buyer?.public_id,order.token].some(value=>String(value||'').toLowerCase().includes(query))));container.querySelector('[data-list]').innerHTML=rows.map(order=>`<article class="wk-online-order"><div><b dir="auto">${esc(order.buyer?.name)}</b><small>ID: ${esc(order.buyer?.public_id||'—')}</small><small>${esc(order.coins?number(order.coins)+' '+t('coins'):t(order.months===1?'one':order.months===6?'six':'year'))}</small></div><div><strong>${esc(money(order.amount,order.currency))}</strong><small>${esc(t(order.state==='paid'?'done':order.state==='paid_review'?'review':'wait'))}</small><small>${esc(new Date(order.created*1000).toLocaleDateString(document.documentElement.lang))}</small></div></article>`).join('')||`<p class="wk-commerce-hint">${esc(t('none'))}</p>`}
   container.querySelector('[data-query]').oninput=draw;container.querySelector('[data-state]').onchange=draw;draw();
  }catch{if(panel.isConnected)panel.querySelector('[data-online-orders]').textContent=t('error')}
 };
 window.WakhanCommerce={open:kind=>shell(kind==='subscription'?'subscription':'wallet'),close,resume(){if(currentState?.order)void check(currentState,true)}};
})();

